export default [{"id":171,"question":"أبي رجلٌ أُمِّيٌّ لا يقرأ ولا يكتب، ويُحافظ على الصلاة في المساجد، ولكنه لا يُجيد قراءة الفاتحة جيدًا، فهل تُقبل صلواته؟","title":"ما حكم صلاة من لا يحسن قراءة الفاتحة؟","answer":"الجواب: علِّموه، يتعلَّم، وإذا عجز فصلاته صحيحة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لكن يُعلّم الفاتحة ويجتهد في التعلم، والله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ، فيُعلِّمه أولاده وغيرهم، يتعلم ويسأل ربَّه التوفيق حتى يحفظ الفاتحة ويُجيدها.\nجاء رجلٌ إلى النبي ﷺ، فشكى إليه أنه لا يستطيع شيئًا من القرآن، فقال له النبيُّ ﷺ قل: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، يقوم هذا مقام الفاتحة لمَن عجز، فمَن عجز عنها يأتي بهذا التَّسبيح، ولكن يلزمه تعلّمها؛ لأنها ركنُ الصلاة، وهي بحمد الله ميسرة، وهي أعظم سورةٍ في كتاب الله ، فالواجب تعلّمها، فإذا لم يتيسر أن يحفظها فإنه يقرأ ما ذكره النبيُّ ﷺ: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله في حال القيام، في حال القراءة، ولكن عليه أن يجتهد في أن يتعلم الفاتحة وما تيسر معها.","link":"https://binbaz.org.sa/fatwas/3711/ما-حكم-صلاة-من-لا-يحسن-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0167.mp3","categories":["القراءة في الصلاة"]},{"id":221,"question":"ما الحكم في جهر الإمام بقراءة سورةٍ واحدةٍ في ركعتين متتاليتين في فرضٍ واحدٍ؟","title":"حكم تكرار السورة في الركعتين بالفريضة","answer":"الجواب: إذا قرأ الإمامُ سورةً واحدةً في ركعتين بعد الفاتحة ما نعلم فيه شيئًا، قد رواه أبو داود بإسنادٍ لا بأس به عن النبيِّ ﷺ: أنه قرأ \"إذا زلزلت\" في الركعتين جميعًا، فلا بأس أن يقرأ سورةً في الركعتين، مثل: \"إذا زلزلت\" و\"الشمس وضحاها\" يُكررها في الركعتين، أو غير ذلك، أو آيةً يُكررها، أو آيات، لا نعلم في ذلك بأسًا، فقد وقع منه هذا وهذا عليه الصلاة والسلام، لكن إذا قرأ في الغالب آيةً أخرى أو سورةً يكون أفضل؛ حتى تكون الفائدةُ أكثر، ولو كرر فلا بأس.","link":"https://binbaz.org.sa/fatwas/4061/حكم-تكرار-السورة-في-الركعتين-بالفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0228.mp3","categories":["القراءة في الصلاة"]},{"id":312,"question":"أنا شابٌّ أُصبت بمرضٍ عصبيٍّ، وجاءتني أيام لا أستطيع فيها النّطق بالفاتحة، وقد بعثتُ أحد الإخوان إلى أحد المشايخ فأجابه بجواز الصلاة بقدر الركعة دون قراءةٍ، فما حكم ذلك؟","title":"ما حكم صلاة العاجز عن القراءة؟","answer":"الجواب: نعم، ربنا يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، فإذا أُصيب المسلم بما يمنعه من القراءة؛ صحَّت صلاته، يقف مقدار الفاتحة وما زاد عليها ويكفيه، وإن استطاع أن يأتي بالتَّسبيح والتَّحميد والتَّهليل والتَّكبير وجب ذلك؛ لأنَّ الرسول ﷺ شكى إليه مَن عجز عن القراءة، فأمره بالتَّسبيح والتَّهليل والتَّكبير: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، أو ما تيسر من ذلك، الذي يستطيع من هذا، حتى يستطيع قراءة الفاتحة، المقصود: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/4317/ما-حكم-صلاة-العاجز-عن-القراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0362.mp3","categories":["القراءة في الصلاة"]},{"id":706,"question":"ما حكم التَّنكيس في السور، مثل: أن يقرأ في الركعة الأولى آخر آل عمران، وفي الركعة الثانية آخر سورة البقرة؟","title":"ما حكم التنكيس في قراءة القرآن في الصلاة؟","answer":"الجواب: لا حرج في هذا؛ لأنَّ ترتيب السور اجتهادٌ ومُستحبٌّ، فلو قرأ في الأولى آخر سورة آل عمران، وفي الثانية آخر سورة البقرة فلا حرج، لكن الأفضل العكس: أن يقرأ سورة البقرة في الأولى وآل عمران في الثانية، وهكذا لو قرأ قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص] في الأولى، وقرأ تَبَّتْ يَدَا [المسد] في الثانية، لا حرج، لكن الأفضل العكس، الأفضل أن يُقدِّم ما قُدّم في القرآن، ويُؤخِّر ما أُخِّر في الثانية، هذا هو الأفضل، على ترتيب المصحف، كما رتَّبه الصحابةُ  باجتهادهم.","link":"https://binbaz.org.sa/fatwas/20582/ما-حكم-التنكيس-في-قراءة-القران-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0535فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["القراءة في الصلاة","القرآن وعلومه"]},{"id":709,"question":"صلى إمامٌ بجماعةٍ وسها عن قراءة الفاتحة، وهي ركنٌ من أركان الصلاة، ماذا يعمل؟","title":"ما يعمل الإمام إذا سها عن قراءة الفاتحة؟","answer":"الجواب: يأتي بركعةٍ، إذا انتهى عندها ولم ينتبه إلا بعد تمام الركعة يأتي بركعةٍ أخرى.........، ويُصلي ركعةً زائدةً، ويسجد للسَّهو، ويُنبه مَن خلفه أن يقوموا ويُتابعوه؛ لأنه أخلَّ بالصلاة، أخلَّ بهذه الركعة التي ترك فيها الفاتحة سهوًا.\nس: لكن تذكَّر في الركعة الأولى؟\nالشيخ: يُعيد، يأتي بتلك الركعة، يقف لا يركع حتى يأتي بها ثم يركع.","link":"https://binbaz.org.sa/fatwas/20578/ما-يعمل-الامام-اذا-سها-عن-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0531فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["القراءة في الصلاة"]},{"id":1152,"question":"ما حكم قراءة الفاتحة في صلاة الجهر؟ أرجو منكم الإجابة الشَّافية؛ لأن العلماء اختلفوا في هذا الأمر. لعله يقصد بالنسبة للمأموم.","title":"ما حكمالفاتحة للمأموم في صلاة الجهر؟","answer":"الجواب:\nالعلماء اختلفوا في قراءة المأموم خلف الإمام على أقوالٍ ثلاثةٍ:\nأحدها: وجوب القراءة على المأموم، الفاتحة مطلقًا، في السر والجهر.\nالثاني: عدم الوجوب مطلقًا، وهو قول الجمهور.\nوالقول الثالث: التَّوسط، وأنها تجب في السرية دون الجهرية.\nوالأرجح وجوبها في الجميع، لكن إذا تركها جهلًا، أو عن اجتهادٍ، وأنه يرى قول مَن قال بأنها لا تجب؛ فلا حرج عليه، أو لم يُدركها مع الإمام: بأن جاء والإمام راكع؛ أجزأه ذلك للعذر، كما فعل أبو بكرة، فإنه جاء والنبي راكعٌ عليه الصلاة والسلام، فدخل في الصفِّ، ولم يأمره النبيُّ بالإعادة، بقضاء الركعة، هذا هو أرجح الأقوال؛ لقوله ﷺ: لا صلاةَ لمن لم يقرأ بفاتحة الكتاب، وهذا عام، وقوله ﷺ: لعلكم تقرؤون خلف إمامكم، قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنَّه لا صلاةَ لمن لم يقرأ بها، وهذا صريحٌ يعمّ الجهرية والسرية، وهو حديثٌ جيدٌ، رواه أحمد وجماعةٌ من أهل السنن، ولا بأس به.\nهذا هو أعدل الأقوال: وجوبها مطلقًا في الجهرية والسرية، لكن ليس ذلك مثل وجوبها على الإمام والمنفرد، لا، بل أقلّ من ذلك، ولهذا لو سها عنها، أو تركها تقليدًا أو اجتهادًا، أو لم يُدرك إلا الركوع؛ أجزأه ذلك، ووجوبها مُخفَّفٌ في حقِّه، كوجوب \"سبحان ربي الأعلى\" و\"سبحان ربي العظيم\" في الركوع والسجود، \"رب اغفر لي\" بين السَّجدتين؛ تسقط بالسَّهو.","link":"https://binbaz.org.sa/fatwas/21211/ما-حكم-الفاتحة-للماموم-في-صلاة-الجهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1007ما حكم قراءة الفاتحة في صلاة الجهرية بالنسبة للمؤموم؟ ابن باز.mp3","categories":["القراءة في الصلاة"]},{"id":1474,"question":"بعض الناس يُنكر على الإمام إذا أطال القراءة في بعض الصَّلوات: كالفجر أو العشاء؟","title":"ما السُّنَّة في قراءة صلاتي الفجر والعشاء؟","answer":"الجواب:\nالإمام عليه أن يتحرَّى السنة، والسنة ما فيها إطالة، والرسول ﷺ أرحم الناس.\nس: وصلاة الفجر؟\nج: يُطَوِّل فيها بعض الشيء، فيقرأ مثلًا: ق، الطور، يعني الثُّمُن وما حوله.\nس: التَّخفيف هنا تخفيفٌ نسبيٌّ؟\nج: نعم، تبع هدي النبي ﷺ، هدي النبي هو المُفَسِّر.\nس: لابن القيم كلام في \"زاد المعاد\" أنكر فيه وقال: بعض الناس ما يحفظون الدين.. أفَتَّانٌ أنت يا معاذ! هل كلامه صحيح؟\nج: النبي أنكر على معاذ لما طوَّل، وكان يقرأ بالبقرة... طويل.\nس: هل من السنة قراءة سورة الزلزلة في صلاة الفجر في الركعتين؟\nج: إذا قرأ بها بعض الأحيان من باب إحياء السنة، أو من باب الجواز؛لا بأس، ولكن السنة الإطالة في الفجر، هذا الثابت من فعل النبي ﷺ عند أبي ذرٍّ، ولا بأس بسنده.","link":"https://binbaz.org.sa/fatwas/21572/ما-السنة-في-قراءة-صلاتي-الفجر-والعشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السنة في القراءة في صلاة الفجر والعشاء.mp3","categories":["القراءة في الصلاة"]},{"id":1479,"question":"التَّخفيف بالنسبة للإمام في الصلاة؟","title":"ما ضابط تخفيف القراءة في صلاة الجماعة؟","answer":"الجواب:\nلا يُخلّ بالصلاة، التخفيف الذي يناسب ولا يضرّ المصلين ينفع المرأةَ التي ولدها يصيح، أو ينفع الإنسان الذي عنده حاجة شديدة، فالتخفيف نسبي، فعلى الإمام أن يتحرى فيه فعلَ النبي ﷺ في صلواته، ويُوافق فعله ﷺ.\nس: هل يكون باستمرارية أم يكون تارةً وتارةً؟\nج: يلزم سنة النبي ﷺ إلا إذا عرض عارضٌ.","link":"https://binbaz.org.sa/fatwas/21577/ما-ضابط-تخفيف-القراءة-في-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التخفيف في القراءة في الصلاة.mp3","categories":["القراءة في الصلاة"]},{"id":2269,"question":"المأموم في الركعتين الأخيرتين من صلاة العصر أو العشاء، أو في الركعة الأخيرة من صلاة المغرب، الأفضل له إذا أطال الإمامُ أن يسكت بعد الفاتحة أم يقرأ؟","title":"ماذا يُفعل لو أطال الإمام في الثالثة والرابعة؟","answer":"الجواب:\nإن قرأ لا بأس، والأفضل -والله أعلم- هو القراءة، فقد كان الصديقُ  يقرأ بعد الثالثة في المغرب: رَبَّنَا لَا تُزِغْ قُلُوبَنَا [آل عمران:8]، المقصود: أنه إذا سكت إمامُه ولم يُكبِّر يقرأ ما تيسر.\nس: لكن الأفضل للإمام أن يُكبّر راكعًا؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/22392/ماذا-يفعل-لو-اطال-الامام-في-الثالثة-والرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يقرأ المأموم بعد الفاتحة في الركعتين الأخيرتين من صلاة العصر أو العشاء.mp3","categories":["القراءة في الصلاة"]},{"id":2344,"question":"متى ينقطع التكبيرُ في العيد؟","title":"متى ينقطع التكبيرُ في العيد؟","answer":"الجواب:\nعند انتهاء الخطبة.\nس: بالنسبة للمُصلِّين: يُكبِّرون من الخروج من بيوتهم إلى المسجد؟\nج: يُكبّرون إلى انتهاء الخطبة.","link":"https://binbaz.org.sa/fatwas/22469/متى-ينقطع-التكبير-في-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى ينقطع التكبيرُ في العيد.mp3","categories":["صلاة العيدين","القراءة في الصلاة","الأدعية والأذكار"]},{"id":2400,"question":"القراءة بالنسبة للنساء في الجهرية؟","title":"حكم جهر النساء بالقراءة في الصلاة","answer":"الجواب:\nتجهر حتى تُسْمِع النساء؛ لأنها تجهر مثل الرجل.\nس: ولو كان في رجال في القُرْب؟\nالشيخ: تجهر بقدر المصليات معها؛ حتى تسمع المصليات حتى يستفدن. والأمر سهل إذا كان صوتها بقدر النساء فالحمد لله، في المغرب والعشاء والفجر أو في التراويح.","link":"https://binbaz.org.sa/fatwas/22525/حكم-جهر-النساء-بالقراءة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القراءة للنساء في الصلاة الجهرية.mp3","categories":["القراءة في الصلاة"]},{"id":2459,"question":"هل له أن يجهر بالقراءة في صلاة الضحى ليسمع نفسه؟","title":"حكم الجهر بالقراءة في الصلاة ليُسمع نفسه","answer":"الجواب:\nنعم، في جميع الصلوات يقرأ قراءة يُسمع فيها نفسه.\nس: وكذا لو قضى الوتر؟\nالشيخ: وفي الوتر كذلك.\nس: صلاة الضحى يصليها في بيته أو في عمله؟\nالشيخ: في بيته أفضل، وإذا ما تيسر وصلّاها في عمله؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/22588/حكم-الجهر-بالقراءة-في-الصلاة-ليسمع-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجهر بالقراءة في الصلاة ليسمع نفسه.mp3","categories":["القراءة في الصلاة"]},{"id":3249,"question":"قراءة السورة بعد الفاتحة يُبَسْمِل لها أو يِستَعِيذ؟","title":"هل يُستعاذ أم يُبَسْمَل للسورة بعد الفاتحة؟","answer":"الجواب: إن كانت سورة يُسمّي، وإن كانت ما هي سورة فلا حاجة؛ الاستعاذة الأولى تكفي، وإن استعاذ فلا حرج، ولكن الاستعاذة في أول الصلاة قبل الفاتحة كافٍ، والتسمية في الفاتحة كافٍ، لكن السورة التي بعدها يُسمّي لها، وإن كانت ما هي بسورة؛ آيات؛ كفى أن يقرأها من دون استعاذة، الاستعاذة الأولى كافية.","link":"https://binbaz.org.sa/fatwas/23413/هل-يستعاذ-ام-يبسمل-للسورة-بعد-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يستعيذ أو يبسمل عند قراءة السورة بعد الفاتحة.mp3","categories":["القراءة في الصلاة"]},{"id":3268,"question":"رجل أخطأ في سورة الفاتحة من غير قصد؟","title":"حكم الخطأ في قراءة الفاتحة مِنْ غير قصد","answer":"الجواب: إن كان الخطأ خفيفًا لا يُغَيِّر المعنى ما يضر، وإن كان يُغَيِّر المعنى يُنَبَّه حتى يعيد الكلمة، يُنَبَّه الإمام حتى يعيدها، يقول صراط الذين أنعمتُ عليهم، أو إياكِ نعبد وإياك نستعين، يرد عليه حتى يعيدها.","link":"https://binbaz.org.sa/fatwas/23432/حكم-الخطا-في-قراءة-الفاتحة-من-غير-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الخطأ في سورة الفاتحة من غير قصد.mp3","categories":["القراءة في الصلاة"]},{"id":3358,"question":"بعض الناس يقول: من المشقة أن تُقرأ السجدة والإنسان في (فجر) يوم الجمعة، هل يُقبل كلامه؟","title":"حكم مَن يَعُدُّ قراءة السجدة والإنسان شاقة؟","answer":"الجواب: لا، المقصود بالتخفيف: تخفيف النبي ﷺ، هو القدوة، كان يقول أنس: أتم صلاة، وأخف صلاة (ما رأيت إمامًا أخف صلاة، ولا أتم صلاة من النبي ﷺ)، يُتأسى به في هذا عليه الصلاة والسلام، هو الذي يُعِلّم الناس عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23524/حكم-من-يعد-قراءة-السجدة-والانسان-شاقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من المشقة في الصلاة أن تقرأ الإنسان والسجدة في يوم الجمعة.mp3","categories":["القراءة في الصلاة"]},{"id":3360,"question":"هل يقسم السجدة في صلاة الفجر بين الركعتين؟","title":"هل تُقرأ السجدة في صلاة الفجر في ركعتين؟","answer":"الجواب: لا، السنة أن يقرأ السجدة في الأولى، والإنسان في الثانية.\nس: هل يقال إنه مبتدع؟\nالشيخ: لا، يُقال خالف السنة، لكن البدعة ما لها لزوم، يقال: خالف السنة.","link":"https://binbaz.org.sa/fatwas/23526/هل-تقرا-السجدة-في-صلاة-الفجر-في-ركعتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقرأ السجدة في صلاة الفجر في الركعتين.mp3","categories":["القراءة في الصلاة"]},{"id":3560,"question":"قراءة سور يسيرة في الثالثة والرابعة بعد الفاتحة؟","title":"حكم القراءة بعد الفاتحة في الثالثة والرابعة","answer":"الجواب: الفاتحة بس، إلا الظهر إذا قرأ بعض الأحيان زيادة في الثالثة والرابعة فقد جاء في حديث أبي سعيد ما يدل على هذا.\nس: المغرب ما ثبت عن أبي بكر الصديق..\nالشيخ: ورد عن الصديق  أنه قرأ: رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا [آل عمران: 8] في الثالثة.","link":"https://binbaz.org.sa/fatwas/23742/حكم-القراءة-بعد-الفاتحة-في-الثالثة-والرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قراءة سور يسيرة في الثالثة والرابعة بعد الفاتحة.mp3","categories":["القراءة في الصلاة"]},{"id":3564,"question":"الصحيح أن قراءة الفاتحة فرض على المأموم؟","title":"هل قراءة الفاتحة واجبة على المأموم؟","answer":"الجواب: نعم، المأموم يقرأها سرًّا، لكنها واجبة في حق المأموم، إذا سقطت جهلاً أو نسيانًا سقطت، أو تركها جهلاً أو نسيانًا، أو جاء والإمام راكع سقطت عنه؛ لحديث: لعلكم تقرؤون خلف إمامكم قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها. وفي حديث أبي بكرة لما جاء والنبي راكع لم يأمره بقضاء الركعة، واجبة في حق المأموم، تسقط بالجهل والنسيان.\nس: في السرية والجهرية سواء؟\nالشيخ: نعم، لكن تسقط بالجهل والنسيان في حق المأموم، والعجز إذا جاء والإمام راكع.","link":"https://binbaz.org.sa/fatwas/23746/هل-قراءة-الفاتحة-واجبة-على-الماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قراءة الفاتحة للمأموم.mp3","categories":["القراءة في الصلاة"]},{"id":3570,"question":"ولو جهر بالبسملة أحيانًا يكره؟","title":"هل يكره الجهر بالبسملة في الصلاة؟","answer":"الجواب: لا يضر، لكن خلاف السنة، ولهذا جاء عن أبي هريرة أن النبي ﷺ كان يجهر بها، ولعل هذا بعض الأحيان.","link":"https://binbaz.org.sa/fatwas/23752/هل-يكره-الجهر-بالبسملة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكره الجهر بالبسملة في الصلاة.mp3","categories":["القراءة في الصلاة"]},{"id":3696,"question":"إعادة قراءة الفاتحة في الركوع الثاني (للكسوف)، هل عليه دليل؟","title":"حكم قراءة الفاتحة بعد الركوع الثاني للكسوف","answer":"الجواب: لأنها ركعة، الركعة الثانية بمثابة ركعة مستقلة يقرأ فيها الفاتحة؛ لأنه إذا قرأ وركع ثم رفع صارت بمنزلة ركعة ثانية؛ فيقرأ الفاتحة ويقرأ بعدها، وهذا الذي عليه عمل أهل العلم.","link":"https://binbaz.org.sa/fatwas/23885/حكم-قراءة-الفاتحة-بعد-الركوع-الثاني-للكسوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إعادة قراءة الفاتحة في الركوع الثاني.mp3","categories":["القراءة في الصلاة"]},{"id":4495,"question":"الإمام الذي يستمرُّ على القراءة من قصار السور؟","title":"حكم اقتصار الإمام علىقصار السور","answer":"الجواب: يُعلَّم السنة.\nس: لكن إذا أصرَّ؟\nج: يُعلَّم السنة ولو أصرَّ، أفضلية، ما هي بواجبٍ.","link":"https://binbaz.org.sa/fatwas/24775/حكم-اقتصار-الامام-على-قصار-السور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإمام الذي يستمرُّ على القراءة من قصار السور.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":4552,"question":"الاستعاذة في كل ركعةٍ من الصلاة؟","title":"حكم الاستعاذة والبسملة في كل ركعة بالصلاة","answer":"الجواب: في خلاف بين أهل العلم، السنة في الأولى فقط، أما الركعات الأخرى فيكفي، تكفي التسمية إن شاء الله، هذا هو الأرجح.  وإن استعاذ فلا بأس، إن استعاذ في الركعات الأخرى فلا بأس، ليس هناك مانع، لكن بعض الصلاة تشبه... القراءة واحدة؛ فإذا استعاذ في أولها، هذا هو الأمر عند أهل العلم؛ تكفيه الاستعاذة في الركعة الأولى، وإن استعاذ في الثانية والثالثة لا بأس، الأمر واسع إن شاء؛ لعموم الآية: فَإِذَا قَرَأْتَ الْقُرْآنَ [النحل:98].\nس: البسملة كذلك؟\nج: لا، التسمية يُكررها التي في أول سورة، إذا كان يبدأ سورةً يُكرر التَّسمية، إلا عند براءة.","link":"https://binbaz.org.sa/fatwas/24833/حكم-الاستعاذة-والبسملة-في-كل-ركعة-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الاستعاذة والبسملة في كل ركعةٍ من الصلاة.mp3","categories":["القراءة في الصلاة"]},{"id":4554,"question":"إذا نسي الفاتحة في إحدى الركعات السرية، ثم جاء بركعةٍ خامسةٍ؟","title":"حكم نسيان المأموم الفاتحة في صلاة سرية","answer":"الجواب: لا ..... تسقط، لكن إذا كان جاء بها عن اجتهادٍ وعن خروجٍ من الخلاف تصحّ إن شاء الله؛ لأنَّ بعض أهل العلم يرى أنَّ عليه أن يأتي بركعةٍ، لكن الصواب أنه لا يلزمه، يُسلم مع الإمام وتسقط عنه.\nس: الجمهور ما يُوجبونها حتى في السرية؟\nج: حتى في السرية نعم.\nس: يرونها مُستحبَّة؟\nج: يرونها مُستحبَّة.\nس: ما تشملها الآية؟\nج: أما حديث: مَن كان له إمامٌ فقراءته له قراءة فهو حديثٌ ضعيفٌ كما قال المؤلف ..... هذا الحديث ضعيف: مَن كان له إمام فقراءته له قراءة احتجَّ به الجمهور، لكنه ضعيف.","link":"https://binbaz.org.sa/fatwas/24836/حكم-نسيان-الماموم-الفاتحة-في-صلاة-سرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من نسي الفاتحة في إحدى الركعات السرية، ثم جاء بركعةٍ خامسةٍ.mp3","categories":["القراءة في الصلاة"]},{"id":4555,"question":"بعض الناس يتفاوتون في التأمين .....؟","title":"ما الصواب في نطق \"آمين\" في الصلاة؟","answer":"الجواب: لا، السنة المدّ: آمين.  وأما مَن قال: \"أمين\" لا، \"أمين\" ليس معناها: آمين.  السنة أن تمدَّها؛ لأن معناها: استجب يا ربنا.  كذلك \"آمّين\" ليس معناها هنا. الآمّين: القاصدين، آمّين المسجد الحرام.  فاللغات ثلاث: \"آمّين\" أي قاصدين.  و\"أمين\" بمعنى الأمانة. وأما \"آمين\" بالتَّخفيف فهذا معناه: استجب، وهي المرادة هنا.","link":"https://binbaz.org.sa/fatwas/24837/ما-الصواب-في-نطق-امين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القول في التأمين في الصلاة.mp3","categories":["القراءة في الصلاة"]},{"id":4556,"question":"إذا اقتصر على الفاتحة الإمام عمدًا؟","title":"حكم اقتصار الإمام على الفاتحة","answer":"الجواب: لا بأس، الواجب عند العلماء الفاتحة فقط، فإذا اقتصر عليها أجزأت، لكن ترك السنة.","link":"https://binbaz.org.sa/fatwas/24838/حكم-اقتصار-الامام-على-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اقتصار الإمام على الفاتحة.mp3","categories":["القراءة في الصلاة"]},{"id":4557,"question":"السكتة بين الفاتحة وبين السورة.....؟","title":"حكم السكتة بعد الفاتحة في الصلاة","answer":"الجواب: لا، لا، فيها خلاف، ولم يثبت فيها شيء؛ لأنَّ الفاتحة وسورة لم يثبت فيها شيء من جهة السكتة، وإنما ثبت عنه سكتتان عليه الصلاة والسلام: الأولى بعد الإحرام، وهذه ثابتة بالنص من حديث أبي هريرة وغيره، يقرأ فيها الاستفتاح، والسكتة الثانية على الأرجح بعد نهاية القراءة قبل الركوع يسكت قليلًا سكتةً لطيفةً، ثم يُكبِّر، لا يتصل التكبير بالقراءة، بل يفصل بين القراءة والتكبير، إذا أنهى القراءة سكت قليلًا ثم كبَّر.\nأما ما بعد الفاتحة فهذا فيه خلاف: جاء في بعض الروايات من رواية قتادة أن هناك سكتةً بعد الفاتحة، ولكن ليست ثابتةً، واختلف العلماء فيها: منهم مَن رأى أن يسكت بعد الفاتحة حتى يقرأ المأمومُ الفاتحة، ومنهم مَن لم ير ذلك، والأصل عدم شرعية السكتة بعد الفاتحة، هذا هو الأصل، ومَن سكت عملًا بمن قال بذلك من أهل العلم فلا بأس، الأمر في هذا واسع إن شاء الله.","link":"https://binbaz.org.sa/fatwas/24839/حكم-السكتة-بعد-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السكتة بين الفاتحة وما بعدها.mp3","categories":["القراءة في الصلاة"]},{"id":4558,"question":"الجمهور يُوجبون الفاتحة في السرية؟","title":"ما الصحيح في قراءة المأموم للفاتحة؟","answer":"الجواب: لا، الجمهور لا ..... مطلقًا، لا في السرية، ولا في الجهرية، ويحتجُّون بحديث: مَن كان له إمامٌ فقراءته له قراءة، لكنه ضعيف.\nس: يُوافقون الأحناف في هذا؟\nج: هو قول مالك وأبي حنيفة وأحمد، وانفرد الشافعي رحمه الله وجماعة منهم البخاري بأنها واجبة على المأموم مطلقًا، وهذا أصح، الشافعي والبخاري أصح، وجوبها مطلقًا، وقال قومٌ: تجب في السرية دون الجهرية، فالأقوال ثلاثة:\nوجوبها مطلقًا، وهو الأرجح.\nوجوبها في السرية دون الجهرية، وهو قول جماعة.\nوعدم وجوبها مطلقًا، وهو قول الأكثر؛ لحديث: مَن كان له إمامٌ فقراءته قراءة له، لكنه مثلما تقدَّم مُرسل ضعيف.\nس: أدلة الجمهور ما تتناول السرية: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا [الأعراف:204]؟\nج: لا، أدلتهم ضعيفة في هذا، استدلال ضعيف؛ ولهذا القول الصحيح والصواب أنها واجبة مطلقًا، ويليه القول بأنها واجبة في السرية دون الجهرية، أما القول بأنها لا تجب مطلقًا حتى في السرية فهذا ضعيفٌ مخالفٌ للأدلة.","link":"https://binbaz.org.sa/fatwas/24840/ما-الصحيح-في-قراءة-الماموم-للفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الفاتحة في الصلاة السرية للمأموم.mp3","categories":["القراءة في الصلاة"]},{"id":4559,"question":"القراءة في الثالثة والرابعة في العشاء بعد الفاتحة؟","title":"ما حكم القراءة في الأخيرتين بالصلاة الرباعية؟","answer":"الجواب: مثل الظهر والعصر، ما نعلم فيه يدل على خلاف ذلك، مثل: قراءة الظهر والعصر؛ الفاتحة.\nس: ما يقرأ في العصر في الثالثة والرابعة؟\nج: ظاهر السنة أنه ما يقرأ... إلا الفاتحة فقط.","link":"https://binbaz.org.sa/fatwas/24841/ما-حكم-القراءة-في-الاخيرتين-بالصلاة-الرباعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القراءة في الركعتين الأخيرتين في الصلاة الرباعية.mp3","categories":["القراءة في الصلاة"]},{"id":4560,"question":"القراءة في الصلاة بالتلفيق بين القراءات السبع في سورةٍ واحدةٍ؟","title":"حكم الجمع بين عدة قراءات في الصلاة؟","answer":"الجواب: الذي يظهر لي أنه لا ينبغي هذا، أنه يقرأ بقراءةٍ واحدةٍ فقط: إما كذا، وإلا كذا، ولكن ما دام المصحف الآن بين أيدي الناس فينبغي أن يقرأ بما بين أيدي الناس؛ حتى لا يقع المحذور من النزاع والخلاف.  أما إذا كان من باب التعليم يُعلِّمهم القراءات السبع، القراءات العشر؛ ما في بأس من باب التعليم، باب واسع.","link":"https://binbaz.org.sa/fatwas/24842/حكم-الجمع-بين-عدة-قراءات-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القراءة في الصلاة بالتلفيق بين القراءات السبع في سورةٍ واحدةٍ.mp3","categories":["القراءة في الصلاة"]},{"id":4612,"question":"\"وإذا أمَّن فأمِّنوا\" متى يكون تأمين المأمومين؟","title":"متى يكون تأمين المأمومين؟","answer":"الجواب: إذا شرع الإمامُ، إذا شرع في المقصود كله دعاء، يدعون جميعًا، هو دعا: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6]، الإمام دعا، وهم مُنصتون له، ثم إذا قال: وَلَا الضَّالِّينَ [الفاتحة:7] يقولون: \"آمين\" جميعًا؛ لأنَّ في الرواية الأخرى: فإذا قال: وَلَا الضَّالِّينَ فقولوا: آمين، فإن مَن وافق تأمينُه تأمينَ الملائكة غُفر له ما تقدَّم من ذنبه، المقصود أن يتَّفق تأمينُهم مع تأمين الملائكة، ويكونوا كلهم مُؤَمِّنين.","link":"https://binbaz.org.sa/fatwas/24901/متى-يكون-تامين-المامومين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون تأمين المأمومين.mp3","categories":["القراءة في الصلاة"]},{"id":4614,"question":"بعض الأئمة يقرأ في صلاة الفجر بسورة الزلزلة، أمس واحد قرأ بسورة النصر وسورة المسد ......؟","title":"حكم القراءة بالزلزلة وقصار السور فيالفجر","answer":"الجواب: ثبت عن النبي ﷺ أنه قرأ الزلزلة في الفجر، كررها في الركعتين، رواه أبو داود بإسنادٍ جيدٍ، النبي أراد بيان الجواز، يعني قصده بيان الجواز؛ أنه يجوز أن يُصلي بقصار السور، لكن الأفضل أن يكون الغالبُ طوال السور، النبي كان يُطيل في الفجر عليه الصلاة والسلام، هذا هو الأفضل، لكن إذا فعل بعض الأحيان قصده لبيان الجواز، فلا حرج.","link":"https://binbaz.org.sa/fatwas/24903/حكم-القراءة-بالزلزلة-وقصار-السور-في-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قراءة سورة الزلزلة في صلاة الفجر في الركعتين.mp3","categories":["القراءة في الصلاة"]},{"id":4615,"question":"إذا أراد الإمامُ أن يُصلي المغرب بالأعراف، هل له أن يُعْلِمَ الجماعة ويُعلن عنها إعلانًا رسميًّا في أوراقٍ أنه سيُصلي في هذا المسجد المغرب بالأعراف؟","title":"حكم إطالة الإمام القراءة في صلاة الجماعة","answer":"الجواب: الأظهر في هذا لا يقرأ ولا يُعلن، ولا يقرأ لأنها نافلة، فعلها النبيُّ ﷺ مرةً واحدةً، وحثَّ على عدم التَّطويل، والناس لا يتحمَّلون اليوم، الذي أرى أنه لا ينبغي أن تُقرأ في هذا الوقت الحاضر؛ لأن الناس ما يتحمَّلون هذا الطول، والنبي ﷺ ما كان يُطوِّل عليهم في الغالب، وحثَّ على التَّخفيف، وسمعتُم ما قال لمعاذٍ، ولم يُحفظ عنه إلا مرة فعلها، لأسبابٍ فعلها عليه الصلاة والسلام، والناس تُراعى أحوالهم من ضعف إيمانٍ وضعف تحمُّلٍ.\nس: ......: \"كان يأمرنا بالتَّخفيف، ويؤمّنا بالصافات\"؟\nج: صلاة النبي ﷺ تخفيف، هذا هو الأصل، وعلمنا التَّخفيف عليه الصلاة والسلام، التَّأسي به هو التخفيف، لكن إذا راعى الإمامُ حال الناس كما أمره النبيُّ ﷺ، ينبغي أن يُراعي الناس... أن يُراعي حال الناس ولا يفتنهم أوْلى.","link":"https://binbaz.org.sa/fatwas/24904/حكم-اطالة-الامام-القراءة-في-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أراد الإمامُ أن يُصلي المغرب بسورة الأعراف.mp3","categories":["القراءة في الصلاة"]},{"id":4761,"question":"معنى خداج؟","title":"ما معنى: «فهي خداج» في الحديث؟","answer":"يعني فاسدة، إذا صلى بغير قراءة الصلاة فاسدة، يقال: أخدجت الناقة: إذا أسقطت الجنين ميتًا، أسقطت ولدًا ميتًا.","link":"https://binbaz.org.sa/fatwas/25120/ما-معنى-فهي-خداج-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من صلّى صلاة لم يقرأ فيها بفاتحة الكتاب فهي خداج.. ما معنى خداج.mp3","categories":["القراءة في الصلاة","صلاة الجماعة","شروح الحديث"]},{"id":4794,"question":"قراءة الزلزلة في صلاة الفجر؟","title":"حكم قراءة الزلزلة في صلاة الفجر في الركعتين","answer":"ما في بأس، جاء أنه قرأها في بعض الصلوات، وكررها في ركعتين عليه الصلاة والسلام، الزلزلة، لكن الأفضل غالبًا يطوّل فيها، قال أبو بكر : كان يقرأ بالفجر بالستين إلى المائة.  الأفضل فيها التطويل، يطوِّل الأولى، ويقصّر في الثانية، لكن يخفف بعض الأحيان؛ حتى يعلم الناس أن هذا جائز، وهذا جائز، يكون أكثر التطويل، وفي بعض الأحيان يخفف لا يطول؛ حتى يعلم الناس جواز هذا، وجواز هذا.\nس: هل يقرأ بالزلزلة في الركعتين؟\nالشيخ: في الركعتين نعم.","link":"https://binbaz.org.sa/fatwas/25173/حكم-قراءة-الزلزلة-في-صلاة-الفجر-في-الركعتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قراءة الزلزلة في صلاة الفجر في الركعتين.mp3","categories":["القراءة في الصلاة"]},{"id":5206,"question":"سماحة الشيخ، هذا سائل يقول: إذا كنتُ أُصلي خلف الإمام فهل أقرأ الفاتحة أم تكفي قراءة الإمام؟","title":"ما حكم قراءة المأموم الفاتحة خلف الإمام؟","answer":"الجواب: يجب عليك أن تقرأ الفاتحة ثم تُنصت؛ لقول النبيِّ ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلَّا بفاتحة الكتاب، فإنَّه لا صلاةَ لمَن لم يقرأ بها، فإذا كنتَ خلف إمامك اقرأها ثم أنصت.","link":"https://binbaz.org.sa/fatwas/30150/ما-حكم-قراءة-الماموم-الفاتحة-خلف-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 182.mp3","categories":["القراءة في الصلاة"]},{"id":5290,"question":"ما الحكم لو ترك الإنسان الفاتحة عمدًا أو سهوًا في الصلاة الجهرية أو السرية؟","title":"ما حكم ترك الفاتحة في الصلاة عمدًا أو سهوًا؟","answer":"الجواب: إذا كان مأمومًا لا يضر ذلك، إنْ كان جاهلًا أو ناسيًا؛ لأنها واجبة في حقه تسقط بالجهل والنسيان، وتسقط إذا جاء والإمام راكع وتجزئه الركعة. أما إذا كان إمامًا أو منفردًا لا تسقط، يعني إذا نسيها في ركعة تقوم بركعة مقامها وتأتي بركعة ثانية، فإذا سلم وطال الفصل يعيد الصلاة؛ لأنها ركن في حق الإمام والمنفرد لا بدّ منها، وإذا نسيها بركعة قامت الركعة الأخرى مقامها وأتى بركعة زائدة حتى يكمل. أما المأموم فهي في حقه واجبة تسقط بالسهو والنسيان، وتسقط بالفوات إذا جاء والإمام راكع ركع معه وأجزأته، كما جاء في حديث أبي بكرة .[1]","link":"https://binbaz.org.sa/fatwas/30931/ما-حكم-ترك-الفاتحة-في-الصلاة-عمدا-او-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 009.mp3","categories":["القراءة في الصلاة"]},{"id":5424,"question":"أيهما أفضل: طول السجود مع الدعاء، أم طول القيام مع القراءة؟","title":"هل الأفضل طول السجود أم القيام والقراءة؟","answer":"الجواب: ينبغي أن تكون الصلاةُ معتدلةً، إذا طوَّل القراءةَ طوَّل الركوعَ والسجودَ، وإذا قصَّر القراءةَ قصَّر الركوع والسجود، فتكون متقاربةً، مثلما قال البراء بن عازب: \"صليتُ مع رسول الله ﷺ فوجدتُ قيامَه فركعته فاعتداله بعد الركوع فسجدته فجلسته بين السجدتين قريبًا من السَّواء\"، يعني: يعتدل في الصلاة.[1]","link":"https://binbaz.org.sa/fatwas/31207/هل-الافضل-طول-السجود-ام-القيام-والقراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 045.mp3","categories":["القراءة في الصلاة","القيام في الصلاة"]},{"id":5506,"question":"في بعض الأحيان أنصت لقراءة الإمام، ويُصيبني شكّ: هل قرأت الفاتحة أم لا؟ وبعض الأحيان لا أقرؤها وأقول: هذا من وسواس الشيطان، فما حكم فعلي السَّابق؟","title":"ما حكم من شكّ هل قرأ الفاتحة في صلاته أم لا؟","answer":"الجواب: الأصل أنه قرأها ما دام خلف الإمام، ويترك الوسواس، ويجتهد في قراءتها ويحرص، ويترك الوساوس؛ لأنَّ الشيطان حريص على إفساد صلاة بني آدم. س: في الصلاة الجهرية لو ما قرأتها؟ ج: مثلما يشك: هل قال: سبحان ربي العظيم؟ هل قال: سبحان ربي الأعلى؟ هل قرأ التَّحيات؟ الشيطان يُوسوس عليه، ويلعب عليه. س: يتحملها الإمام؟ ج: إذا كان جاهلًا المأموم أو ناسيًا أو ما جاء إلا والإمام في الركوع أو عند الركوع، فيتحملها. س: لو ما قرأ الفاتحة في الصلاة الجهرية ؟ ج: يلزمه، لا يتعمد تركها إلا إذا كان جاهلاً يتحملها الإمام. س: إذا لم يستطع أن يقرأها؟ ج: لا يلزمه أن يقرأها، ولو قرأها الإمامُ، ولو ما علمها. س: وإذا لم يقرأها؟ إنسان جاهل ما عليه شيء، وإن كان ناسيًا ما عليه شيء، وإن كان يتعمّد ويعلم الحكم الشرعي ويترك؛ تبطل صلاته على الصحيح.[1]","link":"https://binbaz.org.sa/fatwas/31436/ما-حكم-من-شك-هل-قرا-الفاتحة-في-صلاته-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 021.mp3","categories":["القراءة في الصلاة"]},{"id":5671,"question":"رجل صلَّى بجماعةٍ من المسلمين، ولكن بقراءة الفاتحة تعدَّى آيةً، فلم يرد عليه أحد، هل صلاته صحيحة؟","title":"ما حكم مَن أسقط آيةً من الفاتحة في الصلاة؟","answer":"الجواب: لا، يجب عليه أن يأتي بركعةٍ بدل الركعة التي أسقط منها الآية، يأتي بركعةٍ أخرى بدل الركعة، إذا فاتت الركعةُ ولم يُردّ عليه وتذكر؛ يأتي بركعةٍ أخرى، إن كان في المغرب رابعة، وإن كان ظهرًا خامسة، وإن كان فجرًا ثالثة؛ لأنَّ قراءة الفاتحة ركنٌ في الصلاة، لا بدَّ من ذلك، ويسجد للسَّهو أيضًا.[1]","link":"https://binbaz.org.sa/fatwas/31708/ما-حكم-من-اسقط-اية-من-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 017.mp3","categories":["القراءة في الصلاة"]},{"id":5972,"question":"هل تقرأ المرأة في الصلاة الجهرية جهرًا كما يقرأ الرجل حيث حدث خلاف بين أناس من طلبة العلم، وقال بعضهم: صلوا كما رأيتموني أصلي فهذه للمرأة، والرجل نرجو بيان الحق في ذلك؟","title":"هل تصلي المرأة جهرا كالرجل؟","answer":"الجواب: الذي يظهر لنا أنه لا مانع، تصلي، وتجهر في صلاة المغرب، والعشاء، والفجر كالرجل؛ لأن النبي -عليه الصلاة والسلام- قال: صلوا كما رأيتموني أصلي والأحكام على السواء، أحكام الرجال، والنساء على السواء إلا ما جاء الدليل يخصه إن جاء الدليل بتخصيص الرجل، أو المرأة، وإلا فالأصل أنهما في الأحكام، سواء صلاتهما واحدة، زكاتهما واحدة، حجهما واحد.","link":"https://binbaz.org.sa/fatwas/1353/هل-تصلي-المراة-جهرا-كالرجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_310.mp3","categories":["الأذان والإقامة","القراءة في الصلاة","قضايا المرأة"]},{"id":6018,"question":"ما حكم قراءة الفاتحة في الصلاة السرية، والجهرية مع ذكر الترجيح لديكم؟","title":"حكم قراءة الفاتحة في الصلاة السرية والجهرية","answer":"الجواب:  قراءة الفاتحة فرض على الإمام، والمنفرد، النبي -عليه الصلاة والسلام- قال: لا صلاة لمن لم يقرأ بفاتحة الكتاب وقال -عليه الصلاة والسلام-: من صلى صلاة لم يقرأ فيها بفاتحة الكتاب؛ فهي خداج، فهي خداج غير تمام هذا الذي عليه جمهور أهل العلم، فرض على الإمام، والمنفرد.  لكن اختلفوا في المأموم هل تجب عليه، أم لا؟ على أقوال ثلاثة: قال بعضهم: تجب على المأموم في السرية، دون الجهرية، وقال بعضهم: تجب عليه مطلقًا في السرية، والجهرية، وقال بعضهم: لا تجب لا في السرية، ولا في الجهرية، فهذه أقوال ثلاث، أرجحها فيما يظهر من الأحاديث الوجوب مطلقًا، هذا أظهرها، ولا ينبغي تركها للمأموم، كما أنه لا يتركها الإمام، والمنفرد، بل يقرأها المأموم، ولو على قراءة الإمام، يقرأها في نفسه، ثم ينصت، والظهر، والعصر، والمغرب، والعشاء، والفجر في السرية ظاهر، وفي الجهرية يقرأها بعد الإحرام، بعد الفاتحة بحسب ما تيسر له مع الإمام.","link":"https://binbaz.org.sa/fatwas/1375/حكم-قراءة-الفاتحة-في-الصلاة-السرية-والجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_333.mp3","categories":["القراءة في الصلاة","الدعوة والدعاة"]},{"id":6026,"question":"ما حكم قراءة الفاتحة في الصلاة السرية، والجهرية مع ذكر الترجيح لديكم؟","title":"حكم قراءة الفاتحة في الصلاة السرية والجهرية","answer":"الجواب:  قراءة الفاتحة فرض على الإمام، والمنفرد، النبي -عليه الصلاة والسلام- قال: لا صلاة لمن لم يقرأ بفاتحة الكتاب وقال -عليه الصلاة والسلام-: من صلى صلاة لم يقرأ فيها بفاتحة الكتاب؛ فهي خداج، فهي خداج غير تمام هذا الذي عليه جمهور أهل العلم، فرض على الإمام، والمنفرد.  لكن اختلفوا في المأموم هل تجب عليه، أم لا؟ على أقوال ثلاثة: قال بعضهم: تجب على المأموم في السرية، دون الجهرية، وقال بعضهم: تجب عليه مطلقًا في السرية، والجهرية، وقال بعضهم: لا تجب لا في السرية، ولا في الجهرية، فهذه أقوال ثلاث، أرجحها فيما يظهر من الأحاديث الوجوب مطلقًا، هذا أظهرها، ولا ينبغي تركها للمأموم، كما أنه لا يتركها الإمام، والمنفرد، بل يقرأها المأموم، ولو على قراءة الإمام، يقرأها في نفسه، ثم ينصت، والظهر، والعصر، والمغرب، والعشاء، والفجر في السرية ظاهر، وفي الجهرية يقرأها بعد الإحرام، بعد الفاتحة بحسب ما تيسر له مع الإمام.","link":"https://binbaz.org.sa/fatwas/1375/حكم-قراءة-الفاتحة-في-الصلاة-السرية-والجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_333.mp3","categories":["القراءة في الصلاة","الدعوة والدعاة"]},{"id":6158,"question":"بعض المأمومين يتضجر من قراءة سورة السجدة، وسورة الدهر في ليلة الجمعة، فما موقف الإمام، علمًا بأن أكثرهم يرغب في ذلك، وبعضهم لا يرغب؟","title":"السور التي يسن قراؤتها في صلاة الفجر يوم الجمعة","answer":"الجواب: في الفجر هذه سنة، قراءة سورة السجدة، وقراءة هل أتى على الإنسان سنة فعلها النبي ﷺ وثبت فيها أحاديث صحيحة، فهي سنة يقرأ الإمام في صلاة الفجر: ألم السجدة في الأولى، وهل أتى على الإنسان في الثانية، سنة.  والذي يتبرم منها إما جاهل، وإما ضعيف الإيمان، فإحياء السنن مطلوب، فالإمام لا يبالي بهم، يقرأ السنن، ولا يلتفت إلى من تبرم بذلك، ويعتني بالصلاة، ويفعلها، والطمأنينة في الصلاة، وعدم العجلة، وقراءة ما شرع الله فيها، كل هذا مطلوب، ولو أن بعض الناس يتبرم، فلا يترك السنة لأجل بعض الناس، وليعتني بالسنة، ويحرص عليها في الصلاة، وغيرها، ولو تبرم بعض الناس من ذلك، مثل قراءة سورة السجدة، وهل أتى على الإنسان، هذه من السنن، والله أعلم، وصلى الله وسلم على نبينا محمد.","link":"https://binbaz.org.sa/fatwas/1597/السور-التي-يسن-قراوتها-في-صلاة-الفجر-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_490.mp3","categories":["القراءة في الصلاة","قضايا المرأة"]},{"id":6217,"question":"في أثناء الصلاة يسهو الشخص عن قراءة الفاتحة، أو يفوته بعض التسابيح، فما حكم صلاته؟","title":"حكم نسيان قراءة الفاتحة في الصلاة","answer":"الجواب: إذا سها عن الفاتحة يعيد الصلاة، الفاتحة ركن من أركان الصلاة، إذا كان إمامًا، أو منفردًا، ولم يقرأ الفاتحة؛ لم تصح صلاته، إذا كان سها في الركعة الأولى؛ يقوم مقامها الركعة الثانية، وهكذا، فيأتي بركعة بدل التي سها فيها عن الفاتحة، وعليهم أن ينبهونه إذا سها.  أما المأموم إذا تركها ساهيًا؛ فنرجو أن يجزئه ذلك؛ لأن جمعًا من أهل العلم -وهم الجمهور- يرون أنها تجزئه قراءة الإمام، لكن لا يتعمد تركها، الواجب عليه أن يقرأ الفاتحة، ولا يتعمد، لكن لو سها، أو قلد من يرى سقوطها عن المأموم، أو اعتقد سقوطها عن المأموم؛ فصلاته صحيحة، أما الإمام، والمنفرد فليس له شبهة، والواجب عليه قراءتها، وإذا سها في ركعة؛ قامت الأخرى مقامها، وأتى بركعة سواها. السؤال: وهل يسجد للسهو؟ الجواب:  ويسجد للسهو، نعم.","link":"https://binbaz.org.sa/fatwas/1717/حكم-نسيان-قراءة-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_569.mp3","categories":["القراءة في الصلاة"]},{"id":6469,"question":"ما حكم من يجهر بالبسملة في قراءة الفاتحة عمدًا في المغرب، والعشاء، والفجر؟","title":"الجهر بالبسملة عند قراءة الفاتحة","answer":"الجواب: لا حرج عليه، لكن تركه أفضل، السنة والأفضل ألا يجهر، ومن جهر؛ فلا شيء عليه، إذا فعل ذلك عن اجتهاد، أو تقليد لمن يتبعه من أهل العلم فلا شيء عليه، لكنه خالف الأفضل، وخالف السنة المعروفة المستفيضة.  فالأفضل له، والأولى به ألا يجهر بالبسملة؛ لأن الثابت عن الرسول ﷺ وعن صاحبيه الصديق، وعمر، وعن عثمان أيضًا عدم الجهر ببسم الله الرحمن الرحيم، وقد ورد عن بعض الصحابة كأبي هريرة الجهر بها، وغيره، فمن جهر دون حرج، ولكن ترك الأفضل، وترك ما هو الأولى، والذي ينبغي.","link":"https://binbaz.org.sa/fatwas/2218/الجهر-بالبسملة-عند-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_837.mp3","categories":["القراءة في الصلاة"]},{"id":6473,"question":"ما حكم من يجهر بالبسملة في قراءة الفاتحة عمدًا في المغرب، والعشاء، والفجر؟","title":"الجهر بالبسملة عند قراءة الفاتحة","answer":"الجواب: لا حرج عليه، لكن تركه أفضل، السنة والأفضل ألا يجهر، ومن جهر؛ فلا شيء عليه، إذا فعل ذلك عن اجتهاد، أو تقليد لمن يتبعه من أهل العلم فلا شيء عليه، لكنه خالف الأفضل، وخالف السنة المعروفة المستفيضة.  فالأفضل له، والأولى به ألا يجهر بالبسملة؛ لأن الثابت عن الرسول ﷺ وعن صاحبيه الصديق، وعمر، وعن عثمان أيضًا عدم الجهر ببسم الله الرحمن الرحيم، وقد ورد عن بعض الصحابة كأبي هريرة الجهر بها، وغيره، فمن جهر دون حرج، ولكن ترك الأفضل، وترك ما هو الأولى، والذي ينبغي.","link":"https://binbaz.org.sa/fatwas/2218/الجهر-بالبسملة-عند-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_837.mp3","categories":["القراءة في الصلاة"]},{"id":6598,"question":"ورد عن رسول الله ﷺ أنه كان يجهر بالتسمية في بعض الصلوات، ويسر بها في بعض، ولكن هنا الإنكار، ونسمع إمام يجهر، رغم أنه يجب التوافق بين الحديثين؟","title":"حكم الإسرار بالبسملة في الصلاة الجهرية","answer":"الجواب: الأحاديث الصحيحة دالة على أن السنة السر بالتسمية، والاستعاذة، هذا هو الأفضل أن يكون الإمام، والمنفرد، والمأموم كلهم يسرون بالتعوذ، والبسملة، لا في الفاتحة، ولا في غيرها، وإذا جهر بعض الأحيان؛ ليعلم من ورائه أنه يسمي، وأن الصلاة يسمى فيها، ويستعاذ فيها من باب التعليم؛ فلا بأس، فقد ثبت عن أبي هريرة ما يدل على ذلك، وعن بعض الصحابة. لكن الأفضل، والعموم، والأكثر أن يكون مسرًا بالتسمية في الجهرية، وبالاستعاذة، فإن الرسول ﷺ كان يبدأ القراءة بالحمد لله رب العالمين، ويسر التعوذ، والبسملة -عليه الصلاة والسلام - كما قال أنس وجماعة.","link":"https://binbaz.org.sa/fatwas/2465/حكم-الاسرار-بالبسملة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_992.mp3","categories":["القراءة في الصلاة"]},{"id":6741,"question":"هل يجوز الجهر بالقراءة في صلاة التهجد، أم لا؟ وهل يجوز القراءة في المصحف في صلاة التهجد، أم لا؟","title":"حكم الجهر والقراءة من المصحف في التهجد","answer":"الجواب: أفضل، الجهر أفضل؛ لأنه ينشط، ويطرد النعاس، ويرغم الشيطان، وينفع المستمع، فالأفضل له الجهر في صلاة التهجد بالليل، هذا هو الأفضل، ولا بأس أن يقرأ في المصحف، إلا إذا كان حوله نيام يشق عليهم؛ خفض صوته حتى لا يشغلهم، وحتى لا يؤذيهم. أما إذا كان ما حوله أحد يتأذى بذلك، فالأفضل الجهر، جهرًا لا يتعبهم، ولا يؤذي أحدًا، وكذلك إذا كان حوله يصلون؛ لا يشغلهم أيضًا، لا يجهر جهرًا، لا يؤذي مصليًا، ولا يؤذي نائمًا، وكذلك لا بأس بالقراءة في المصحف، كان مولى عائشة -رضي الله عنها- يصلي بها من المصحف في رمضان، فالذي ما عنده حفظ، وقرأ من المصحف لتهجده؛ فلا بأس. السؤال: حتى ولو كان إمامًا يا شيخ؟ الجواب: ولو كان إمامًا نعم. السؤال: وصلاة الفريضة؟ الجواب: الفريضة ما هو محتاج للمصحف في الغالب، الحمد لله الفاتحة ميسرة، وما تيسر معها ميسر، لكن الغالب يحتاج إلى هذا في التهجدات، ولو قرأ من المصحف ما في شيء، صحيح، لكن ما له حاجة فيه.","link":"https://binbaz.org.sa/fatwas/2618/حكم-الجهر-والقراءة-من-المصحف-في-التهجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1114.mp3","categories":["الوتر وقيام الليل","القراءة في الصلاة"]},{"id":6748,"question":"هل يجوز ترك سنة الوتر، وقد سمعت بأن الرسول لم يترك الوتر، لا في سفر، ولا حضر، وضح لنا الطريق؟","title":"هل يجوز ترك صلاة الوتر؟","answer":"الجواب: الوتر سنة مؤكدة في الحضر، والسفر، الوتر سنة مؤكدة، أقله ركعة في السفر، والحضر، ولكن لو تركه لا شيء عليه، هو نافلة، تطوع، ليس بواجب، وكان يوتر على بعيره، ولا يصلي الفريضة إلا على الأرض. فالوتر من النوافل، كسنة الظهر، والمغرب، والعشاء، والفجر، وسنة الجمعة، كلها من النوافل، ولما سأله رجل عن الصلاة؛ علمه أنها خمس صلوات، فقال: هل علي غيرها؟ قال: لا، إلا أن تطوع فالذي ... الصلوات الخمس بالرواتب، والوتر صلاة الضحى كلها نوافل، كلها تطوع.","link":"https://binbaz.org.sa/fatwas/2622/هل-يجوز-ترك-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1118.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":6936,"question":"هناك شبهة يروج لها المبتدعة، وهي: ما سنه عمر  من جميع المسلمين في صلاة التراويح على إمام واحد، وصلى بهم إحدى وعشرين ركعة، وقوله : (نعمت البدعة) مع أن السنة عن رسول الله صلاة التراويح إحدى عشرة ركعة، وفي رواية ثلاث عشرة، فكيف يخالف عمر  هدي رسول الله ﷺ ويزيد في صلاة التراويح إحدى وعشرين ركعة؟ وما هو الأولى في ذلك، صلاة التراويح إحدى عشر كهدي الرسول ﷺ أم ثلاث وعشرين، كما بين عمر ؟","title":"الرد على من أنكر صلاة التراويح","answer":"الجواب: هذا لا تعلق للبدعة فيه؛ لأن عمر  إنما أراد بقوله: (نعمت البدعة) يعني من حيث اللغة؛ لأن البدعة من حيث اللغة ما عمل على غير مثال سابق، ما عمله الناس على غير مثال سابق؛ يسمى بدعة في اللغة، وليس مراده أن هذا بدعة في الدين، لو كان في بدعة في الدين ما فعله، هو أبعد الناس عن البدع -رضي الله عنه وارضاه-. وإنما أراد أنه فعله على غير الطريقة التي كان عليها رسول الله ﷺ فإنه كان رسول الله ﷺ يصلي في بيته، وخاف على الناس من الصلاة في المسجد أن تفرض عليهم، صلى بهم النبي ﷺ عدة ليال، ثلاث ليال، ثم تأخر، وقال: إني خشيت أن تفرض عليكم فدل ذلك على أنه إنما تركها؛ خوف الفريضة عليه، فلما توفي النبي ﷺ أمن الناس من الفريضة؛ لأن التشريع انقطع، الوحي انقطع، ما بقي تشريع، فلهذا فعلها عمر  وأمر أُبَيّ أن يصلي بالناس، رضي الله عنهم وأرضاهم جميعًا. فليست بدعة، وإنما هي سنة سنها الرسول ﷺ وفعلها، وفعلها الصحابة في وقته، كانوا يصلون في وقت النبي ﷺ أوزاعًا، كان الرجل وحده يصلي، الرجل بالرجلين، وبالثلاثة أوزاعًا، يعني جماعات في المسجد، فجمعهم عمر على إمام واحد، فهي سنة، وليست بدعة، وإنما أراد من حيث اللغة، سماها بدعة من حيث اللغة .. وأما كونه صلى ثلاثًا وعشرين، فقد ثبت عنه هذا، وهذا، ثبت عنه: صلى إحدى عشرة، وثبت عنه: أنه صلى ثلاثًا وعشرين، والسبب في ذلك أن الإحدى عشر كانوا يطولون فيها، ثم رأى التخفيف بعض الشيء، وأن تكون ثلاثًا وعشرين، وكله سنة، هذا سنة، وهذا سنة، لأن الرسول ﷺ قال: صلاة الليل مثنى مثنى ولم يحدد إحدى عشرة، ولا ثلاث عشرة، ولا أكثر من ذلك قال: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح؛ صلى ركعة واحدة، توتر له ما قد صلى ولم يقل: فإذا زاد على إحدى عشرة؛ فليقف، أو ثلاث عشرة، قال: فإذا خشي الصبح؛ صلى ركعة واحدة، توتر له ما قد صلى. فصلاة الليل موسع فيها، ولهذا كان بعض السلف يصلي أربعين، وبعضهم يصلي أكثر من ذلك، فصلاة الليل فيها سعة، فعمر  لما علم هذا؛ عمر خففها من ثلاث وعشرين إلى إحدى عشرة؛ حتى يتمكن الناس من أدائها بنشاط، من غير تعب، فمن صلاها إحدى عشرة، أو ثلاث عشرة، أو ثلاثًا وعشرين، أو أكثر من ذلك؛ فلا حرج، لكن الأفضل إحدى عشرة، أو ثلاث عشرة. هذا الأفضل كونه يوافق فعل النبي ﷺ هذا هو الأفضل، ولكن ليس بمخالفة ذلك بدعة، ولا إنكار؛ لأن المشروع في صلاة الليل أمر واسع -بحمد الله- وفي النهار كذلك.","link":"https://binbaz.org.sa/fatwas/2866/الرد-على-من-انكر-صلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1314.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":6964,"question":"أسمع وأنا أصلي من يقرأ سورًا من القرآن في الركعة الثالثة، والرابعة، هل هذا من السنة؟ وهل يؤثر في صحة الصلاة؟","title":"حكم قراءة سورة مع الفاتحة في الركعة الثالثة والرابعة","answer":"الجواب:\n\nثبت في الصحيحين عن أبي قتادة الأنصاري  عن النبي ﷺ أنه كان يقرأ في الثالثة، والرابعة بفاتحة الكتاب فقط في الظهر، والعصر يعني، وهكذا العشاء، والمغرب، فالسنة أنه يقتصر على الفاتحة في الثالثة، والرابعة في الظهر، والعصر، والمغرب، والعشاء.\n\nلكن يستحب له في بعض الأحيان -خاصة في الظهر- أن يقرأ زيادة؛ لأنه ثبت في حديث أبي سعيد ما يدل على أنه ربما قرأ في الثالثة، والرابعة في الظهر خاصة -عليه الصلاة والسلام- فإذا قرأ زيادة في الظهر، والعصر في الثالثة، والرابعة بعض الشيء مع الفاتحة؛ فلا بأس.\n\nومستحب في بعض الأحيان، لا دائمًا؛ جمعًا بين الأحاديث الواردة في ذلك، لأن أبا قتادة ذكر أنه يقرأ الفاتحة فقط في الثالثة، والرابعة، وأبو سعيد ذكر ما يدل على أنه في بعض الأحيان يقرأ زيادة على الفاتحة، نعم في الظهر خاصة.","link":"https://binbaz.org.sa/fatwas/2912/حكم-قراءة-سورة-مع-الفاتحة-في-الركعة-الثالثة-والرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1360.mp3","categories":["القراءة في الصلاة"]},{"id":6986,"question":"أسمع وأنا أصلي من يقرأ سورًا من القرآن في الركعة الثالثة، والرابعة، هل هذا من السنة؟ وهل يؤثر في صحة الصلاة؟","title":"حكم قراءة سورة مع الفاتحة في الركعة الثالثة والرابعة","answer":"الجواب:\n\nثبت في الصحيحين عن أبي قتادة الأنصاري  عن النبي ﷺ أنه كان يقرأ في الثالثة، والرابعة بفاتحة الكتاب فقط في الظهر، والعصر يعني، وهكذا العشاء، والمغرب، فالسنة أنه يقتصر على الفاتحة في الثالثة، والرابعة في الظهر، والعصر، والمغرب، والعشاء.\n\nلكن يستحب له في بعض الأحيان -خاصة في الظهر- أن يقرأ زيادة؛ لأنه ثبت في حديث أبي سعيد ما يدل على أنه ربما قرأ في الثالثة، والرابعة في الظهر خاصة -عليه الصلاة والسلام- فإذا قرأ زيادة في الظهر، والعصر في الثالثة، والرابعة بعض الشيء مع الفاتحة؛ فلا بأس.\n\nومستحب في بعض الأحيان، لا دائمًا؛ جمعًا بين الأحاديث الواردة في ذلك، لأن أبا قتادة ذكر أنه يقرأ الفاتحة فقط في الثالثة، والرابعة، وأبو سعيد ذكر ما يدل على أنه في بعض الأحيان يقرأ زيادة على الفاتحة، نعم في الظهر خاصة.","link":"https://binbaz.org.sa/fatwas/2912/حكم-قراءة-سورة-مع-الفاتحة-في-الركعة-الثالثة-والرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1360.mp3","categories":["القراءة في الصلاة"]},{"id":7028,"question":"هل صلاة الوتر تختلف عن صلاة الليل من حيث وقتها، والدعاء الذي يقال في الصلاتين، وكذلك عدد ركعات الصلاة؟","title":"هل صلاة الوتر تختلف عن صلاة الليل؟","answer":"الجواب:\n\nالوتر من صلاة الليل وهو ختامها، ركعة واحدة، يختم بها صلاة الليل في آخر الليل، أو في وسط الليل، أو في أول الليل، بعد صلاة العشاء يصلي ما تيسر، ثم يختم بواحدة يقرأ فيها: الْحَمْد [الفاتحة:2]، وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]، هذا الوتر.\n\nالسؤال: فيها دعاء يا شيخ؟\n\nالجواب: فيها قنوت إذا أراد، يقنت بعد الركوع اللهم اهدني فيمن هديت ... إلى آخره، أو يدعو بغير ذلك لا بأس.","link":"https://binbaz.org.sa/fatwas/3010/هل-صلاة-الوتر-تختلف-عن-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1417.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":7032,"question":"كذلك إذا نسي الفاتحة، فهل يأتي بركعة أخرى تحل محلها؟ وهل يسجد سجود السهو؟","title":"حكم من نسي قراءة الفاتحة","answer":"الجواب: إذا كان مأمومًا ما عليه شيء، أما إذا كان إمامًا، أو منفردًا فيأتي بركعة، بدل الركعة التي سقطت منها الفاتحة، أما إن كان مأمومًا، فالمأموم تابع لإمامه، إذا نسي، أو فاته القيام؛ أجزأه، ما أدرك مع الإمام.","link":"https://binbaz.org.sa/fatwas/3005/حكم-من-نسي-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1413.mp3","categories":["القراءة في الصلاة"]},{"id":7036,"question":"هل قراءة سورة السجدة، وسجدة التلاوة في صلاة الفجر يوم الجمعة من السنة؟ وهل يداوم على فعلها إذا كان ذلك من السنة؟","title":"حكم المداومة على قراءة سورتي السجدة والإنسان في فجر الجمعة","answer":"الجواب: نعم سنة، كونه يقرأ في فجر الجمعة سورة الم ۝ تَنْزِيلُ [السجدة:1، 2]، وهَلْ أَتَى عَلَى الْإِنْسَانِ [الإنسان:1] سنة، رواه الشيخان من حديث أبي هريرة، ورواه مسلم من حديث ابن عباس، ورواه الطبراني من حديث ابن مسعود، وكان ابن مسعود يقول: إنه يديم ذلك، فالسنة المداومة نعم. السؤال: ... يجزأ السورة؟ الجواب: لا، يقرأ الم ۝ تَنْزِيلُ في الأولى وهَلْ أَتَى عَلَى الْإِنْسَانِ في الثانية، لا يقطعها، مثل ما فعل النبي ﷺ، يقرأ السورتين جميعًا هذه السنة.","link":"https://binbaz.org.sa/fatwas/3007/حكم-المداومة-على-قراءة-سورتي-السجدة-والانسان-في-فجر-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1415.mp3","categories":["القراءة في الصلاة"]},{"id":7044,"question":"قراءة الفاتحة للمأموم؟","title":"ما حكم قراءة الفاتحة للمأموم؟","answer":"الجواب:\n\nالصحيح أن الواجب عليه قراءتها إذا أمكنه.\n\nالسؤال: وإذا كان الإمام يقرأ السورة بعد الفاتحة مباشرة؟\n\nالجواب: ولو، يقرأها وهو يقرأ، ما في مانع.\n\nالسؤال: لا يتسع؟\n\nالجواب: تقرأها، وإن كان الإمام يقرأ تقرأ الفاتحة، ولو كان الإمام يقرأ، ثم تنصت الحمد لله، لكن إذا فاتت سقطت، إذا جاء والإمام راكع، أو ما أمكنك عليها؛ سقطت على المأموم.\n\nالسؤال:...؟\n\nالجواب: ما في بأس، تقرأها ثم تستمع.","link":"https://binbaz.org.sa/fatwas/3024/ما-حكم-قراءة-الفاتحة-للماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1431.mp3","categories":["القراءة في الصلاة"]},{"id":7061,"question":"كيف نوفق بين حديثي رسول الله ﷺ: من كان له إمام؛ فقراءة الإمام له قراءة وحديث: لا صلاة لمن لم يقرأ بفاتحة الكتاب؟ وكيف وصل الأمر إلى اختلاف المذاهب في هذا الأمر، منهم من حرم القراءة كليًّا، ومنهم من كرهها، ومنهم من كرهها في الجهرية واستحبها في السرية، وغير ذلك؟ والمعلوم بأن الأمور التعبدية اتباع وتقليد، ليس للبشر، وفعل الصحابة، فكيف يختلف الفقهاء في أمر تعبدي؟ وما هو فعل الرسول ﷺ والصحابة من بعده؟","title":"سبب اختلاف الفقهاء في قراءة المأموم للفاتحة","answer":"الجواب: \n\nليس في هذا اختلاف بمعناه؛ لأن الحديث: من كان له إمام؛ فقراءته قراءة له حديث ضعيف عند أهل العلم، ليس بصحيح، وقد اغتر به بعض الناس، وظن أنه صحيح وقال: إن المأموم ليس عليه قراءة، يكفي قراءة الإمام، وذهب إلى هذا بعض أهل العلم من الصحابة، ومن بعدهم.\n\nوذهب آخرون من أهل العلم: إلى أن القراءة على المأموم مطلوبة، وعليه أن يقرأ لقوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب وهي أحاديث صحيحة رواه البخاري ومسلم وغيرهما -رحمة الله عليهما- وقوله ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم. قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها هذا يبين لنا أن المأموم عليه القراءة.\n\nوأما أسباب الاختلاف، فأسباب ذلك أن بعض أهل العلم قد يطلع على بعض الأحاديث، ولا يطلع على البعض الآخر، فلهذا يقع الاختلاف، هذا من أسباب الخلاف؛ لأن العلماء انتشروا في البلاد في العهد الأول، هذا في المدينة، هذا في مكة، هذا في مصر، هذا في الشام، هذا في العراق، هذا في خراسان، انتشر الناس، والكتب لم تؤلف أولًا، كان الناس يحفظون العلم في صدورهم، ثم ألفت الكتب، ونشرت في القرن الثالث وما بعده، فبعض أهل العلم اطلع على شيء، والآخر اطلع على شيء آخر، فلهذا خفي بعض الأحاديث على بعض العلماء فقالوا بعلمهم.\n\nفالذين قالوا: إنه تجب القراءة على المأموم؛ بلغتهم الأحاديث الصحيحة؛ فأمروا بقراءة الفاتحة، والذين لم يبلغهم الحديث، أو بلغهم ولكن لم يصح، أو نحو ذلك؛ ظنوا أن الإمام يقوم بذلك، وأنه يكفيه ذلك، ويسد عن المأموم. \n\nوالصواب: أنه لا يكفيه عن قراءة الفاتحة، يقرأ المأموم الفاتحة، ثم ينصت، ويكفيه الإمام عن الزيادة في الجهرية، يعني في المغرب والعشاء والفجر.","link":"https://binbaz.org.sa/fatwas/3031/سبب-اختلاف-الفقهاء-في-قراءة-الماموم-للفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1436.mp3","categories":["القراءة في الصلاة"]},{"id":7069,"question":"قراءة الفاتحة للمأموم؟","title":"ما حكم قراءة الفاتحة للمأموم؟","answer":"الجواب:\n\nالصحيح أن الواجب عليه قراءتها إذا أمكنه.\n\nالسؤال: وإذا كان الإمام يقرأ السورة بعد الفاتحة مباشرة؟\n\nالجواب: ولو، يقرأها وهو يقرأ، ما في مانع.\n\nالسؤال: لا يتسع؟\n\nالجواب: تقرأها، وإن كان الإمام يقرأ تقرأ الفاتحة، ولو كان الإمام يقرأ، ثم تنصت الحمد لله، لكن إذا فاتت سقطت، إذا جاء والإمام راكع، أو ما أمكنك عليها؛ سقطت على المأموم.\n\nالسؤال:...؟\n\nالجواب: ما في بأس، تقرأها ثم تستمع.","link":"https://binbaz.org.sa/fatwas/3024/ما-حكم-قراءة-الفاتحة-للماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1431.mp3","categories":["القراءة في الصلاة"]},{"id":7427,"question":"قراءة سورة السجدة في ليلة الجمعة لا بد أن تكون في كل أسبوع؟","title":"حكم قراءة سورتي السجدة والإنسان في صلاة فجر يوم الجمعة","answer":"الجواب: سنة دائمة، قراءة سورة السجدة وهَلْ أَتَى عَلَى الْإِنْسَانِ سنة في الفجر يوم الجمعة دائمًا، كان النبي ﷺ يحافظ عليها، ولو تركها لم يحرم، لكن هذا هو السنة. السؤال: يقسموها يا شيخ؟ الجواب: لا، السنة يقرأ هذه وهذه، القسم خلاف السنة، يقرأ التنزيل في الأولى، وهل أتى على الإنسان في الثانية، هذه السنة التي فعلها النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/3512/حكم-قراءة-سورتي-السجدة-والانسان-في-صلاة-فجر-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1816.mp3","categories":["القراءة في الصلاة"]},{"id":7664,"question":"تقول أيضاً سؤالي الثاني هو أني رأيت بعض المسلمين إذا صلوا يقرءون في الركعة الأولى والثانية الفاتحة، ويتبعونها بآيات قصيرة، أما الركعتين الباقيتين فيقرؤون في كل ركعة سبحان الله والحمد لله لا إله إلا الله والله أكبر ثلاث مرات، أي: أنهم لا يقرءون الفاتحة في كل ركعة في الركعتين الأخيرتين. فهل هذا صحيح، أثابكم الله عن توضيح الخطأ والصواب لإخوانكم المسلمين؟","title":"حكم قول المصلي: (سبحان الله والحمد لله) بدلاً من الفاتحة","answer":"الجواب: هذا خطأ، الذي لا يقرأ في الثالثة والرابعة الفاتحة هذا خطأ غلط ولا يجوز ولا تصح الصلاة بذلك؛ الرسول ﷺ كان يقرأ في الأولى والثانية بالفاتحة وسورة أخرى مع الفاتحة، وفي الثالثة والرابعة لا يقرأ شيئاً سوى الفاتحة يقرأ الفاتحة، وربما قرأ زيادة على الفاتحة في الثالثة والرابعة في الظهر خاصة، وقد ثبت عنه هذا عليه الصلاة والسلام في عدة أحاديث من حديث أبي قتادة الأنصاري وحديث أبي سعيد الأنصاري ومن أحاديث أخرى، ثبت فيها أنه ﷺ أنه كان يقرأ في الأولى والثانية بالفاتحة وزيادة، وفي الثالثة والرابعة لا يقرأ إلا الفاتحة عليه الصلاة والسلام، لكن جاء ما يدل على أنه قد يقرأ زيادة في الثالثة والرابعة في الظهر خاصة، وقد صح عنه عليه الصلاة والسلام أنه قال: لا صلاة لمن لم يقرأ بفاتحة الكتاب فالذي لا يقرأ بها في الثالثة والرابعة لا صلاة له.\nفالواجب على من رأى من يفعل هذا التسبيح ينكر عليه ويعلمه، وعلى الأخت في الله السائلة أن تعلم هؤلاء تقول: إني سمعت في نور على الدرب كذا وكذا تعلمهم أن هذا لا يجوز وأنه واجب على المسلم أن يقرأ الفاتحة في جميع الركعات، لقول النبي عليه الصلاة والسلام: لا صلاة لمن لم يقرأ بفاتحة الكتاب متفق على صحته، ولقوله عليه الصلاة والسلام أيضاً في الحديث الصحيح: من صلى صلاة لم يقرأ فيها بفاتحة الكتاب فهي خداج فهي خداج غير تمام يعني ناقصة غير صحيحة.\nفالحاصل أن الواجب على المسلم والمسلمة أن يعلما ويرشدا، فهذه السائلة بارك الله فيها عليها أن تعلم من رأتهم يفعلون ذلك، الذين لا يقرءون في الثالثة والرابعة تعلمهم أن هذا خلاف ما قاله النبي صلى الله عليه وسلم وخلاف ما عليه المسلمون، فالواجب على هؤلاء أن يقرؤوا الفاتحة بدلاً من التسبيح في الثالثة والرابعة كما قرءوها في الأولى والثانية، لكن في الأولى والثانية يتأكد الزيادة على الفاتحة إما سورة وإما آيات على تفصيل في الصلوات الخمس، لكن في الثالثة والرابعة الأفضل الاقتصار على الفاتحة كما فعله النبي صلى الله عليه وسلم إلا في الظهر فيستحب أن يقرأ زيادة على الفاتحة في بعض الأحيان في الثالثة والرابعة. نعم. لأنه ورد عن النبي ذلك عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/4838/حكم-قول-المصلي-سبحان-الله-والحمد-لله-بدلا-من-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_038/03803.mp3","categories":["القراءة في الصلاة"]},{"id":7731,"question":"من السودان وردت هذه الرسالة من حمد مسعود فضل السيد يقول: ما حكم الجهر في صلاة النوافل بالليل؟ وإذا سها وجهر في ركعة فما الحكم؟","title":"حكم الجهر في صلاة الليل","answer":"الجواب: السنة الجهر، في صلاة الليل السنة الجهر في النافلة والفريضة، يجهر في المغرب في الأولى والثانية، في العشاء في الأولى والثانية، ويسر في الثالثة من المغرب ويسر في الثالثة والرابعة من العشاء، أما النوافل فالسنة فيها الجهر لكن جهراً لا يؤذي أحداً ولا يشق على أحد، فإذا كان بقربه مصلون أو نوام أو قراء فإنه يجهر جهراً لا يؤذيهم ولا يشق عليهم ولا يشوش عليهم، وقد خرج صلى الله عليه وسلم على قوم يصلون في المسجد ويرفعون أصواتهم فقال لهم ﷺ: كلكم يناجي الله فلا يؤذ بعضكم بعضاً، المقصود أنه إذا جهر يتحرى الجهر الخفيف الذي لا يتأذى به مصلي ولا قارئ ولا نائم، وهكذا من كان في المساجد يقرأ، في المساجد ينبغي له أن يلاحظ عدم التشويش على من حوله، فيقرأ قراءة خفيفة ليس فيها تشويش على من حوله من المصلين والقراء، بعض الناس في المساجد في الجمع وغير الجمع يجهر جهراً يشوش على من حوله وهذا لا ينبغي، أقل أحواله الكراهة، فينبغي في مثل هذا أن يراعي القاري عدم التشويش على من حوله من المصلين والقراء سواء كان في صلاة الليل في بيته أو في المساجد هذه هي السنة. نعم.","link":"https://binbaz.org.sa/fatwas/4930/حكم-الجهر-في-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_032/03206.mp3","categories":["صلاة التطوع","القراءة في الصلاة"]},{"id":7736,"question":"أيضاً لديه سؤال آخر يقول: سمعت شخص وهو يصلي صلاة المغرب مع المصلين خلف الإمام حين كان الإمام يقرأ إحدى السور يقول: اللهم ارحمني وجميع المسلمين جهراً، فما حكم ذلك وفقكم الله؟","title":"حكم إنصات المأموم لقراءة إمامه","answer":"الجواب: الواجب على المأموم أن ينصت لإمامه إذا قرأ وألا يتكلم بشيء بل ينصت ويتدبر ويتعقل؛ لأن الله يقول سبحانه: وَإذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204] والنبي عليه الصلاة والسلام يقول: إذا قرأ -يعني: الإمام- فأنصتوا هذا هو الواجب ولا يتكلم بشيء، لكن لو سكت الإمام بعض السكتات فقال المأموم فيما بينه وبين نفسه شيئاً يتعلق بالقراءة لا حرج، كذكر الجنة أو النار، فقال في الجنة: اللهم اجعلني من أهلها، وفي النار أعوذ بالله منها، في السكتة التي ما فيها قراءة، لا حرج في ذلك إن شاء الله، وأما وقت القراءة فالواجب أن يراعي الإنصات وألا يتكلم بشيء، إلا في الفاتحة يقرؤها المأموم ولو قرأ الإمام إذا لم يتيسر سكته، إذا كان الإمام لا يسكت فإن المأموم يقرأ الفاتحة مع إمامه ثم ينصت لبقية القراءة ...... في الصلاة الجهرية على الصحيح من أقوال العلماء. نعم.","link":"https://binbaz.org.sa/fatwas/4935/حكم-انصات-الماموم-لقراءة-امامه ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_033/03304.mp3","categories":["صلاة الجماعة","القراءة في الصلاة"]},{"id":7759,"question":"أيضاً يقول محمد عبده سعيد اليماني: ما حكم الذي يصلي الفرض ولا يقرأ إلا الفاتحة فقط ولم يقرأ آيات أخرى؟","title":"حكم الاقتصار على الفاتحة في الصلاة المفروضة","answer":"الجواب: الفاتحة هي ركن الصلاة، فإذا قرأ الفاتحة وقت الصلاة أجزأت الصلاة وصحت، لكن عمله مكروه؛ لأنه خالف السنة، والنبي ﷺ كان يقرأ معها في الأولى والثانية سورة أو آيات، الظهر والعصر والمغرب والعشاء والفجر، فالذي يترك قراءة سورة مع الفاتحة في الفجر.. في الجمعة.. في الظهر والعصر والمغرب والعشاء في الأولى والثانية يكون قد خالف السنة، فأقل أحواله أنه ترك الأولى، ولا مانع أن يقال: إنه فعل مكروهاً؛ لأنه ترك سنة قد داوم عليها النبي ﷺ، فيكون فعل مكروهاً لا ينبغي له فعله. نعم.","link":"https://binbaz.org.sa/fatwas/4955/حكم-الاقتصار-على-الفاتحة-في-الصلاة-المفروضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_044/04402.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":7961,"question":"هذه رسالة من السودان يقول المخلص محمد علي عبد الله يقول: حضرة السادة المرشدين! دمتم في حفظ الله ورعايته والسلام عليكم ورحمته، سبق أرسلت استفسار عن قطع الجمار. وفي الحقيقة أجبنا عليه في حينه، يقول: ثم أرسلت استفسار عن إمام لم أصل معه قبل ذلك فصليت معه فريضة الجمعة والإمام المذكور بعد الفاتحة قرأ السورة الثانية ونسي فيها آية ولم ينبئه الذين كانوا بالقرب منه، فهل على المأموم شيء، وأعتقد لم أحقد الرد -يعني: لم أعرف الرد كلمة (أحقد) يقصد بها: أعرف- أرجو إفتائي في ذلك وفقكم الله؟الشيخ: والإمام قرأ الفاتحة؟المقدم: إي نعم، قرأ الفاتحة وقرأ السورة التي بعدها لكنه في السورة التي بعدها نسي آية.","title":"حكم صلاة من ترك آية من السورة التي بعد الفاتحة","answer":"الجواب: ما يضر، نسيانه الآية لا يضر يا أخي، لا يضر والصلاة صحيحة ولا يضر، المهم الفاتحة لما كمل الفاتحة الحمد لله، السورة مندوبة وإذا ترك منها شيئاً لا حرج. نعم.","link":"https://binbaz.org.sa/fatwas/5483/حكم-صلاة-من-ترك-اية-من-السورة-التي-بعد-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_069/06904.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":7979,"question":"أيضاً يقول: ما هي الحكمة من أن صلاة الفجر والمغرب والعشاء جهرية، وصلاة الظهر والعصر سرية، أي: في الخفاء، وفقكم الله وبارك في جهودكم لخدمة المسلمين؟","title":"الحكمة من الجهر بالقراءة أو الإسرار بها في الصلاة","answer":"الجواب: هذا ليس فيه نص في بيان الحكمة فيما نعلم، أقول: ليس هناك نص في بيان الحكمة فيما نعلم إلا أن بعض أهل العلم ذكر شيئاً في هذا وهو أن الظهر والعصر تأتي في النهار في وقت العمل والناس مشغولون بأعمالهم فناسب أن تكون سرية حتى يقبل كل واحد على صلاته وحتى يشتغل بقراءته فيما بينه وبين نفسه حتى لا يشغل بشيء آخر، بخلاف ما لو جهر الإمام فإنه قد ينصت له ولكن تذهب به الهواجس والأوهام إلى أشياء أخرى، فإذا أقبل على صلاته واشتغل بقراءته كان أقرب إلى جمع قلبه على الصلاة، أما في الليل فالغالب أن الشواغل تنتهي وتقل، وهكذا الفجر بعد قيامه من النوم ما بعد شرع في المشاغل مشاغل الدنيا فيكون قلبه فارغاً وحاضراً يستمع قراءة الإمام وليستفيد من قراءة الإمام بإنصاته له، فالليل محل قلة الشغل وتواطؤ القلب مع اللسان ليستفيد ويستمع قراءة الإمام ويتدبر ما يسمع، فهذا أقرب إلى أن يسمع وإلى أن يستفيد وإلى أن يتدبر، بخلاف النهار فإنه مشغول وعنده من مشاغل الدنيا ما يقلقه عن الاستماع والإنصات، فشرع الله له أن يشتغل بنفسه وأن يقرأ بنفسه حتى لا تذهب به الوساوس إلى أشياء أخرى، هذا مما قيل في هذا، والله سبحانه وتعالى أعلم.","link":"https://binbaz.org.sa/fatwas/5526/الحكمة-من-الجهر-بالقراءة-او-الاسرار-بها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07202.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":8065,"question":"أيضاً يقول: إذا فاتته صلاة الفجر، هل يجوز قراءتها سراً أو جهراً وهي قد طلعت الشمس؟","title":"الجهر بالقراءة لمن صلى الفجر بعد طلوع الشمس","answer":"الجواب: يقرأها جهراً، لا بأس. نعم. يؤديها كما شرع الله، والنبي ﷺ لما فاتته صلاة الفجر، ولم يصلها إلا بعد الشمس، صلاها كما كان يصليها في الليل في أول النهار، كما كان يصليها بعد طلوع الفجر، يعني: يصليها كما هي، ركعتين بصلاة جهرية، ويصلي راتبتها قبلها، كما فعله النبي ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/5862/الجهر-بالقراءة-لمن-صلى-الفجر-بعد-طلوع-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_083/08307.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":8261,"question":"في بعض الأحيان -تقول- يحدث أنني أنسى أثناء الصلاة وأقرأ آية مكان آية أخرى، أو أقرأ كلمة خطأ، ثم أتذكر ذلك أثناء الركوع أو السجود أو بعد الصلاة، فما الحكم في ذلك وماذا أفعل، وهل أعيد الركعة أم لا؟","title":"ما يعمل من يخطئ في القراءة أثناء الصلاة؟","answer":"الجواب: الفرض في هذا هو الفاتحة، فإذا قرأت الفاتحة وهي الحمد؛ سورة الحمد حصل المقصود والحمد لله، فإذا قرأت زيادة آية أو آيتين أو قرأت آية بدل آية أو نسيت آية وأتيت بآية، أو نقص منك كلمة لا يضرك، وصلاتك صحيحة وليس عليك إعادة ركعة ولا إعادة الصلاة، والحمد لله، بل صلاتك صحيحة.\nولكن عليك أن تجتهدي فيما تيسر لك من قراءة بعض الآيات مع الفاتحة في الركعة الأولى والثانية من الظهر والعصر والمغرب والعشاء وهكذا في الفجر، أما الثالثة من المغرب والثالثة والرابعة من الظهر والعصر والعشاء فيكفي الفاتحة والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6071/ما-يعمل-من-يخطى-في-القراءة-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09811.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":8297,"question":"له أسئلة كثيرة كما سبق وأن قلت سماحة الشيخ، نختتم رسالته في هذه المرة بسؤاله عن أولئك الذين يجهرون بالبسملة، هل في هذا محذور؟","title":"حكم الجهر بالبسملة في الصلاة الجهرية","answer":"الجواب: لا مانع من الجهر بالبسملة، ولكن السر بها أفضل؛ ثبت عنه ﷺ أنه كان يسر بالبسملة، وهكذا كان الصديق وعمر وعثمان يسرون بها، فهذا هو الأفضل، وإذا جهر بها بعض الأحيان فقد فعل هذا بعض الصحابة ، وقد روي هذا عن النبي ﷺ، لكن المحفوظ هو السر عنه عليه الصلاة والسلام، المحفوظ عنه أنه كان يسر بها كما قال أنس : صليت خلف النبي ﷺ، وخلف أبي بكر وعمر وعثمان فكانوا لا يجهرون ببسم الله الرحمن الرحيم فمن جهر بها بعض الأحيان فلا بأس، لكن الأولى والأفضل أن يسر بها في الغالب؛ اتباعاً للنبي صلى الله عليه وسلم وتأسياً بالسلف الصالح رضي الله عنهم، وأخذاً بالأحوط والأفضل.\nالمقدم: لكن لو صلى خلف إمام يجهر بالبسملة؟\nالشيخ: لا حرج، لا حرج.\nالمقدم: لا حرج؟\nالشيخ: لا حرج.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6110/حكم-الجهر-بالبسملة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10805.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":8359,"question":"لدينا بعض الأئمة يجهرون في صلاة الفرض بالبسملة، فما حكم ذلك؟ وهل هو مكروه؛ لأن الرسول ﷺ لم يجهر بها كما يقال، ولم ينه عنها؟ وهل يأثم من اقتدى بالإمام، أفتونا جزاكم الله خيراً؟","title":"حكم الجهر بالبسملة في صلاة الفريضة","answer":"الجواب: الجهر بالبسملة خلاف السنة، والسنة أن يسر بالبسملة هذا هو المحفوظ عن النبي عليه الصلاة والسلام، كما رواه أنس وغيره عن النبي عليه الصلاة والسلام، لكن إذا جهر بها بعض الأحيان للتعليم والفائدة حتى يعلم الناس أنها تقرأ، فلا حرج في ذلك، أما استمراره عليها ومداومته على الجهر فهذا خلاف السنة، وأقل أحواله الكراهة.\nفينبغي أن ينصح من فعل ذلك ويوجه إلى الخير. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6208/حكم-الجهر-بالبسملة-في-صلاة-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11316.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":8368,"question":"إذا أطال الإمام في الركعتين الأخيرتين، هل يجوز قراءة ما تيسر من القرآن مع الفاتحة أم يسكت؟","title":"حكم القراءة بعد الفاتحة في الركعتين الأخيرتين عند إطالة الإمام","answer":"الجواب: نعم إذا أطال لا حرج في القراءة؛ لأن القيام محل قراءة، فإذا أطال الإمام قرأ المأموم ما تيسر بعد الفاتحة حتى يركع الإمام.","link":"https://binbaz.org.sa/fatwas/6217/حكم-القراءة-بعد-الفاتحة-في-الركعتين-الاخيرتين-عند-اطالة-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11408.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":8400,"question":"هل على من يصلي النوافل هل عليه قراءة شيء من القرآن غير الفاتحة، وأنا أداوم في ركعتي الفجر خاصة على سورتي الإخلاص؟","title":"حكم قراءة شيء بعد الفاتحة في صلاة النافلة","answer":"الجواب: المشروع لمن كان يصلي النافلة في الليل أو في النهار، أن يقرأ مع الفاتحة ما تيسر، هذا هو الأفضل، أما الوجوب فلا تجب إلا الفاتحة، لا يجب إلا الفاتحة، هي ركن في الصلاة إذا قرأها كفت، ولكن إذا قرأ معها زيادة آيات أو سوراً أخرى كان أفضل؛ كان النبي ﷺ يقرأ الفاتحة ويقرأ معها زيادة عليه الصلاة والسلام، ويقول ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب فصاعداً» فالأصل هو الفاتحة، ولهذا قال عليه الصلاة والسلام: «لا صلاة لمن لم يقرأ بفاتحة الكتاب فالسنة للمؤمن إذا قرأها أن يقرأ معها زيادة هذا هو الأفضل.\nوفي سنة الفجر يقرأ معها سورتي: (قل يا أيها الكافرون)، و (قل هو الله أحد)، في الأولى: (قل يا أيها الكافرون)، وفي الثانية: (قل هو الله أحد)، وإن قرأ مع الفاتحة آية البقرة: قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا... [البقرة:136] الآية، وآية آل عمران: قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ... [آل عمران:64] الآية، فهذا أيضاً سنة، فعل النبي هذا وهذا عليه الصلاة والسلام، كان تارة يقرأ السورتين: (قل يا أيها الكافرون)، و(قل هو الله أحد)، وتارة يقرأ الآيتين المذكورتين آنفاً، وإن قرأ غير ذلك فلا بأس أيضاً، ولكن الأفضل أن يقرأ ما قرأه النبي عليه الصلاة والسلام في سنة الفجر، وهكذا في سنة المغرب يقرأ: (قل يا أيها الكافرون)، و(قل هو الله أحد) يعني: بعد الفاتحة، وهكذا في سنة الطواف إذا طاف بالكعبة فالأفضل أن يقرأ سورتي الإخلاص: (قل يا أيها الكافرون)، و(قل هو الله أحد) بعد الفاتحة؛ اقتداءً بالنبي عليه الصلاة والسلام في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/6273/حكم-قراءة-شيء-بعد-الفاتحة-في-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11705.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":8416,"question":"إحدى الأخوات المستمعات أيضاً من العراق بعثت برسالة وفيها مجموعة من الأسئلة في سؤال لها تقول: لي مجموعة من أدعية الرسول ﷺ، لكني لا أحفظها، هل تصح قراءتها من الورقة أو لا؟","title":"حكم قراءة الأدعية لتعذر حفظها وحكم القراءة من المصحف في الصلاة","answer":"الجواب: لا مانع، لا مانع أن يقرأ الإنسان الدعاء من الورقة، إذا كان لا يحفظ، وكتب الدعاء في ورقة وقرأها في الأوقات التي يحب أن يقرأ مثل: آخر الليل، مثل: في أثناء الليل، في غير هذا لا بأس، ولكن إذا تيسر حفظ ذلك، وأن يقرأه عن حضور قلب وعن خشوع، كان ذلك أكمل، وقراءته من الورقة لا بأس بها. نعم.\nالمقدم: طيب والقراءة سواء كانت أثناء الصلاة أو خارج الصلاة؟\nالشيخ: لا، في الصلاة الأولى أن تكون عن حفظ، ..... أن تكون دعوات مختصرة موجزة تحفظها هذا أفضل، ولو قرئت من ورقة مثل التشهد، أو في بين السجدتين، ما يضر ذلك لا حرج في ذلك، لكن كونها تحفظ ذلك، كون الداعي يحفظ ذلك يكون أقرب إلى الخشوع. نعم.\nالمقدم: بارك الله فيكم، يقاس على هذا قراءة القرآن سماحة الشيخ؟\nالشيخ: كذلك لو قرأ القرآن من المصحف لا بأس مثل في التراويح قيام رمضان؛ لأنه قد يحتاج إلى طول القراءة، فإذا قرأ من المصحف فلا بأس على الصحيح، وقد كان مولى عائشة رضي الله عنها يصلي بها من المصحف في رمضان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6300/حكم-قراءة-الادعية-لتعذر-حفظها-وحكم-القراءة-من-المصحف-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11807.mp3","categories":["الأدعية والأذكار","القراءة في الصلاة"]},{"id":8734,"question":"أخونا أيضًا يسأل يقول: إنني شاب في الثامنة والعشرين من عمري ومحافظ -ولله الحمد- على الصلوات جماعة، لكني أرغب أيضًا في كثير من المعلومات، فمثلًا: أسألكم عندما يقرأ الإمام الفاتحة وبعدها يقرأ سورة طويلة، في تلك اللحظات هل أسأل الله سبحانه وتعالى بعض الدعاء، أم أقرأ، أم أنصت؟","title":"حكم الإنصات للإمام عند قراءته في الصلاة","answer":"الجواب: الواجب الإنصات؛ لقول الله سبحانه: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204] ولقول النبي ﷺ: إذا قرأ الإمام فأنصتوا إلا الفاتحة فإنه يقرؤها، سواء كان سكت الإمام أو ما سكت يقرؤها، إن كان يسكت قرأها في السكتات، فإن كان يتابع القراءة قرأها ثم أنصت؛ لقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب ولقوله ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها فيقرأ بها سرًا ثم ينصت لإمامه. نعم.","link":"https://binbaz.org.sa/fatwas/6888/حكم-الانصات-للامام-عند-قراءته-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_161/16106.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":8897,"question":"هنا رسالة وصلت إلى البرنامج من الأردن وباعثها أخونا حسن حسين سالم أبو رياش أخونا يقول: هل تجوز قراءة الفاتحة مع الإمام في الصلاة الجهرية علماً بأن الإمام لا يترك فرصة للمؤتمين لقراءتها بل يبدأ بقراءة القرآن بعد انتهاء المؤتمين من قول آمين مباشرة. أفيدونا أفادكم الله؟","title":"وقت قراءة المأموم للفاتحة","answer":"الجواب: نعم، يقرأ المأموم الفاتحة وإن كان الإمام يقرأ؛ لأنه مأمور بذلك، يقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب متفق عليه، ويقول ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم. قال: لا تفعلوا إلا بفاتحة الكتاب فإنه لا صلاة لمن لم يقرأ بها، فعلى المأموم أن يقرأ بها إن كان الإمام سكت فيقرؤها في حال سكوته، وإن قرأ يقرؤها وإن كان يقرأ الإمام ثم ينصت عملاً بالأحاديث كلها، فينصت بعد قراءتها ولا حرج عليه في ذلك وهذا هو الصواب، قال بعض أهل العلم: إنها تسقط عنه واحتجوا بحديث ضعيف عن النبي ﷺ أنه قال: من كان له إمام فقراءته له قراءة، لكنه حديث ضعيف عند أهل العلم، والصواب أنه يقرأ المأموم في حال سكتات الإمام إن سكت، وإلا فليقرأ وإن كان يقرأ الإمام ثم ينصت، هذا هو المختار، وهذا هو الصواب. نعم.","link":"https://binbaz.org.sa/fatwas/7053/وقت-قراءة-الماموم-للفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_140/14009.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9144,"question":"وصلت إلى البرنامج رسالة من المستمعة (ف. ع. س) من اليمن الشمالي تعز، تقول في رسالتها: إنني امرأة لا أحفظ الكثير من القرآن عند الصلاة، فما حكم الشرع في هذا وأنا لم أتعلم، فكيف أؤدي صلاتي، أفيدونا أفادكم الله؟","title":"ما المشروع في قراءة الصلاة لمن لا يحفظ إلا القليل؟","answer":"الجواب: يكفيك أيها الأخت في الله أن تقرئي الفاتحة: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الْرَّحمَنِ الْرَّحَيمِ ۝ مَالِكِ يَوْمِ الدِّينِ [الفاتحة:2-4]، إلى آخرها، تقرأينها تكفي، وإن تيسر معها زيادة مثل: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] .. قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] ..قُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] أو غيرها من السور أو بعض الآيات فهذا خير إلى خير، في الركعة الأولى والثانية من الظهر والعصر والمغرب والعشاء وفي الفجر أيضاً، أما الثالثة من المغرب والثالثة والرابعة من الظهر والعصر والعشاء تكفيك فيها الفاتحة الحمد، ولا يلزمك شيء أكثر من هذا، الحمد هي الركن اللازم، وما زاد فهو مستحب، والحمد لله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7307/ما-المشروع-في-قراءة-الصلاة-لمن-لا-يحفظ-الا-القليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23010.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9173,"question":"المرسل عجب خلف الغنامي من عفيف، سماحة الوالد البار عبد العزيز بن عبد الله بن باز أطال الله بقاءه.. آمين، السلام عليكم ورحمة الله وبركاته وبعد: فأرجو من الله أن يطيل بقاءكم ذخراً لهذه الأمة وهادياً إلى الله ووالداً للجميع، سؤالي: عندما يقول الإمام إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، يقول المأموم: استعنا بالله، فما الحكم في هذا القول؟","title":"حكم قول المأموم: استعنا بالله أثناء قراءة الإمام للفاتحة","answer":"الجواب: لا أعلم ما يدل على شرعيته، والأولى بالمأموم أن ينصت وأن لا يقول هذه الكلمة استعنا بالله؛ لأنه لا دليل عليها، فالأولى والأفضل له أن يسكت عن ذلك ولا يقول هذا الكلام ولو قاله ما يضر صلاته صلاته صحيحة، لكن ترك ذلك هو الأولى لأنه لا دليل على شرعية ذلك من المأموم، وإنما المشروع له أن ينصت لإمامه ويتدبر ما يقوله إمامه حتى يستفيد؛ لقول الله سبحانه: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204]، والنبي ﷺ يقول: إذا قرأ الإمام فأنصتوا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7333/حكم-قول-الماموم-استعنا-بالله-اثناء-قراءة-الامام-للفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_150/15007.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9354,"question":"ما هي المواضع التي يجهر فيها المأموم بالقراءة خلف الإمام؟","title":"حكم جهر المأموم بالقراءة","answer":"الجواب: المأموم لا يجهر خلف الإمام وإنما يقرأ سرًا، وإنما الإمام هو الذي يجهر في المغرب والعشاء والفجر والجمعة والعيد، يجهر في الأولى والثانية من العشاء، والمغرب، ويجهر في الفجر أيضًا، ويجهر في الجمعة، ويجهر في صلاة العيد، وصلاة الكسوف، وصلاة الاستسقاء، والمأموم يقرأ سرًا بينه وبين نفسه ولا يجهر، هذا هو المشروع. نعم.","link":"https://binbaz.org.sa/fatwas/7518/حكم-جهر-الماموم-بالقراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18509.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9361,"question":"من جمهورية مصر العربية رسالة باعثها أحد الإخوة من هناك رمز إلى اسمه بالحروف: (ن. ح. ع) أخونا له ثلاثة أسئلة.في سؤاله الأول يقول: أسمع بعض الناس في الصلاة الجهرية يبدأ بالفاتحة مباشرة دون أن يسمي، أي: لم يذكر البسملة فما هو التوجيه في هذا؟","title":"حكم الإسرار بالبسملة أثناء القراءة في الصلاة الجهرية","answer":"الجواب: المشروع للمؤمن والمؤمنة أن يبدأ بالتعوذ، ثم التسمية، ثم القراءة، فإذا كبر للصلاة أولًا استفتح بما شرعه الله من الاستفتاحات التي ثبتت عن رسول الله عليه الصلاة والسلام، ومنها: وهو أخصرها: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك ومنها: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد وهناك استفتاحات أخرى ثابتة عن رسول الله عليه الصلاة والسلام، فالأفضل أن يستفتح بواحد منها، هذا هو الأفضل وإن ترك ذلك فلا حرج.\nثم يقول: أعوذ بالله من الشيطان الرجيم، أو أعوذ بالله السميع العليم من الشيطان الرجيم، ثم يقول: بِسْمِ اللَّهِ الْرَّحمَنِ الْرَّحَيمِ  ثم يقرأ الفاتحة، هذا هو المشروع، ولو قرأ من دون استفتاح ولا تعوذ ولا تسمية صحت القراءة؛ لأن التسمية سنة، والتعوذ سنة، والاستفتاح سنة، لكن الأفضل له والسنة له أن يأتي بهذه الأمور، يستفتح، ثم يستعيذ، ثم يسمي، ثم يقرأ، هذا هو المشروع، وهذا هو الكمال. نعم.\nالمقدم: يسأل أخونا عن الصلاة الجهرية يا سماحة الشيخ، يقول: لم أسمعهم يذكروا بسم الله الرحمن الرحيم في الصلوات الجهرية؟\nالشيخ: السنة في الجهرية أن لا يجهر، يقرأ التسمية والتعوذ لكن سرًا هذا هو الأفضل؛ لأن الرسول ﷺ كان يسر بها، وهكذا خلفاؤه الراشدون: الصديق، وعمر، وعثمان، وعلي كانوا يسرون، فالسنة الإسرار بها.\nوقد ورد عن أبي هريرة  ما يدل على أن الرسول ربما جهر بها عليه الصلاة والسلام في بعض الأحيان، فإذا جهر بها الإنسان في بعض الأحيان للبيان والتعليم فلا حرج في ذلك، ولكن الأفضل أن يكون الغالب عليه أن يسر بها اقتداءً بالنبي عليه الصلاة والسلام في ذلك.","link":"https://binbaz.org.sa/fatwas/7525/حكم-الاسرار-بالبسملة-اثناء-القراءة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18603.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9537,"question":"وهذه رسالة وردت من السائل (م. س. ع) من العراق -الموصل-، يقول في رسالته: قرأت في كتاب صفة الصلاة للألباني قول الرسول ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب، ولفظ آخر: لا تجزئ صلاة لا يقرأ الرجل فيها بفاتحة الكتاب،  ما معنى الصلاة هنا؟ هل هي الركعة الواحدة أم أن الصلاة كلها تبطل، أفيدونا أفادكم الله؟","title":"حكم قراءة الفاتحة في كل ركعة في الصلاة","answer":"الجواب: إذا ترك الفاتحة بطلت الصلاة، كان إماماً أو منفرداً، إذا تعمد ذلك بطلت إما إذا كان ساهياً قامت الأخرى مقامها وزاد ركعة، أما إذا كان عامداً تعمده وهو يعلم حكم الشرع في ذلك تبطل صلاته، إما إذا كان ساهياً فإنها لا تبطل صلاته لكن يأتي بركعة إذا لم ينتبه إلا بعد فراغه من الركعة يأتي بركعة أخرى بدلاً من التي ترك فيها القراءة، أما المأموم فإن الواجب عليه أن يقرأها على الصحيح، يقرؤها مع إمامه أو في سكتات إمامه، فإن لم يقرأها جاهلاً أو ناسياً أو مقلداً لمن يرى أنها لا تجب على المأموم فلا شيء عليه، أو جاء المأموم والإمام راكع ولم يتمكن من قراءتها أو قرب الركوع ولم يتمكن من قراءتها فلا حرج عليه، لأنه ثبت عنه ﷺ أنه أقر أبا بكرة لما جاء والإمام راكع، ركع معه أبو بكرة -عليه الصلاة والسلام- ولم يأمره بقضاء الركعة عليه الصلاة والسلام، دل ذلك على أنه معذور واحتج به الجمهور على أن الفاتحة لا تجب على المأموم، ولكن عموم الأدلة تدل على وجوبها على المأموم إلا أنه معذور إذا فاته القيام أو نسي أو كان جاهلاً فيتحملها عنه الإمام. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7709/حكم-قراءة-الفاتحة-في-كل-ركعة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24608.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9542,"question":"يسأل أيضاً ويقول: أنا أبدأ صلاتي بالبسملة قبل الفاتحة وقبل السورة التي تليها في كل ركعة، فهل من حرج في ذلك؟","title":"حكم البسملة في الصلاة قبل كل سورة","answer":"الجواب: هذا هو المشروع، المشروع للمؤمن أن يسمي في أول كل سورة، في الفاتحة وغيرها ويستعيذ بالله من الشيطان الرجيم أول ما يقرأ، ثم يأتي بالتسمية ثم يقرأ الفاتحة، وهكذا في السور الأخرى يسمي وإن أعاد التعوذ فلا بأس وإن تركه كفاه التعوذ في أول صلاته، وأما التسمية فيسن تكرارها عند كل سورة؛ لأن النبي عليه السلام كان يقرؤها في أول كل سورة عليه الصلاة والسلام، ولكن يسر بها في الجهرية إذا كان إمام يسر بها الأفضل أن يسر بها؛ لأن الرسول كان يسر بها عليه الصلاة والسلام، وإن جهر بعض الأحيان ليعلم الناس أنه يقرؤها للفائدة فلا بأس كما جهر بها بعض الصحابة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7706/حكم-البسملة-في-الصلاة-قبل-كل-سورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24605.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9545,"question":"يسأل أيضاً ويقول: أنا أبدأ صلاتي بالبسملة قبل الفاتحة وقبل السورة التي تليها في كل ركعة، فهل من حرج في ذلك؟","title":"حكم البسملة في الصلاة قبل كل سورة","answer":"الجواب: هذا هو المشروع، المشروع للمؤمن أن يسمي في أول كل سورة، في الفاتحة وغيرها ويستعيذ بالله من الشيطان الرجيم أول ما يقرأ، ثم يأتي بالتسمية ثم يقرأ الفاتحة، وهكذا في السور الأخرى يسمي وإن أعاد التعوذ فلا بأس وإن تركه كفاه التعوذ في أول صلاته، وأما التسمية فيسن تكرارها عند كل سورة؛ لأن النبي عليه السلام كان يقرؤها في أول كل سورة عليه الصلاة والسلام، ولكن يسر بها في الجهرية إذا كان إمام يسر بها الأفضل أن يسر بها؛ لأن الرسول كان يسر بها عليه الصلاة والسلام، وإن جهر بعض الأحيان ليعلم الناس أنه يقرؤها للفائدة فلا بأس كما جهر بها بعض الصحابة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7706/حكم-البسملة-في-الصلاة-قبل-كل-سورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24605.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9648,"question":"هذا السائل صالح عبد الله يقول: ما حكم إنسان تذكر وهو ساجد بأنه لم يقرأ الفاتحة ماذا يفعل؟","title":"حكم من نسي الفاتحة في الصلاة","answer":"الجواب: عليه أن يأتي بركعة زائدة، يكمل صلاته ويأتي بركعة زائدة يقرأ فيها الفاتحة بدل التي ترك منها الفاتحة؛ لأنها بطلت التي ترك منها الفاتحة، فيأتي بركعة بدالها ويسجد للسهو، وينبه الذين وراءه يقومون حتى يتابعوه بالإشارة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7814/حكم-من-نسي-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27204.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9667,"question":"السؤال الثالث في رسالة الأخت إستبرق من العراق تقول فيه: هل يجوز الجهر في الصلاة السرية أفيدونا أفادكم الله؟","title":"هل يجوز الجهر في الصلاة السرية؟","answer":"الجواب: يجوز لكن السر أفضل، قد كان النبي يجهر في بعض الأحيان في السرية ﷺ ويسمعهم الآية لكن الأغلب كان يسر عليه الصلاة والسلام، هذا هو السنة، الإسرار في السرية كالظهر والعصر ولكن إذا جهر بعض الأحيان بعض الآيات هذا أفضل. نعم.","link":"https://binbaz.org.sa/fatwas/7833/هل-يجوز-الجهر-في-الصلاة-السرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19415.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9675,"question":"نفس السائل أيضاً يقول: بأنني صليت الظهر لوحدي وفي الركعة الثانية لم أقرأ سوى الفاتحة نسياناً، يعني لم أقرأ بعدها سورة من القرآن الكريم، فتذكرت قبل السلام، فسجدت سجدتين للسهو، فهل علي حرج في هذا؟","title":"حكم قراءة سورة بعد الفاتحة في الصلاة","answer":"الجواب: ليس عليك حرج ولا يجب عليك سجود السهو؛ لأن قراءة السورة ليست واجبة إنما المهم قراءة الفاتحة، أما قراءة سورة بعدها أو آيات بعدها فهو مستحب فقط، فإذا تركه الإنسان لم يجب عليه سجود السهو، وإن سجد فلا بأس والحمد لله، صلاتك صحيحة ولا حرج عليك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7863/حكم-قراءة-سورة-بعد-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_253/25305.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9720,"question":"هذا السائل من الأحساء (د. ع) يقول: من فاتته صلاة الفجر فصلاها بعد طلوع الشمس، هل يسر بصلاته أم يجهر بها؟","title":"حكم الجهر بالقراءة في الفجر لمن صلاها بعد الشروق","answer":"الجواب: يجهر، إذا صلاها بعد طلوع الشمس يجهر بها، النبي ﷺ لما نام هو وأصحابه عن صلاة الفجر في بعض الليالي في بعض الأسفار صلاها بعد ارتفاع الشمس وجهر بالقراءة عليه الصلاة والسلام، فالسنة الجهر بالقراءة، نعم، القضاء يحكي الأداء.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7875/حكم-الجهر-بالقراءة-في-الفجر-لمن-صلاها-بعد-الشروق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27212.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9831,"question":"سؤالها الأخير أو الثاني تقول: إنني أدرس في مرحلة التكميل وأتمنى أن أقرأ القرآن لكنني لا أقدر بل أقرأ الجزء أو مثل سورة الكوثر أو النصر وهكذا عندما أركع في الفجر وغيره من الصلوات ما حكم صلاتي هذه إذا لم أستطع أن أقرأ بعد الفاتحة بشيء صحيح؟","title":"حكم الزيادة على قراءة الفاتحة في الصلاة","answer":"الجواب: الفرض في الصلاة الفاتحة هي ركن الصلاة كما قال النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب فالفاتحة هي ركن الصلاة سواء كانت فريضة أو نافلة والباقي سنة، فإذا كانت لا تحسن إلا الفاتحة كفتها الفاتحة وصلاتها صحيحة، سواء كانت فرضاً أو نفلاً والحمد لله، لكن إذا تيسر لها أن تحفظ جملة من السور فذلك خير لها وأفضل حتى تقرأ مع الفاتحة ما تيسر وكلما زادت في حفظ ما تيسر من السور كان أفضل لها وخيراً لها، فأنا أوصي السائلة أن تجتهد في حفظ ما تيسر من القرآن مثل جزء عم وما تيسر معه حتى تقرأ بذلك في صلواتها، فإن لم يتيسر لها ذلك فإنها تكفيها الفاتحة والحمد لله.\nالمقدم: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8006/حكم-الزيادة-على-قراءة-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_261/26106.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":9903,"question":"هذه الرسالة وصلت من جمهورية غينيا كوناكري، السائل: عبدالله محمد باري ومقيم بأنجولا يقول: أسمع في بعض المساجد الكثير من المصلين يرفعون أصواتهم حين يقرأ الإمام: مُحَمَّدٌ رَسُولُ اللَّهِ وَالَّذِينَ مَعَهُ [الفتح:29] الآية، ويقولون: ﷺ، وكذلك في آخر سورة التين، يقولون بصوت مرتفع: بلى ونحن على ذلك من الشاهدين، أفيدونا بهذا مأجورين؟","title":"حكم رفع المؤتمين أصواتهم عند قراءة الإمام: {مُحَمَّدٌ رَسُولُ اللَّهِ}","answer":"الجواب: السنة الإنصات ، وعدم رفع الصوت لا بالصلاة على النبي ﷺ ولا ببلى ونحن مع من الشاهدين، السنة للمأمومين الإنصات وعدم رفع الصوت بشيء؛ لأن الله يقول: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204] ولم ينقل عن الصحابة رضي الله عنهم وأرضاهم أنهم كانوا يرفعون أصواتهم معه ﷺ ، فالمشروع الإنصات، والتدبر، والتعقل وعدم رفع الصوت، كقولهم عند قوله: مُحَمَّدٌ رَسُولُ اللَّهِ [الفتح:29] ﷺ ، أما بينه وبين نفسه فالأمر أوسع ، بينه وبين نفسه الأمر سهل، لو ترك لكان الأفضل وإن فعل فلا بأس ، لكن لم ينقل عنه ﷺ في الفريضة أنه كان يقف فيصلي على النبي ﷺ أو يدعو إنما كان هذا في التهجد ، كان يفعله في التهجد بالليل، وهكذا: أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ [التين:8] لا يقل: بلى وأنا على ذلك من الشاهدين لأن الحديث ضعيف، ولكن يقول: سبحانه وبحمده أو سبحانه وتعالى بينه وبين نفسه، لا بأس، كذلك الآية الكريمة آخر القيامة: أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى [القيامة:40]هذا ورد فيها حديث صحيح ، فإذا قال: بلى ، لا بأس؛ لأنه ورد في الحديث الصحيح في آخر القيامة أن يقول ذلك، وأما آخر التين ، وآخر المرسلات، فلم يثبت فيها حديث ، ولكن ينصت ويستمع ويحضر قلبه ولا يتكلم فهذا هو الأفضل؛ لأن الصحابة كانوا ينصتون ، والله أمر بهذا بقوله: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا لَعَلَّكُمْ تُرْحَمُونَ[الأعراف:204] لكن لو سبح بينه وبين نفسه أو دعا بينه وبين نفسه فالأمر في هذا إن شاء الله لا حرج فيه، لفعله ﷺ له في صلاة الليل.","link":"https://binbaz.org.sa/fatwas/8071/حكم-رفع-الموتمين-اصواتهم-عند-قراءة-الامام-محمد-رسول-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27315.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":10130,"question":"تسأل وتقول: هل يجوز مسك المصحف الشريف في الصلاة والقراءة منه بعد الفاتحة؟","title":"حكم القراءة من المصحف في الصلاة","answer":"الجواب: إذا دعت الحاجة إلى ذلك لا بأس، مثل التراويح والقيام في رمضان لا حرج، وإذا كان الإنسان يقرأ عن ظهر قلب يكون أخشع إذا تيسر له ذلك، فإذا دعت الحاجة إلى أن يقرأ من مصحف لكونه إماماً أو المرأة ويتهجد بالليل أو الرجل كذلك وهو لا يحفظ فلا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8305/حكم-القراءة-من-المصحف-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30511.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":10161,"question":"هل تجوز الصلاة بقراءة الفاتحة فقط؟","title":"هل تجوز الصلاة بقراءة الفاتحة فقط؟","answer":"الجواب: نعم؛ إذا لم يقرأ إلا الفاتحة صحت صلاته، جميع الصلوات الخمس إذا لم يقرأ إلا الفاتحة صحت؛ لأنها ركن في الصلاة وما زاد عليها مستحب ليس بواجب، لكن السنة أن يزيد عليها في الأولى والثانية من الظهر والعصر والمغرب والعشاء والسنة أن يزيد عليها في الفجر أيضاً هذا السنة؛ لأن الرسول كان يزيد عليها عليه الصلاة والسلام، لكنه قال: لا صلاة لمن لم يقرأ بفاتحة الكتاب فدل على أنها ركن والباقي مستحب. نعم.\nالمقدم: جزاكم الله خيراً، من لم يقرأ الفاتحة في صلاته -سماحة الشيخ- كيف توجهونه لو سمحتم؟\nالشيخ: أما إذا كان إماماً أو منفرداً فإن صلاته غير صحيحة لابد يعيدها؛ لأن الفاتحة ركن الصلاة.\nالمقدم: ولا يجبرها شيء؟\nالجواب: أبداً، لابد من إعادتها، أما إذا كان مأموم فإن العلماء اختلفوا في المأموم هل تلزمه الفاتحة أم لا، والأكثرون على أنها لا تلزمه وأن الإمام يقوم مقامه في ذلك، والصواب أنه تلزمه، الصواب أنها تلزمه الفاتحة يقرؤها ولو مع الإمام، يقرؤها مع الإمام ثم ينصت إذا إذا كان في الجهرية لعموم قوله عليه الصلاة والسلام: لا صلاة لمن لم يقرأ بفاتحة الكتاب، ولأنه عليه الصلاة والسلام: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب فإنه لا صلاة لمن لم يقرأ بها فهذا نص في المأمومين، نص وهو صحيح، فوجب الأخذ به، لكن لو فاته القيام لأنه تأخر لم يأت إلا في الركوع أجزأه؛ لأن النبي ﷺ لما دخل أبو بكرة والنبي ﷺ راكع فركع دون الصف ثم دخل في الصف لم يأمره بقضاء الركعة لأنه معذور بفوات القيام، ومثله من كان مع الإمام ولكن سها عن قراءة الفاتحة أو يعتقد قول الجمهور أنها لا تجب عليه صلاته صحيحة، أو جاهل بالحكم الشرعي فلم يقرأ يحسب أنه لا يلزمه القراءة مع الإمام هذا صلاته صحيحة كالذي جاء والإمام راكع بجامع العذر، جامع العذر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8329/هل-تجوز-الصلاة-بقراءة-الفاتحة-فقط ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30710.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":10170,"question":"يقول: إنني أعيد قراءة الفاتحة عدة مرات أثناء الصلاة لأنني أخطئ في قراءتها، فما حكم ما فعلت؟","title":"حكم إعادة قراءة الفاتحة لمن يخطئ فيها","answer":"الجواب: هذا غير مشروع، السنة أن تقرأ مرة واحدة، تقرأها قراءة مرتلة تدبرها وتعقلها حتى تؤدي الحروف كما ينبغي، أما التكرار فمكروه، لكن إذا غلطت فيها تعيد ما غلطت فيه، إذا غلطت في آية تعيد الآية وما بعدها، أما أن تكررها يعني من باب الوسوسة هذا لا ينبغي، بل هو مكروه، وكذلك من باب الاحتياط مكروه، كان النبي يقرؤها مرة واحدة عليه الصلاة والسلام وهكذا أصحابه رضي الله عنهم وأرضاهم، والخير كله في اتباعه صلى الله عليه وسلم واتباع أصحابه، والبدعة كلها شر. فأنت إذا تيقنت غلطاً في آية تعيد الآية بإصلاح الخطأ ولا تعيد السورة كلها، فإذا قلت مثلاً: إياك نعبد.. تعيد تقول: إياك نعبد أو قلت: اهدنا الصراطُ المستقيم، تعيدها: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ، مع أن الرفع لا يضر في هذا، ما يغير المعنى، أو قلت: الحمد لله رب َالعالمين، ثم انتبهت وعدت قلت: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ بالخفض هذا هو الصواب، ولكن النصب لا يضر، لو قلت: الحمد لله ربَ العالمين ما يضر الفاتحة لأن المعنى لا يتغير، أو قلت: الحمد لله ربُ العالمين ما يضر المعنى.\nفالحاصل أن اللحن اللي ما يغير المعنى ولا يؤثر في المعنى لا يضر القراءة، لكن لو أعاد الآية فأصلحها على الوجه الأكمل لا بأس، أما الذي يحيل المعنى فلابد من إعادة الآية، لو قرأ: أهدنا بفتح الهمزة أهدنا يعيد الآية يقول: اهْدِنَا يعيدها بكسر الهمزة: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ، أو قرأ: إياكِ نعبد هذا غلط ..يخاطب المرأة ما يصلح، لابد يعيد القراءة يقول: إِيَّاكَ نَعْبُدُ أو قرأ: صراط الذين أنعمتُ هذا غلط يعيد الآية يقول: صِرَاطَ الَّذِينَ أَنْعَمْتَ يخاطب الرب جل وعلا، أو يقول: أنعمتِ هذا غلط خطاب مرأة، هذا يعني ضمير امرأة ... أنعمتِ ما يجوز يغير المعنى لابد يعيد الكلمة يقول: صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ يخاطب الرب جل وعلا هو المنعم سبحانه وتعالى.\nفالحاصل أن اللحن الذي يغير المعنى يجب أن يعيد الآية حتى يصلح اللحن، ولا حاجة إلى أن يعيد السورة كلها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8344/حكم-اعادة-قراءة-الفاتحة-لمن-يخطى-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30805.mp3","categories":["القراءة في الصلاة"," الوسواس بأنواعه"]},{"id":10226,"question":"سؤال طويل ملخصه: هل يجب ترتيب السور في القراءة أثناء الصلاة، أو لا يجب؟","title":"حكم ترتيب السور عند قراءتها في الصلاة","answer":"الجواب: السنة الترتيب، كما رتب الصحابة المصحف، هذا هو الأفضل، ومن نكس فلا حرج، لو قرأ آل عمران، ثم قرأ من البقرة؛ فلا حرج، لكن الأفضل أن يسير على ما رتب الصحابة رضي الله عنهم وأرضاهم حين جمعوا القرآن في عهد عثمان ، إذا قرأ البقرة يقرأ بعدها من آل عمران، أو ما بعد ذلك، وإذا قرأ مثلاً سورة: لم يكن، يقرأ ما بعدها: الزلزلة، العاديات، وهكذا. هذا هو الأفضل على ترتيب المصحف، لكن لو نكس، وقرأ من آخر القرآن ثم قرأ من مقدم القرآن فلا حرج في ذلك، جاء عن عمر  أنه قرأ في الأولى بسورة النحل من صلاة الفجر، وفي الثانية سورة يوسف. وهي قبلها، وقرأ النبي ﷺ في بعض الليالي بالبقرة، ثم النساء، ثم آل عمران. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8390/حكم-ترتيب-السور-عند-قراءتها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31007.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":10318,"question":"يقول: إذا كان الإنسان يصلي منفرداً في الصلاة الجهرية فهل يجهر بالقراءة؟ وهل يشمل الجهر التكبيرات أم لا؟","title":"حكم جهر المنفرد بالقراءة والتكبيرات في الصلاة الجهرية","answer":"الجواب: نعم يجهر بالقراءة، إذا كان يصلي جهريةً كالفجر والثنتين الأولى من المغرب والعشاء فإنه يجهر هذه السنة يجهر بالقراءة جهراً مناسباً، لا يشوش على من حوله إن كان حوله مصلون أو إن كان حوله قراء يكون جهره لا يشوش عليهم، أما التكبير فلا حاجة إلى الجهر به؛ لأن التكبير يجهر به في حق الإمام حتى يسمع المأمومون، أما إذا كان يصلي وحده فلا حاجة إلى الجهر بذلك يكبر تكبيراً ليس فيه جهر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8489/حكم-جهر-المنفرد-بالقراءة-والتكبيرات-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31402.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":10367,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الضفة الغربية بفلسطين المحتلة، بعثت بالرسالة إحدى الأخوات المستمعات من هناك تقول (ع. م. الخطيب )، أختنا لها جمع من الأسئلة في أحدها تقول: ذكر سيد سابق أن المداومة في صلاة المغرب على قصار المفصل دائمًا فعل مروان بن الحكم وهو خلاف السنة، بالعكس من النووي الذي ذكر أن ذلك هو السنة، فما هو الصحيح؟","title":"حكم المداومة على قراءة قصار المفصل في صلاة المغرب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول، الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالصواب هو ما ذكره الـسيد سابق ؛ لأن الرسول عليه الصلاة والسلام ما كان يحافظ على قصار المفصل، بل تارة يقرأ من قصار المفصل وتارة يقرأ من طوال المفصل، وتارة يقرأ بغير ذلك من غير المفصل، فالأفضل للإمام في المغرب أن يقرأ تارة كذا وتارة كذا، اقتداءً بالنبي عليه الصلاة والسلام، فلا يلازم المفصل ولا يلازم طوال المفصل ولا أوساطه ولكن تارة وتارة، يتأسى بالنبي عليه الصلاة والسلام في ذلك، فقد ثبت عنه ﷺ أنه كان يقرأ بقصار المفصل، في المغرب وثبت عنه عليه الصلاة والسلام أنه قرأ فيها بالمرسلات في آخر حياته، وهي ليست من قصار المفصل بل هي من طواله، وقرأ فيها بالطور، وهي من طوال المفصل أيضًا، وقرأ فيها بالأعراف قسمها لركعتين وهي سورة طويلة.\nفعلم بذلك أن السنة أن يقرأ فيها تارة بقصار وتارة بغيرها فلا يلزم حالة معينة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8539/حكم-المداومة-على-قراءة-قصار-المفصل-في-صلاة-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33901.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":10372,"question":"قد يسهو الإنسان في الصلاة، فيسأل هل قرأت بالفاتحة أم لا؟ فهل إذا قرأها بعد السورة تعتبر كمن قرأها قبلها؟ أم كيف يكون الحال؟","title":"حكم إعادة قراءة الفاتحة عند الشك","answer":"","link":"https://binbaz.org.sa/fatwas/8543/حكم-اعادة-قراءة-الفاتحة-عند-الشك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33904.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":10373,"question":"قال النووي في كتاب الأذكار: اعلم أن الأذكار المشروعة في الصلاة وغيرها واجبة كانت أو مستحبة لا يحسن منها شيء، ولا يعتد به يتلفظ به حتى يسمع نفسه، إذا كان صحيح السمع لا عارض له؟ انتهى.","title":"عند القراءة في الصلاة هل يشترط إسماع النفس؟","answer":"الجواب: نعم نعم، مثلما قال لا بد من لفظ يسمع نفسه إذا كان صحيح السمع، أما قراءته بمجرد حركة اللسان من دون إسماعه نفسه فلا تعتبر؛ لأنها ليست قراءة وإنما هي حركة اللسان فقط، لكن لابد من قراءة تسمع، يسمعها صاحب السمع، حتى تكون قراءته تعتبر قراءة، سواءً كانت قراءة الفاتحة أو قراءة السور أو التسبيح في الركوع والسجود، أو الدعاء بين السجدتين أو في آخر الصلاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8545/عند-القراءة-في-الصلاة-هل-يشترط-اسماع-النفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33905.mp3","categories":["الأدعية والأذكار","القراءة في الصلاة"]},{"id":10416,"question":"ما هو حكم المصلي خلف الإمام في الصلوات الجهرية، هل يستمع فقط أم يصلي الصلاة كما وجبت عليه إذا صلى منفردًا، إذ أنني أسمع بعض المصلين يعيدون الفاتحة بعد الإمام بسرعة حيث لا يتدبرون معناها؟","title":"حكم قراءة المأموم الفاتحة في الصلاة","answer":"الجواب: المسألة فيها خلاف بين العلماء والصواب أنه يقرأ في الجهرية والسرية جميعًا، إن سكت إمامه قرأ في السكوت، وإن لم يسكت إمامه قرأها ثم أنصت، لقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب، ولقوله ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها، وهذا عام في الجهرية والسرية، لكن يقرؤها سراً ثم ينصت.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8589/حكم-قراءة-الماموم-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28017.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":10431,"question":"يقول في سؤال له أيضًا: بعض الأئمة يقرءون قصار السور ويقتصرون على ذلك في صلاة التراويح، ولا يختمون القرآن إطلاقًا ما حكم هذا العمل؟","title":"حكم القراءة في التراويح بقصار السور وعدم الختم","answer":"الجواب: الأمر في هذا واسع والحمد لله، الكل يقرأ بما يسر الله له، سواءً قرأ القرآن كله، أو قرأ من قصار المفصل أو قرأ بعض السور التي يحفظها لا حرج في ذلك، لكن الأفضل أن يقرأ القرآن كله إذا تيسر ولو من المصحف، يجعل حوله كرسي ويقرأ المصحف وإذا أراد الركوع والسجود جعله على الكرسي وإذا قام قرأ، وكان ذكوان مولى عائشة رضي الله عنها يصلي بها في رمضان من المصحف.\nوالصواب: أنه لا حرج في ذلك، هذا هو الصواب، أنه لا حرج في أن يقرأ من المصحف ولو ترك ذلك وقرأ بهم من جزء عم أو غيره فلا حرج في ذلك، الأمر في هذا واسع، ليس من اللازم أن يختم القرآن لو صلى بهم ببعض القرآن في جميع رمضان فلا بأس في ذلك، سواءً كان من قصار المفصل أو من طواله، لكن الأفضل إذا تيسر له أن يختم بهم فهو أفضل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8604/حكم-القراءة-في-التراويح-بقصار-السور-وعدم-الختم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34107.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":10474,"question":"رسالة من أحد الإخوة المستمعين ضمنها جمع من الأسئلة هو المستمع (أ. ع. ع. محمود ) في أحدها يقول: نرجو أن تحدثونا عن صلاة الرغيبة الفجر، هل نقرأ الفاتحة وسورة أخرى معها؟","title":"ما السنة في قراءة ركعتي الفجر؟","answer":"الجواب: السنة هي تسمى الراتبة راتبة الفجر، ومن سماها الرغيبة فهو اسم لا أعرف له أصلًا، المقصود سنة الفجر، وهي ركعتان تفعل في البيت أفضل وإن فعلها في المسجد فلا بأس، يقرأ فيهما الفاتحة وقل يا أيها الكافرون في الأولى، وفي الثانية: قل هو الله أحد مع الفاتحة، أو يقرأ فيهما آية البقرة في الأولى مع الفاتحة: قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى إِبْرَاهِيمَ وَإِسْمَاعِيلَ [البقرة:136] الآية، وفي الركعة الثانية بعد الفاتحة آية آل عمران: قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّهَ [آل عمران:64] كل هذا فعله النبي ﷺ هذا وهذا، وهي سنة مؤكدة لكن فيها يشرع فيها التخفيف، وفي البيت أفضل، وإن صلاها في المسجد فلا بأس، وهي مشروعة للرجل والمرأة جميعاً، والمسافر والمقيم، للجميع. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8643/ما-السنة-في-قراءة-ركعتي-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32009.mp3","categories":["صلاة التطوع","القراءة في الصلاة"]},{"id":10660,"question":"إذا فات المصلي الركعتان الأوليان من الصلاة الجهرية، وقام بعد تسليم الإمام لقضائها، فهل يجهر فيهما بالقراءة أم لا؟ وهل صلاة من لم يجهر فيهما بالقراءة صحيحة؟","title":"حكم الجهر بالقراءة للمسبوق بعد سلام الإمام","answer":"الجواب: الصواب أن ما يدركه مع الإمام هو أول صلاته، وما يقضيه هو آخر صلاته، فإذا أدرك مع الإمام ركعتين فهما أول صلاته، يصليهما مع الإمام ساكتاً؛ لأن الإمام ساكت غير جاهر، وإذا قام يقضي كذلك يقضيهما على أنهما الركعتان الأخيرتان فلا يجهر فيهما، هذا هو الصواب؛ لأنهما آخر صلاته في مثل العشاء، وهكذا المغرب إذا فاته واحدة فإنه يقضيها، وتكون بالنسبة إليه هي الأخيرة لا يجهر فيها، هذا هو السنة، حتى لا تتناقض الصلاة. نعم.","link":"https://binbaz.org.sa/fatwas/8839/حكم-الجهر-بالقراءة-للمسبوق-بعد-سلام-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32905.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":10893,"question":"السائل (ع. ح. م) المدينة المنورة يقول: سماحة الشيخ! متى يقرأ المأموم الفاتحة في الصلاة الجهرية خلف الإمام؟ أفتونا مأجورين.","title":"قراءة المأموم للفاتحة في الصلاة الجهرية","answer":"الجواب:  يقرؤها إذا سكت الإمام، بعد أن يقرأ الفاتحة الإمام إذا سكت يقرأها وقت سكوت الإمام، فإن كان الإمام لا يسكت يقرأها في أي وقت، ولا حرج، يقرؤها المأموم، وإن كان إمامه يقرأ، يقرؤها، ثم ينصت، سواء قبل الفاتحة، أو بعد الفاتحة، لكن إن كان الإمام له عادة يسكت يقرأها المأموم في حال السكوت، جمعًا بين المصلحتين، بين قراءتها وبين الاستماع للإمام وقت القراءة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9070/قراءة-الماموم-للفاتحة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28607.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":10935,"question":"رسالة بعث بها أحد الإخوة المستمعين يقول: أرجو أن تتفضلوا بإجابتي على هذه الأسئلة، وهذا المستمع هو رحمة الله عبدالقادر مدرس تحفيظ القرآن الكريم بمحايل عسير أبها، يقول: هل أقرأ سورة الفاتحة إذا كنت مأمومًا أم لا؛ لأن بعض الشيوخ يقولون: يجب الاستماع والإنصات لقراءة القرآن الكريم والفاتحة أولى؛ لأن الفاتحة أم القرآن، والله  يقول: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا لَعَلَّكُمْ تُرْحَمُونَ [الأعراف:204]، فوجب الاستماع والإنصات، سواءً في الصلاة، أو في غير الصلاة؛ لأن الذي يقول: آمين، كأنه يدعو مثل قوله تعالى: قَالَ قَدْ أُجِيبَتْ دَعْوَتُكُمَا [يونس:89]، وهارون  كان يقول: (آمين) فقط، وبعض الشيوخ يقولون: يجب قراءة الفاتحة للإمام وللمأموم؛ لأن الرسول ﷺ يقول: لا صلاة لمن لم يقرأ بفاتحة الكتاب، ما هو التطبيق بين القرآن والحديث؟ أفيدونا بأدلة كاملة -جزاكم الله خيرًا؛ لأن الأولين يقولون: حديث: لا صلاة لمن لم يقرأ بفاتحة الكتاب، للإمام والمنفرد فقط، لا للمأموم؟","title":"حكم قراءة المأموم للفاتحة في السرية والجهرية","answer":"الجواب:  هذه المسألة فيها خلاف بين أهل العلم -رحمهم الله- فمنهم من قال: إن المأموم ليس عليه قراءة الفاتحة، كما أخبرك هؤلاء الذين أخبروك وقالوا: إن عليه أن ينصت في حال الجهرية، وأنه يتحمل عنه الإمام القراءة حتى في حال السرية. وبعض آخر من أهل العلم قالوا: إنه يقرأ في حال السر، ولا يقرأ في حال الجهر، بل يستمع وينصت؛ للآية الكريمة التي تلوت وهي قوله تعالى: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204]، ولحديث: إذا قرأ الإمام فأنصتوا. والقول الثالث: أنه يلزمه أن يقرأ الفاتحة في السرية والجهرية جميعًا؛ للحديث الذي ذكرت وهو قوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب؛ ولقوله ﷺ في الحديث الآخر: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها خرجه الإمام أحمد وأبو داود والترمذي وجماعة بإسناد جيد، وله شواهد.   وهذا القول أصح الأقوال الثلاثة، وأن المأموم يقرأ إما الفاتحة في السرية والجهرية مع إمامه، ثم ينصت ويكون هذا الحديث وما جاء في معناه مخصصًا للآية الكريمة: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204] هي عامة والحديث يخصها، والقاعدة الشرعية: أن الخاص يقضي على العام ويخصه. وبهذا تعلم أنه لا معارضة بين الحديث والآية، فالآية عامة والحديث في قراءة الفاتحة للمأموم خاص، والخاص يحكم به على العام، ويقضى به على العام، فنصيحتي لك ولكل مسلم أن يقرأ خلف الإمام الفاتحة مطلقًا في الجهرية والسرية، ثم ينصت بعد قراءة الفاتحة، ينصت لإمامه، وإذا كان للإمام سكوت قرأ في حال السكوت، وإن كان ما له سكوت قرأ ولو كان إمامه يقرأ، فإذا فرغ من الفاتحة أنصت لإمامه، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9104/حكم-قراءة-الماموم-للفاتحة-في-السرية-والجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36201.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11172,"question":"إذا نسي الإنسان ولم يقرأ سورة بعد الفاتحة حين يصلي، فهل يسجد للسهو أم أن صلاته بطلت؟","title":"حكم من نسي القراءة بعد الفاتحة","answer":"الجواب:  لا. لا حرج عليه، نسي السورة؛ لأنها مستحبة ما هي بواجبة، الواجب الفاتحة، فإذا نسي السورة وركع ليس عليه شيء، وإن سجد فلا بأس لكن لا يلزمه شيء. نعم.","link":"https://binbaz.org.sa/fatwas/9344/حكم-من-نسي-القراءة-بعد-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29019.mp3","categories":["سنن الصلاة","القراءة في الصلاة"]},{"id":11175,"question":"تقول السائلة: أم عبدالمجيد من جدة تقول: جدتي لا تحفظ إلا قليلًا من القرآن الكريم حيث أنها تخطئ في سورة الفاتحة، وقد قال لها البعض من الناس في قريتنا: إذا لم تحفظي في صلاتك سورة الفاتحة فإن صلاتك غير صحيحة، فهل هذا صحيح، وقد ماتت على ذلك؟ فهل صحيح أن من لم يقرأ سورة الفاتحة بصورة صحيحة لا تقبل صلاته يا سماحة الشيخ؟","title":"حكم صلاة من لا يحسن قراءة الفاتحة","answer":"الجواب:  صلاتها صحيحة ومعذورة الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ما دام أنها عالجت واجتهدت ولم تستطع صلاتها صحيحة، والنبي ﷺ قال للذي لا يستطيع: تقول: سبحان الله والحمد لله ولا إله إلا الله والله أكبر، إذا كانت لا تستطيع، عالجت نفسها ولم تستطع، تسبح تقول: سبحان الله والحمد لله ولا إله إلا الله والله أكبر ولا حول ولا قوة إلا بالله محل القراءة، ويكفي. أما الذي تعمد يستطيع لكن يتعمد ما يقرأ الفاتحة ما تصح صلاته؛ لقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب لكن إذا كانت امرأة عجزت أو رجل عجز فالله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، صلاته صحيحة والحمد لله، لكن يعلم ويأتي بالتسبيح، تسبح بدل الفاتحة، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر. نعم.","link":"https://binbaz.org.sa/fatwas/9355/حكم-صلاة-من-لا-يحسن-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29022.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11199,"question":"هل يستوي أجر القراءة في السر والجهر؟","title":"التوسط في القراءة بين الإسرار والجهر","answer":"الجواب:  السنة فيها التوسط عدم الجهر الذي يشق على الناس، وعدم السر الذي يخفى على الناس، مثل ما جاء في الحديث: أن النبي ﷺ أمر عمر وأمر الصديق بالتوسط في القراءة، فالسنة أن يقرأ قراءة تنفعه وتنفع الحاضرين، ولا تشق عليه، وإذا رأى أن السر أخشع لقلبه وأنفع له أسر بذلك، وإن رأى أن الجهر أنفع له وأخشع لقلبه جهر بذلك، بشرط أن لا يؤذي أحدًا من الناس، أما إذا كان بين المصلين أو بين القراء لا يجهر عليهم، يشق عليهم، يشوش عليهم، قد ثبت عنه ﷺ أنه خرج ذات يوم إلى المسجد وفيه إناس يصلون، يصلي الرجل باثنين والآخر يصلي بثلاثة، فقال ﷺ: كلكم يناجي الله، فلا يجهر بعضكم على بعض وفي لفظ: فلا يؤذ بعضكم بعضًا. المقصود أن القارئ يتحرى عدم إيذاء إخوانه، من مصلين أو قراء. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9378/التوسط-في-القراءة-بين-الاسرار-والجهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37222.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11301,"question":"أحد الإخوة المستمعين يقول : عيد عواد من ضواحي ظبا يسأل ويقول: إذا نسيت قراءة سورة بعد الفاتحة في إحدى ركعات الفروض، فهل يلزمني سجود السهو أم تكفي الفاتحة؟ وجزاكم الله خيرًا.","title":"حكم نسيان قراءة سورة بعد الفاتحة في الصلاة","answer":"الجواب:  لا، لا يلزمك، ليس عليك شيء الفاتحة كافية، لكن السنة أن يقرأ مع الفاتحة زيادة في الأولى والثانية الإمام والمنفرد، أما المأموم ... تكفيه الفاتحة إلا في السرية كالظهر في الأولى والثانية والعصر في الأولى والثانية يقرأ بعدها ما تيسر كالإمام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9477/حكم-نسيان-قراءة-سورة-بعد-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37609.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11310,"question":"بعد هذا رسالة وصلت إلى البرنامج من مكة المكرمة وباعثها المستمع حسن أبو علي، الأخ حسن له عدد من القضايا يسألها ويقول: هل إذا شرع الإمام في قراءة السورة التي بعد الفاتحة، هل يجوز لي أن أقرأ الفاتحة وهو يقرأ ما يتيسر من القرآن؟","title":"هل يجوز أن أقرأ الفاتحة والإمام يقرأ ما يتيسر من القرآن؟","answer":"الجواب: نعم لك أن تقرأ الفاتحة، لكن إذا تيسر أن تقرأها في حال السكوت فهو أولى، فإذا كان لا يسكت أو لم يتيسر لك تقرؤها ثم تنصت؛ لقول النبي ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب فإنه لا صلاة لمن لم يقرأ بها فإذا تمكنت من قراءتها في حال السكوت فافعل وإلا فاقرأها ثم أنصت. لكن من نسيها من المأمومين، أو جهل حكمها، أو جاء والإمام راكع تجزئه الركعة والحمد لله؛ لأنها في حق المأموم أسهل، بخلاف الإمام والمنفرد فإنها ركن في حقهما. أما في حق المأموم فالجمهور على أنها سنة في حق المأموم، رخصة أي أنها واجبة في حق المأموم، لكن إذا نسي أو جهل سقطت عنه أو جاء والإمام راكع ما أمكنه قراءتها أجزأته الركعة لحديث أبي بكرة الذي جاء والنبي ﷺ راكع فركع دون الصف ثم دخل في الصف فقال له النبي ﷺ: زادك الله حرصًا ولا تعد. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9492/هل-يجوز-ان-اقرا-الفاتحة-والامام-يقرا-ما-يتيسر-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37703.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11325,"question":"بعد هذا رسالة وصلت إلى البرنامج من مكة المكرمة وباعثها المستمع حسن أبو علي، الأخ حسن له عدد من القضايا يسألها ويقول: هل إذا شرع الإمام في قراءة السورة التي بعد الفاتحة، هل يجوز لي أن أقرأ الفاتحة وهو يقرأ ما يتيسر من القرآن؟","title":"هل يجوز أن أقرأ الفاتحة والإمام يقرأ ما يتيسر من القرآن؟","answer":"الجواب: نعم لك أن تقرأ الفاتحة، لكن إذا تيسر أن تقرأها في حال السكوت فهو أولى، فإذا كان لا يسكت أو لم يتيسر لك تقرؤها ثم تنصت؛ لقول النبي ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب فإنه لا صلاة لمن لم يقرأ بها فإذا تمكنت من قراءتها في حال السكوت فافعل وإلا فاقرأها ثم أنصت. لكن من نسيها من المأمومين، أو جهل حكمها، أو جاء والإمام راكع تجزئه الركعة والحمد لله؛ لأنها في حق المأموم أسهل، بخلاف الإمام والمنفرد فإنها ركن في حقهما. أما في حق المأموم فالجمهور على أنها سنة في حق المأموم، رخصة أي أنها واجبة في حق المأموم، لكن إذا نسي أو جهل سقطت عنه أو جاء والإمام راكع ما أمكنه قراءتها أجزأته الركعة لحديث أبي بكرة الذي جاء والنبي ﷺ راكع فركع دون الصف ثم دخل في الصف فقال له النبي ﷺ: زادك الله حرصًا ولا تعد. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9492/هل-يجوز-ان-اقرا-الفاتحة-والامام-يقرا-ما-يتيسر-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37703.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11395,"question":"يقول هذا السائل أشرف محمد: أثناء الصلاة يحدث لي سهو مما أضطر إلى قراءة الفاتحة أكثر من مرة، وكذلك التحيات، فهل هذه الصلاة جائزة؟ وما الواجب علي نحو ذلك؟","title":"حكم تكرار الفاتحة أو نحوها في الصلاة سهواً","answer":"الجواب:  الصلاة جائزة، ولكن المشروع لك ألا تكرر، وأن تتعوذ بالله من الشيطان عند الوساوس، تقرأ الفاتحة مرة، والتحيات مرة، لا تكرر، وإذا جاءتك الوساوس؛ تعوذ بالله من الشيطان، ولو كررت؛ الصلاة صحيحة، والحمد لله.  المقدم: طيب.","link":"https://binbaz.org.sa/fatwas/9572/حكم-تكرار-الفاتحة-او-نحوها-في-الصلاة-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29315.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11421,"question":"بعد هذا رسالة بعث بها المستمع مصعب المنصور يقول: هل يجوز أن أمسك المصحف أثناء الصلاة، مع توضيح ذلك، وكيف أضعه أثناء السجود؟ جزاكم الله خيرًا.","title":"ما حكم القراءة من المصحف في الصلاة للحاجة؟","answer":"الجواب:  إذا دعت الحاجة إلى ذلك يقرأ في المصحف مثل صلاة رمضان، مثل القيام، وأشباه ذلك؛ لا بأس، والأفضل يقرأ عن ظهر قلب إذا كان حافظًا، فإذا كان يحتاج المصحف؛ فلا بأس، قد ثبت أن مولى عائشة -رضي الله عنها- كان يصلي بها من المصحف في رمضان، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9601/ما-حكم-القراءة-من-المصحف-في-الصلاة-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38019.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11594,"question":"يسأل سؤالًا آخر فيقول: ما حكم من يصلي خلف الإمام، ولا يقوم بقراءة أي شيء حتى الفاتحة لا يقرؤها، ولا يقول: آمين عند الانتهاء من الفاتحة؟ جزاكم الله خيرًا.","title":"حكم قراءة الفاتحة في الصلاة للمأموم","answer":"الجواب:  الأكثرون من أهل العلم على أن صلاته صحيحة، وأن الإمام يتحمل عنه قراءة الفاتحة، ولكن ترك المشروع، المشروع له أن يأتي بالفاتحة سرية، ويقرأ معها ما تيسر في الأولى والثانية من الظهر والعصر، أما في الجهرية فيقرأ الفاتحة فقط، ويكتفي بها، هذا هو المشروع، وإذا كان للإمام سكتة قرأها في السكتة. وذهب بعض أهل العلم: إلى وجوب قراءة الفاتحة على المأموم، وأن الواجب عليه يقرؤها إذا قدر، وهذا هو الصواب، أن عليه أن يقرأها إذا تمكن من ذلك؛ لعموم قوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب وقوله ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب؛ فإنه لا صلاة لمن لم يقرأ بها وهو حديث صحيح، رواه أحمد، والترمذي، وجماعة بسند صحيح. لكن لو فاته القيام مع الإمام، ولم يدرك إلا الركوع؛ أجزأه على الصحيح، لما ثبت في الصحيح صحيح البخاري -رحمه الله- أن أبا بكرة الثقفي  جاء والنبي ﷺ راكع، فركع دون الصف، ثم دخل في الصف، فلما سلم النبي ﷺ قال له: زادك الله حرصًا ولا تعد، ولم يأمره بقضاء الركعة، فدل على إجزائها؛ لأنه معذور بسبب غيبته وقت القراءة، وقت وقوف الإمام. وهكذا من جهل الحكم الشرعي، أو نسي؛ فالصواب: أنه تسقط عنه بالجهل والنسيان؛ لأنها واجبة في حقه، لا ركن في حق المأموم، بدليل أنه ﷺ لم يأمر أبا بكرة لما فاته القيام أن يقضي الركعة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9776/حكم-قراءة-الفاتحة-في-الصلاة-للماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38702.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11602,"question":"بعد هذا رسالة بعث بها أحد الإخوة المستمعين يسأل جمعًا من الأسئلة في أحدها، يقول: في صلاة الظهر والعصر أصلي الركعتين الأولى والثانية، وأقرأ الفاتحة ومعها سورة، أما في الركعتين الأخيرتين فإنني لا اقرأ إلا الفاتحة، فهل صلاتي صحيحة؟","title":"ما السنة في القراءة في صلاة الظهر والعصر؟","answer":"الجواب:  نعم، هذه السنة، السنة أن يقرأ في الأولى والثانية الفاتحةن وما تيسر معها، أما الثالثة والرابعة يقرأ فيها الفاتحة كما جاء هذا في حديث أبي قتادة في الصحيحين: أن النبي ﷺ كان يقرأ في الثالثة والرابعة الفاتحة فقط لكن لو زاد قرأ زيادة على الفاتحة؛ صلاته صحيحة، لا يضر، ولكن في الظهر لو زاد بعض الأحيان فقرأ بعض الآيات، أو بعض السور القصيرة في الثالثة والرابعة في الظهر؛ فلا بأس؛ لأنه ثبت من حديث أبي سعيد الخدري عند مسلم ما يدل على ذلك، وأن النبي كان يفعل هذا بعض الأحيان -عليه الصلاة والسلام- فإذا زاد على الفاتحة بعض الشيء بعض الأحيان ما هو دائم في بعض الأحيان في الثالثة والرابعة من الظهر؛ فلا حرج في ذلك، ولكن الغالب من النبي ﷺ أنه كان يقرأ الفاتحة فقط، يكتفي بها في الثالثة والرابعة ﷺ نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9789/ما-السنة-في-القراءة-في-صلاة-الظهر-والعصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38715.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11620,"question":"بعض الناس يقولون: الاستعاذة قبل قراءة الفاتحة في كل ركعة، ولا يكتفي بها عند البداية في الصلاة؟","title":"حكم الاستعاذة في كل ركعة في الصلاة","answer":"الجواب:  المشهور عند العلماء الاكتفاء بها في الأولى، في الركعة الأولى يستعيذ ويسمي، وفي البقية يسمي مع السورة، وإذا استعاذ في كل ركعة؛ فالحمد لله الأمر واسع، إن استعاذ وسمى قبل قراءة الفاتحة في كل ركعة؛ فالأمر واسع، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9809/حكم-الاستعاذة-في-كل-ركعة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38820.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11623,"question":"يقول: أنا شاب مستقيم والحمد لله، وحافظ لبعض أجزاء القرآن الكريم، ولكن إذا قمت إلى الصلاة أنسَ ما كنت حافظًا، كيف أتخلص من هذا؟","title":"حكم قراءة شيء بعد الفاتحة في الصلاة","answer":"الجواب:  الواجب الفاتحة، والباقي سنة، فإذا كان المؤمن يحفظ الفاتحة فالحمد لله، يقرؤها قراءة جيدة، ويقرأ ما تيسر من القرآن، من بعض الآيات، أو السور والحمد لله، والعلاج أن تجتهد في الدراسة، دراسة ما حفظت، في الأوقات المناسبة من الليل أو النهار، تسأل ربك التوفيق والإعانة، تضرع إليه -جل وعلا- وبهذا يتيسر لك الحفظ -إن شاء الله- بأمرين: الأمر الأول: العناية وإكثار الدراسة في الأوقات المناسبة. والأمر الثاني وهو الأهم أيضًا: سؤال الله، والضراعة إليه أن يعينك، وأن يمنحك التوفيق، وأن يعيذك من أسباب النسيان.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9810/حكم-قراءة-شيء-بعد-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38821.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11630,"question":"هل صلاة الليل والقراءة فيها سرية، أم جهرية؟","title":"حكم الجهر والإسرار في صلاة الليل","answer":"الجواب:  صلاة الليل جهرية؛ وإن أسر؛ فلا بأس؛ النبي ﷺ أسر وجهر كما قالت عائشة -رضي الله عنها- فإذا رأى المصلحة في السر أسر، وإذا رأى المصلحة في الجهر جهر، والجهر أفضل إذا تيسر، وإذا كان السر أخشع لقلبه؛ فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/9812/حكم-الجهر-والاسرار-في-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38823.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":11660,"question":"أخيرًا يسأل عن السبع المثاني؟","title":"ما هي السبع المثاني؟","answer":"الجواب: السبع المثاني بينها النبي ﷺ هي الفاتحة، قال ﷺ: الفاتحة هي أم القرآن وهي أفضل سور القرآن، وقال: إنها السبع المثاني، والقرآن العظيم الذي أوتيته هكذا قال -عليه الصلاة السلام- كما روى البخاري في الصحيح. فالسبع المثاني هي الفاتحة: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَنِ الرَّحِيمِ [الفاتحة:2-3]، سبع آيات أولها: (الحمد لله) وآخرها: غَيْرِ الْمَغْضُوبِ عَلَيْهِمْْ وَلا الضَّالِّينَ [الفاتحة:7]، فالتسمية ليست منها، التسمية مستقلة، قبل كل سورة إلا سورة براءة فإنه لا تسمية قبلها، والبقية كل سورة قبلها بسملة مشروعة مستحبة، ومنها الفاتحة: (بسم الله الرحمن الرحيم) هذه آية مستقلة. أما الفاتحة فأولها: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ [الفاتحة:1]، الثانية: الرَّحْمَنِ الرَّحِيمِ [الفاتحة:2]، الثالثة: مَالِكِ يَوْمِ الدِّينِ [الفاتحة:3]، الرابعة: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:4]، الخامسة: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:5]، السادسة: صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْْ[الفاتحة:6]، السابعة: غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ [الفاتحة:7]. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9843/ما-هي-السبع-المثاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29812.mp3","categories":["القرآن وعلومه","القراءة في الصلاة"]},{"id":11716,"question":"سماحة الشيخ! يلجأ بعض الأئمة إلى هذه الطريقة لكونهم لم يحفظوا القرآن الكريم، فهل يجوز أن يقرؤوا من المصحف، ويصلوا بالناس التراويح؟","title":"حكم القراءة من المصحف في صلاة التراويح","answer":"الجواب:  نعم يقرؤون من المصحف، الذي لا يحفظ؛ يقرأ من المصحف، والحمد لله، كان مولى عائشة -رضي الله عنها- يصلي بها من المصحف. المقدم: جزاكم الله خيرًا، إذًا ليس هذا الأمر مبتدعًا، ولا يؤثر في الصلاة. الشيخ: لا حرج في ذلك. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9891/حكم-القراءة-من-المصحف-في-صلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39204.mp3","categories":["الوتر وقيام الليل","القراءة في الصلاة"]},{"id":11741,"question":"أخيرًا يسأل أخونا ويقول: رجل صلى بالجماعة، لكنه نسي آية من سورة الفاتحة، ما حكم صلاته، وصلاة المأمومين خلفه؟","title":"حكم من نسي آية من سورة الفاتحة وهو إمام","answer":"الجواب:  حكمه أن يأتي بركعة، بدل الركعة التي ترك فيها آية من الفاتحة يأتي بركعة قبل أن يسلم، ويسجد للسهو، فإن طال الفصل يعيد هو، ويعيدون، أما إن ذكر بعد السلام في وقت قريب يأتي بركعة، ويسجد للسهو، ويسلم، وإن سجد للسهو بعد السلام؛ فهو أفضل يأتي بركعة، ثم يسلم، ثم يسجد للسهو بعد السلام، هذا هو الأفضل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9923/حكم-من-نسي-اية-من-سورة-الفاتحة-وهو-امام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39307.mp3","categories":["القراءة في الصلاة","سجود السهو"]},{"id":11755,"question":"أيهما أفضل تكون صلاة القيام جهرًا، أم سرًا؟","title":"هل الجهر أفضل في صلاة الليل للرجال والنساء؟","answer":"الجواب:  في الليل جهرًا، هذا الأفضل، وإن أسر؛ فلا حرج في ذلك. نعم. المقدم: إذًا صلاة القيام في الليل.. الشيخ: جهرًا، هذا الأفضل، كان النبي ﷺ يجهر وربما أسر كما قالت عائشة -رضي الله عنها- نعم. المقدم: هذا إذا كان في البيت. الشيخ: في البيت، أو في البر في السفر، أو في المسجد يتهجد، أو في التراويح، أو في قيام رمضان في العشر السنة الجهر. المقدم: ما شاء الله، جزاكم الله خيرًا، وأحسن إليكم، هل الحكم شامل للرجال والنساء سماحة الشيخ؟ الشيخ: للجميع النساء والرجال نعم، في البيت والمسجد، لكن المرأة إذا كان عندها أجانب؛ الأفضل السر؛ لأن صوتها قد يفتن بعض الناس؛ فالأفضل السر، وهكذا التلبية إذا كان حولها أجانب الأفضل السر. نعم. المقدم: بارك الله فيكم، بالنسبة للصلوات المفروضة الجهرية هل تجهر المرأة أيضًا؟  الشيخ: في بيتها؟ المقدم: في بيتها نعم. الشيخ: الأفضل تجهر، أما إذا كانت مع الإمام تنصت. المقدم: نعم نعم، أحسن الله إليكم، وجزاكم خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9937/هل-الجهر-افضل-في-صلاة-الليل-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39318.mp3","categories":["القراءة في الصلاة","الوتر وقيام الليل"]},{"id":11796,"question":"المستمع أيضًا يسأل ويقول: إمام صلى بنا صلاة سريةـ إنما هو قد جهر فيها، فما هو توجيهكم؟","title":"ما حكم جهر الإمام في الصلاة السرية؟","answer":"الجواب:  لا شيء عليه، وإن سجد للسهو؛ فهو حسن، ولكن لا يلزمه ذلك؛ لأن الجهر والإسرار سنتان، فلو جهر في السر، أو أسر في الجهر؛ فلا شيء عليه والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9980/ما-حكم-جهر-الامام-في-الصلاة-السرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42213.mp3","categories":["القراءة في الصلاة","سنن الصلاة"]},{"id":11823,"question":"هل يصح للمصلي أن يجهر في صلاته في الصلوات غير الجهرية، كالظهر والعصر، أو في الركعات الأخرى بعد التشهد الأول، أو الجهر في السنن، وصلاة الضحى مثلًا؟","title":"حكم الجهر بالقراءة في الصلاة السرية","answer":"الجواب:  السنة السر إلا في الليل السنة في صلاة النهار السر إلا صلاة الفجر، وصلاة الجمعة، وصلاة الكسوف والاستسقاء، أما النوافل العادية في النهار السنة فيها السر، وهكذا في صلاة الظهر والعصر السنة فيها السر. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10006/حكم-الجهر-بالقراءة-في-الصلاة-السرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39509.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":11876,"question":"من دولة قطر المستمع الصديق إدريس محمد، يسأل سماحتكم فيقول: سمعت بعض المصلين في بداية سورة الفاتحة، يبدؤون بـ(الحمد لله رب العالمين)، بدون (بسم الله الرحمن الرحيم)، والبعض الآخر يسمي، فمن هو الذي على صواب؟ جزاكم الله خيرًا.","title":"حكم الإسرار بالبسملة في الصلاة","answer":"الجواب:  المشروع للإمام والمأموم والمنفرد -لكل قارئ- أن يسمي، في الفاتحة وغيرها من السور، يبدأ بالتسمية، إلا براءة سورة التوبة، تبدأ بالتعوذ بالله من الشيطان الرجيم، لم يرد فيها التسمية، وأما بقية السور؛ فإنه يبدؤها: بسم الله الرحمن الرحيم، لكن في الصلاة يسر بها، ولو كانت جهرية؛ كالمغرب والعشاء والفجر، يسر بها، ويبدأ جاهرًا بـ(الحمد لله)، يبدأ بالحمد، كان النبي ﷺ يسر بها، والصحابة كانوا يسرون بها، فإذا أراد القراءة في المغرب والعشاء والفجر والجمعة؛ يسر بها، يسر بالتسمية، ويبدأ قول: (الحمد لله رب العالمين)، جاهرًا. أما في الظهر والعصر، يسر بالجميع، وهكذا في الثالثة والرابعة من العشاء، والثالثة من المغرب يسر بالقراءة، لكن في الفجر والجمعة، والأولى والثانية من المغرب والعشاء يسر بالبسملة، ويجهر بالحمد، وبقية السور والآيات، هذا هو السنة، قال أنس : كان النبي ﷺ و أبو بكر و عمر يبدؤون القراءة بالحمد لله، لا يجهرون بـ بسم الله الرحمن الرحيم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10060/حكم-الاسرار-بالبسملة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_424/42405.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12033,"question":"يسأل سؤالًا آخر فيقول: هل إذا قرأت الفاتحة مرتين في ركعة واحدة سهوًا، أو بدون سهو، هل ذلك يؤثر؟","title":"حكم قراءة الفاتحة مرتين سهوًا في ركعة واحدة","answer":"الجواب:  لا يؤثر، لكن لا يشرع لك تكرارها إلا إذا كنت حصل عندك نسيان فكررتها، وإلا فالأصل تكفي واحدة، مرة واحدة لا تكرر، إذا قرأتها مرة كفى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10218/حكم-قراءة-الفاتحة-مرتين-سهوا-في-ركعة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43302.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12066,"question":"المستمع محمد صالح من جيزان، بعث يسأل عددًا من الأسئلة، من بينها سؤال يقول: ما هو أقل ما يحفظ من القرآن الكريم للصلاة الفرض، والنافلة؟ جزاكم الله خيرًا.","title":"أقل واجب يقرأ في صلاة الفرض والنفل","answer":"الجواب:  أقل ما يحفظ الفاتحة يجب حفظها الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ هذه هي الواجبة ركن في الصلاة، يجب على كل إنسان حفظها، الرجل والمرأة، ثم يشرع له حفظ ما تيسر من السور؛ حتى يقرأ مع الفاتحة ما تيسر، مثل سور قصيرة يجتهد في حفظ ما تيسر، يشرع له ذلك، لكن لا يجب عليه إلا الفاتحة؛ لأنها الركن للجميع للإمام والمنفرد والمأموم، فرضًا على الجميع، وإن كان في حق المأموم واجبًا يسقط بالسهو والنسيان، ويسقط بالجهل، ويسقط إذا فاته القيام، وأدرك الإمام في الركوع؛ سقطت عنه، لكن يجب عليه تعلمها وحفظها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10251/اقل-واجب-يقرا-في-صلاة-الفرض-والنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43415.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12104,"question":"في حديث للرسول ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب أو كما قال ﷺ فهل تبطل صلاة المأموم إذا لم يقرأ الفاتحة، وخاصة في صلاة الفجر؟ جزاكم الله خيرًا.","title":"حكم صلاة المأموم إذا لم يقرأ الفاتحة","answer":"الجواب:  الواجب على الجميع قراءة الفاتحة، لقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب لكن المأموم إذا فاته القيام، جاء والإمام راكع؛ أجزأته الركعة، والحمد لله، أو نسي القراءة، أو جهل الحكم؛ فصلاته صحيحة، للعذر الشرعي؛ لأن الرسول ﷺ عذر أبا بكرة لما جاء والإمام راكع، فركع دون الصف، ثم دخل في الصف، ولم يأمره بقضاء الركعة، بل قال له: زادك الله حرصًا، ولا تعد، يعني: لا تعد إلى الركوع دون الصف، بل اصبر حتى تدخل الصف، ولم يأمره بقضاء الركعة، فدل على أن من جاء والإمام راكع، أو عند الركوع معذور إذا لم يقرأ؛ لأنه لم يبق لها وقت، وهكذا لو جهل الحكم الشرعي، أو نسي قراءتها؛ فإن صلاته صحيحة. أما الإمام فلابد من قراءتها، ولا تسقط عنه، وهكذا المنفرد لابد من قراءتها، وإذا نسيها في أي الركعات؛ أتى بركعة بدلًا من الركعة التي نسي فيها الفاتحة، وسجد للسهو، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10289/حكم-صلاة-الماموم-اذا-لم-يقرا-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43707.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12206,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين هو أحمد علي ناجي محمد الصباحي من الجمهورية العربية اليمنية، أخونا أحمد عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة بقي له ما يقرب من خمسة أسئلة، في أحدها يقول: ما هو الحكم في الجهر بالبسملة في الصلاة، وبم نرد على من يقول: إن ذلك هو مذهب الإمام الشافعي  وهل آية في سورة الفاتحة؟ وإذا لم تكن آية فلماذا هي مرقمة بالرقم واحد في سورة الفاتحة في المصحف؟","title":"ما حكم الجهر بالبسملة في الصلاة؟","answer":"الجواب:  الصواب أن البسملة ليست آية من الفاتحة، ولا من غيرها من السور، ولكنها آية مستقلة أنزلها الله فصلًا بين السور، علامة أن السورة التي قبلها انتهت، وأن التي بعدها سورة جديدة، هذا هو الصواب عند أهل العلم، وترقيمها في بعض المصاحف أنها الأولى غلط، ليس بصواب، الصواب أنها ليست من الفاتحة، وإنما أول الفاتحة الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ هذه الآية الأولى الرَّحْمَنِ الرَّحِيمِِ الثانية مَالِكِ يَوْمِ الدِّينِ الثالثة إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ الرابعة اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ هي الخامسة صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ  هذه هي السادسة غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ هي السابعة، أما التسمية فهي آية مستقلة فصل بين السور، ليست من الفاتحة، ولا من غيرها من السور في أصح قولي العلماء. إلا أنها بعض آية من سورة النمل من قوله تعالى: إِنَّهُ مِنْ سُلَيْمَانَ وَإِنَّهُ بِسْمِ اللَّهِِ الرَّحْمَنِ الرَّحِيمِ [النمل:30]، فهي بعض آية من سورة النمل، ولكنها آية مستقلة، أنزلها الله فصلًا بين السور، وليست آية من الفاتحة، وليست آية من غيرها، ولكنها بعض آية من سورة النمل، هذا هو الصواب الذي عند أهل العلم، نعم. المقدم: جزاكم الله خيرًا. الشيخ: أما الجهر بالقراءة، أما الجهر بها فالأولى عدم الجهر؛ لأن الثابت عن النبي ﷺ أنه كان لا يجهر بها، ثبت في الصحيحين من حديث أنس  قال: كان النبي  وأبو بكر، وعمر يفتتحون القراءة بالحمد لله رب العالمين وفي رواية أهل السنن: لا يجهرون ببسم الله الرحمن الرحيم. فالمقصود: أنهم يبدؤون بالحمدلة الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ [الفاتحة:2] فدل ذلك على أنهم كانوا يسرون، يعني النبي ﷺ والصديق وعمر كانوا يسرون بالتسمية، وقد جاء من طريق أبي هريرة ما يدل على أنه قد يجهر بها؛ لأنه جهر  بالتسمية، فلما صلى قال: إني أشبهكم صلاة برسول الله ﷺ فاحتج بهذا بعض الناس على أنه يجهر بها، ولكن ليس حديثًا صريحًا في ذلك، ولو ثبت التنصيص على ذلك؛ فيحمل على أنه كان في بعض الأحيان، والأكثر منه ﷺ أنه كان لا يجهر؛ جمعًا بين الروايات. فالأفضل والأولى عدم الجهر إلا إذا فعله الإنسان بعض الأحيان، جهر بها ليعلم الناس أنه، فسمي، وليعلم الناس أنها مشروعة، ويسمي الإنسان سرًا بينه وبين ربه، هذا حسن. نعم. المقدم: جزاكم الله خيرًا، أخونا يقول: بم نرد على من يقول: إن ذلك هو مذهب الإمام الشافعي؟  الشيخ: هذا يحتاج إلى مراجعة نصوص الشافعي -رحمه الله- فلعل الشافعي -رحمه الله- إذا ثبت عنه أنه قال ذلك أخذ برواية أبي هريرة حين سمى وجهر، ولما فرغ من الصلاة قال: \"إني لأشبهكم صلاة برسول الله ﷺ\" وهذا ظاهره أن النبي ﷺ جهر؛ لأن أبا هريرة جهر، وقال: \"إني أشبهكم صلاة برسول الله\" فالجهر بها جائز، ولكن الأفضل عدم الجهر. المقدم: بارك الله فيكم! إذًا: لا تستوجب أن يكون هناك خلاف بين المسلمين؟ الشيخ: ما ينبغي في هذه النزاع، ينبغي أن يكون الأمر فيها خفيفًا، والأفضل تحري سنة الرسول ﷺ بعدم الجهر، وإذا جهر بعض الأحيان من أجل حديث أبي هريرة، أو من أجل التعليم، أو ليعلم الناس أنها تقرأ؛ فلا بأس به، وقد جهر بها بعض الصحابة -رضي الله عنهم وأرضاهم- نعم. المقدم: طيب طيب، جزاكم الله خيرًا!","link":"https://binbaz.org.sa/fatwas/10392/ما-حكم-الجهر-بالبسملة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_445/44501.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12208,"question":"يقول: ألاحظ أن الأئمة يقرؤون سورة الإخلاص في الركعة الثانية بشكل دائم، فهل ذلك مشروع؟","title":"حكم المداومة على سورة الإخلاص في الركعة الثانية","answer":"الجواب:  الأمر في هذا واسع، والسنة تحري صلاة النبي ﷺ وأن يقرأ الإمام كما كان النبي يقرأ -عليه الصلاة والسلام- يطول في الفجر وفي الظهر، ويخفف العصر وفي المغرب تارة وتارة، تارة يطول، وتارة يخفف في القراءة، والعشاء يتوسط فيها كالظهر والعصر إلا أن الظهر أطول، وهي أقرب إلى الفجر، هكذا جاءت السنة عن النبي -عليه الصلاة والسلام- فالمؤمن يتحرى قراءته ﷺ فيقرأ في الفجر بمثل: ق والذاريات والطور وأشباهها من طوال المفصل وفي الظهر أقل من ذلك، وفي العصر أقل من الظهر، وفي المغرب تارة وتارة، قرأ فيها النبي ﷺ بالطور، قرأ فيها بالمرسلات، والغالب أنه يقرأ فيها بقصار المفصل -عليه الصلاة والسلام- مثل: وَالشَّمْسِ وَضُحَاهَا [الشمس:1] وَالضُّحَى [الضحى:1]، وَاللَّيْلِ إِذَا يَغْشَى [الليل:1] وإِذَا زُلْزِلَتِ [الزلزلة:1]، والقارعة، وإذا طول بعض الأحيان كما فعل النبي ﷺ كان هذا من السنة، والعشاء بأوساط مفصل مثل هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِِ [الغاشية:1]، وَالسَّمَاءِ ذَاتِ الْبُرُوجِ [البروج:1]، وَالسَّمَاءِ وَالطَّارِقِ [الطارق:1]، إِذَا السَّمَاءُ انفَطَرَتْ [الانفطار:1]، وأشباه ذلك، كما أوصى النبي ﷺ معاذًا بذلك -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/10394/حكم-المداومة-على-سورة-الاخلاص-في-الركعة-الثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_445/44503.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12209,"question":"الذين يقرؤون بعض السورة سماحة الشيخ هل في هذا حرج؟","title":"حكم الاكتفاء بقراءة بعض السورة في الصلاة","answer":"الجواب:  لا حرج في ذلك؛ لأن الله يقول: فَاقْرَءُوا مَا تَيَسَّرَ مِنْه [المزمل:20] فإذا قرأ بعض سورة، أو آخر سورة؛ فلا حرج في ذلك، وإذا قرأ بعض الأحيان في الثانية (قل هو الله أحد) أو قرأها مع غيرها؛ فلا بأس، فقد قيل للنبي ﷺ: إن بعض أئمة الأنصار يقرأ قل هو الله أحد مع قراءته الأخرى، فسأله النبي ﷺ عن ذلك، فقال: إني أقرأ بها؛ لأني أحبها؛ لأنها صفة الرحمن وأنا أحبها، فقال له النبي ﷺ: حبك إياها أدخلك الجنة وفي لفظ قال: أخبروه أن الله يحبه يعني: كما أحبها، فإذا قرأها مع غيرها؛ فلا بأس، أو قرأها وحدها بعد الفاتحة؛ فلا بأس ولكن تحري سنة النبي ﷺ والسير على منهجه في القراءة أولى وأولى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10395/حكم-الاكتفاء-بقراءة-بعض-السورة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_445/44504.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12265,"question":"يسأل سؤال آخر فيقول: هل تجزئ قراءة الفاتحة في الصلاة بالنسبة للمرأة الأمية التي لا تعرف غيرها؟","title":"حكم صلاة من لا يحسن سوى الفاتحة","answer":"الجواب:  نعم تجزئ الفاتحة، هي ركن الصلاة، وهي مجزئة للرجل والمرأة جميعًا، والأمي وغير الأمي، لكن الذي يستطيع أن يقرأ زيادة؛ فهو أفضل، في الأولى والثانية من الظهر والعصر والمغرب والعشاء، يشرع أن يقرأ زيادة على الفاتحة إذا تيسر له ذلك، وأما الثالثة والرابعة من الظهر والعصر والعشاء فيقرأ الفاتحة فقط تكفي، والثالثة من المغرب كذلك، والأمية يشرع لها التعلم حتى تستفيد، حتى تحفظ بعض السور الأخرى. أما الفاتحة فلابد من حفظها، وضبطها، وتعلمها لمن لم يعلمها، من الرجال والنساء جميعًا؛ لأنها ركن الصلاة، يقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب فالواجب على جميع المكلفين تعلمها، وحفظها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10465/حكم-صلاة-من-لا-يحسن-سوى-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_450/45002.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12413,"question":"هل يجوز للفرد إذا صلى منفردًا أن يجهر في الصلاة، وإذا كان ذلك جائزًا، فهل هو في جميع النوافل والفروض؟ جزاكم الله خيرًا.","title":"صفة القراءة إذا صلى الإنسان منفرداً","answer":"الجواب:  سنة في الليل، صلاة الليل يجهر، وهكذا في صلاة الفجر يجهر، سواء كان إمامًا، أو منفردًا، أما المأموم فينصت لإمامه، يقرأ الفاتحة بينه وبين نفسه، وينصت لإمامه، ولكن الإمام يجهر في صلاة الفجر، في التهجد بالليل، في وتره، وهكذا الإنسان في بيته يتهجد، ويرفع صوته في الليل، وهكذا في صلاة الفجر للنساء، وللرجل الذي صلى في بيته لمرض، أو عذر شرعي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10619/صفة-القراءة-اذا-صلى-الانسان-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40207.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12445,"question":"أيضًا يسأل: هل تكون قراءة القرآن في صلاة التهجد سرًا، أم جهرًا؟","title":"هل الأفضل الجهر أم الإسرار في صلاة التهجد؟","answer":"الجواب:  السنة الجهر، وإن أسر؛ فلا حرج، لكن الأفضل الجهر، جهرًا، لا يؤذي أحدًا، لا يؤذي نوامًا، ولا مصلين، جهرًا خفيفًا، لا يتأذى به أحد، وإن قرأ سرًا لأنه أرفق به؛ فلا بأس، أخبرت به عائشة -رضي الله عنها-: أن النبي ﷺ في صلاة الليل أسر وجهر، عليه الصلاة والسلام. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10652/هل-الافضل-الجهر-ام-الاسرار-في-صلاة-التهجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40317.mp3","categories":["الوتر وقيام الليل","القراءة في الصلاة"]},{"id":12603,"question":"رسالة وصلت إلى البرنامج من المستمع أبو الليث حسين بن عباس بن عبدالكريم سوادني بعث بالرسالة وضمنها جمعًا من الأسئلة، من بينها سؤال يقول فيه: هل كان النبي ﷺ يجهر بالبسملة في الصلاة عند قراءة الفاتحة، أم كان يسر بها، أم كان لا يقرؤها أبدًا في الصلاة، وما حكم من جهر بالبسملة في صلاته؟","title":"ما حكم من جهر بالبسملة في صلاته؟","answer":"الجواب:  كان النبي ﷺ لا يجهر بها، وكان يقرؤها سرًا، كما أخبر بهذا أنس  وهكذا كان الصديق وعمر وعثمان كانوا يسرون بها، وجاء عن بعض الصحابة أنه كان يجهر بها، فالأمر فيها واسع، فمن جهر؛ فلا بأس، ولكنه ترك الأفضل، والسنة الإسرار بها، وعدم الجهر بها؛ اقتداءً بالنبي، عليه الصلاة والسلام.  لكن إذا فعلها بعض الأحيان، ليعلم الناس أنها تقرأ، يعلم من حوله أنها تقرأ؛ فلا بأس بذلك جهرًا خفيفًا، حتى يعلم الناس أنها تقرأ، ولكنها ليست لازمة لو قرأ بدون بسملة؛ صحت القراءة؛ لأنها سنة البسملة، كونه يقول: بسم الله الرحمن الرحيم سنة، قبل الفاتحة، وقبل غيرها من السور، سنة غير واجبة لا في الصلاة، ولا في غيرها، إلا ما قبل براءة، فلا تشرع قبل براءة (التوبة) إذا بدأ بالتوبة يقرأ بالتعوذ، يتعوذ بالله من الشيطان الرجيم، ولا يقرأ بالتسمية في أولها؛ لأنها لم تشرع فيها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10818/ما-حكم-من-جهر-بالبسملة-في-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41406.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12616,"question":"إذا جاء المصلي والإمام يقرأ سورة بعد الفاتحة، هل يقرأ المصلي الفاتحة، أم يستمع لقراءة الإمام؟","title":"إذا جاء والإمام يقرأ سورة بعد الفاتحة، هل يقرأ الفاتحة أم ينصت؟","answer":"الجواب:  يقرأ الفاتحة، يقرأ الفاتحة، ثم ينصت؛ لأنه مأمور بالفاتحة، قد أمره النبي بقراءتها -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/10828/اذا-جاء-والامام-يقرا-سورة-بعد-الفاتحة-هل-يقرا-الفاتحة-ام-ينصت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41416.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12618,"question":"رسالة وصلت إلى البرنامج من المستمع أبو الليث حسين بن عباس بن عبدالكريم سوادني بعث بالرسالة وضمنها جمعًا من الأسئلة، من بينها سؤال يقول فيه: هل كان النبي ﷺ يجهر بالبسملة في الصلاة عند قراءة الفاتحة، أم كان يسر بها، أم كان لا يقرؤها أبدًا في الصلاة، وما حكم من جهر بالبسملة في صلاته؟","title":"ما حكم من جهر بالبسملة في صلاته؟","answer":"الجواب:  كان النبي ﷺ لا يجهر بها، وكان يقرؤها سرًا، كما أخبر بهذا أنس  وهكذا كان الصديق وعمر وعثمان كانوا يسرون بها، وجاء عن بعض الصحابة أنه كان يجهر بها، فالأمر فيها واسع، فمن جهر؛ فلا بأس، ولكنه ترك الأفضل، والسنة الإسرار بها، وعدم الجهر بها؛ اقتداءً بالنبي، عليه الصلاة والسلام.  لكن إذا فعلها بعض الأحيان، ليعلم الناس أنها تقرأ، يعلم من حوله أنها تقرأ؛ فلا بأس بذلك جهرًا خفيفًا، حتى يعلم الناس أنها تقرأ، ولكنها ليست لازمة لو قرأ بدون بسملة؛ صحت القراءة؛ لأنها سنة البسملة، كونه يقول: بسم الله الرحمن الرحيم سنة، قبل الفاتحة، وقبل غيرها من السور، سنة غير واجبة لا في الصلاة، ولا في غيرها، إلا ما قبل براءة، فلا تشرع قبل براءة (التوبة) إذا بدأ بالتوبة يقرأ بالتعوذ، يتعوذ بالله من الشيطان الرجيم، ولا يقرأ بالتسمية في أولها؛ لأنها لم تشرع فيها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10818/ما-حكم-من-جهر-بالبسملة-في-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41406.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":12924,"question":"آخر سؤال لها تقول: هل يجوز لي أن أقرأ من المصحف أثناء صلاة النافلة كقيام الليل مثلًا؟","title":"حكم القراءة من مصحف في الصلاة","answer":"الجواب:  لا حرج في ذلك، مثل قيام الليل، والتهجد في رمضان، لا حرج أن يقرأ الإنسان من المصحف، الرجل والمرأة جميعًا؛ لأن في هذا إعانة لهما على الاستكثار من القراءة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11140/حكم-القراءة-من-مصحف-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46909.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13093,"question":"من جمهورية مصر العربية، كليه التربية، محافظة كفر الشيخ، المستمع: محمد حامد محمد عبدالوهاب بعث برسالة، وضمنها سبعة أسئلة، في أحد أسئلته يقول: إذا قرأ الإمام في الصلاة الجهرية بالفاتحة، ثم أتبعها بسورة، ولم يترك بينهما وقتًا، فهل أقرأ أنا الفاتحة، أم أسكت؟ وإذا فصل بين الفاتحة والسورة، وقرأت أنا، ولكن المدة لم تكف، وقرأ هو السورة، وأنا ما زلت في الفاتحة، فهل أكمل الفاتحة، أم أسكت؟","title":"حكم قراءة المأموم الفاتحة في الصلاة الجهرية والسرية","answer":"الجواب:  نعم نعم، الواجب قراءة الفاتحة مطلقًا، سواء سكت الإمام، أم لم يسكت الإمام، إن سكت؛ شرع للمأموم أن يقرأها في السكتة حتى يجمع بين القراءة، وبين الإنصات، ولو قرأت، ثم بدأ يقرأ وأنت لم تكمل؛ كملتها، فإن لم يسكت؛ تقرأ وإن كان يقرأ، ثم تنصت بعد ذلك؛ لقوله ﷺ: لعلكم تقرؤون خلف إمامكم قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب فإنه لا صلاة لمن لم يقرأ بها وهذا نص صريح في أمر المأموم بقراءتها مطلقًا في الجهرية والسرية، وهكذا عموم قوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب وقوله ﷺ: من صلى صلاة لم يقرأ فيها بفاتحة الكتاب؛ فهي خداج، فهي خداج غير تمام. فالواجب على المأموم في أصح قولي العلماء، في أصح أقوال أهل العلم أن يقرأ في السرية والجهرية، والعلماء لهم أقوال ثلاثة:  أحدها: أنه لا يقرأ مطلقًا لا في السرية، ولا في الجهرية، بل تسقط عنه القراءة بقراءة الإمام. والقول الثاني: يقرأ في السرية دون الجهرية؛ لعموم قوله -جل وعلا-: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204] ولقوله ﷺ: وإذا قرأ الإمام؛ فأنصتوا. والقول الثالث: أنه يقرأ في السرية والجهرية؛ لقوله -عليه الصلاة والسلام-: لا صلاة لمن لم يقرأ بفاتحة الكتاب ولقوله أيضًا -عليه الصلاة والسلام-: لعلكم تقرؤون خلف إمامكم قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب فإنه لا صلاة لمن لم يقرأ بها. فهذا حديث صحيح، يدل على أن المأموم يقرأ في السرية والجهرية الفاتحة خاصة، ثم ينصت، إذا كان في الجهرية ينصت لإمامه، أما في السرية فيقرأ زيادة، ولا حرج؛ لأنه ليس هناك قراءة ينصت لها، أما قوله -جل وعلا- في كتابه العظيم: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204]. فهذا من العام المخصوص والسنة تخص القرآن، هذه الآية مخصوصة بغير الفاتحة، وهكذا قوله ﷺ: وإذا قرأ الإمام؛ فأنصتوا هذا عام مخصوص بالفاتحة. والقاعدة الكلية أن السنة تخص الكتاب، وأن الأحاديث يخص بعضها بعضًا، هذه قاعدة معلومة عند أهل الأصول، وعند أهل المصطلح، فإذا تعارضت النصوص؛ وجب تخصيص العام بالخاص، ووجب تقييد المطلق بالمقيد، وهذا أمر معلوم عند أهل العلم، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11314/حكم-قراءة-الماموم-الفاتحة-في-الصلاة-الجهرية-والسرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47306.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13102,"question":"يقول أخونا: إذا ركع الإمام وأنا أقرأ الفاتحة، ولم أكملها بعد، فهل أركع معه، أم أكمل الفاتحة؟ ومتى تسقط الفاتحة عن المأموم في الصلاة؟","title":"حكم من ركع إمامه وهو لم يكمل قراءة الفاتحة","answer":"الجواب:  إذا كان لم يبق إلا شيء يسير، كالآية والآيتين يكمل، وإذا كنت تخشى أن يرفع؛ فاركع، ويسقط عنك ما بقي، كما لو جئت والإمام قد ركع؛ تركع وتسقط عنك الفاتحة، لو جاء المأموم والإمام راكع؛ ركع معه، وأجزأه، أجزأته الركعة كما في صحيح البخاري من حديث أبي بكرة  أنه جاء والنبي ﷺ راكع؛ فركع دون الصف، ثم دخل في الصف، فلما سلم النبي ﷺ قال له: زادك الله حرصًا، ولا تعد ولم يأمره بقضاء الركعة. وهذا قول الأئمة الأربعة جميعًا، أن من أدرك الإمام راكعًا أجزأته الركعة، وسقطت عنه الفاتحة، فهكذا إذا قرأ أولها، ثم خاف من فوات الركعة؛ يركع، ولا يضره ذلك، وهكذا لو نسيها المأموم، أو كان جاهلًا؛ سقطت عنه، وأجزأته صلاته مع الإمام. بخلاف المفرد والإمام فإنها لا تجزئه، لو سها عنها، أو جهلها؛ لابد من قراءتها؛ لأنها ركن صلاته، أما المأموم فهي في حقه واجبة مع الذكر، ومع العلم، بدليل أنه ﷺ لم يأمر أبا بكرة الثقفي بالإعادة لما جاء والإمام راكع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11319/حكم-من-ركع-امامه-وهو-لم-يكمل-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47307.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13126,"question":"هل يكتفي المأموم بقراءة الفاتحة خلف الإمام، أم يقرأ مع الفاتحة سورة قصيرة؟","title":"حكم الزيادة على الفاتحة للمؤتم","answer":"الجواب:  في الجهرية لا، تكفي الفاتحة، أما في السرية مثل الظهر والعصر؛ فلا بأس يقرأ زيادة، في الأولى والثانية، يقرأ زيادة على الفاتحة؛ لأنه ليس هناك قراءة يستمعها، وينصت لها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11350/حكم-الزيادة-على-الفاتحة-للموتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47404.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13174,"question":"هذا السائل يقول: هل إذا كررت سورة الفاتحة في الركعة الواحدة من الصلاة أكثر من مرة واحدة، علمًا بأنني أريد أن أتدبرها، هل علي إثم في ذلك؟","title":"حكم تكرار سورة الفاتحة في الصلاة","answer":"الجواب:  الأفضل عدم التكرار، قال بعض أهل العلم: يكره تكرارها، إذا أردت أن تكررها كررها في خارج الصلاة؛ لأن النبي ﷺ ما كان يكررها، ولا الصحابة؛ فلا ينبغي لك تكرارها، ولكن في خارج الصلاة إذا أردت تكرراها للتأمل، والتعقل، ولو مرات كثيرة؛ فلا بأس، هي أو غيرها لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11429/حكم-تكرار-سورة-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51110.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13384,"question":"هل صلاة الوتر.. هل القراءة فيها جهرية، أم سرية؟","title":"هل القراءة في صلاة الوتر جهرية؟","answer":"الجواب: جهرية، إلا إذا صلاها في النهار، إذا فاته في الليل، وصلى في النهار بدلًا من صلاة الليل؛ يسر؛ لأن صلاة النهار سرية، إلا صلاة الفجر فإنها جهرية، وصلاة الجمعة جهرية، وصلاة الكسوف والاستسقاء جهرية، أما صلاة الوتر إذا قضاها؛ فإنه يقضيها غير جهرية، كما يصلي صلاة الضحى غير جهرية، والرواتب مثل الظهر غير جهرية، السنة قبل العصر غير جهرية، لكن لا يصلي وترًا، إذا فاته وتره من الليل؛ يصلي شفعًا، هذا السنة، فإذا كان يصلي خمسًا بالليل، وفاته بسبب النوم، يصلي ستًا في النهار ثلاث تسليمات، وإذا كان وتره سبعًا، صلى أربع تسليمات وهكذا. نعم. المقدم: جزاكم الله خيرًا، والحكم واحد بالنسبة للرجال والنساء؟ الشيخ: الحكم واحد للرجال والنساء، تقول عائشة -رضي الله عنها-: \"كان النبي ﷺ إذا نام عن ورده من الليل، أو شغله عنه مرض؛ صلى من النهار ثنتي عشرة ركعة، وكان وتره في الغالب إحدى عشر -عليه الصلاة والسلام-\" إحدى عشرة، نعم. المقدم: من حيث الجهرية والسرية بالنسبة....؟ الشيخ: نعم، نعم، للرجال والنساء. نعم. المقدم: للرجال والنساء؟ الشيخ: نعم. المقدم: أيضًا المرأة لها أن تجهر؟ الشيخ: تجهر في المغرب والعشاء والفجر. المقدم: تجهر. الشيخ: تجهر في الأولى والثانية من المغرب، والأولى والثانية من العشاء كالرجل.. وتجهر في الفجر كذلك، نعم. المقدم: هل لذلك من شرط معين؟ الشيخ: ما فيه شرط إلا إذا كان هناك رجال أجانب تخفض صوتها. المقدم: تخفض صوتها. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11673/هل-القراءة-في-صلاة-الوتر-جهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47705.mp3","categories":["الوتر وقيام الليل","القراءة في الصلاة"]},{"id":13413,"question":"السائل يقول في هذا  لقد حصل جدال في الصلاة الرباعية والثلاثية عن الركعتين الأخيرتين من الرباعية، والركعة الأخيرة من الثلاثية، هل يجوز أن نقرأ ما تيسر من القرآن فيهن، أم لا؟","title":"حكم قراءة سورة بعد الفاتحة في الركعات الأخيرة","answer":"الجواب: السنة قراءة الفاتحة في الثالثة والرابعة في الظهر والعصر والعشاء والمغرب هذا هو الأفضل؛ لأن النبي ﷺ كان يقرأ في الأخيرتين من الظهر والعصر بفاتحة الكتاب فقط، وهكذا الأخيرة من المغرب، والأخيرتين من العشاء، وإن قرأ زيادة يسيرة؛ فلا حرج، لكن هذا هو الأفضل. وقد ورد في حديث أبي سعيد الخدري ما يدل على أنه ربما يقرأ في الثالثة والرابعة شيئًا يسيرًا، وجاء عن أبي بكر  أنه كان يقرأ في الركعة الثالثة من المغرب بعد الفاتحة: رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11706/حكم-قراءة-سورة-بعد-الفاتحة-في-الركعات-الاخيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51607.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13432,"question":"من أسئلة السائل أبو عبدالله يقول: بعض كبار السن يقرأ أول الفاتحة، وهو جالس، ثم يواصل قراءة الفاتحة بعد قيامه، ما حكم هذا العمل؟","title":"حكم قراءة المصلي أول الفاتحة وهو جالس","answer":"الجواب: إذا كان عاجزًا ما يستطيع القيام الكلي، وإنما يستطيع بعض القيام، هذا لا بأس به أن يقرأ أولها، يخاف أن تفوته إذا أخرها، أما إذا كان يتمكن من قراءتها وهو قائم؛ فيؤجلها حتى يقرأها وهو قائم، أما إذا كان لا يستطيع، وإن أجلها قد تفوته، قد يركع الإمام؛ فيقرأ بعضها حال الجلوس، ثم يكمل وهو قائم إذا كان عاجزًا، أما إن كان عن كسل، وتساهل؛ فلا يجوز، يجب أن يبادر بالقيام، ولا يحل له الجلوس، فإذا جلس؛ بطلت صلاته، لكن إذا كان عاجزًا، له عذر شرعي، يشق عليه القيام حالًا؛ فهذا عذر له شرعي. وإذا قرأ بعض الفاتحة لأنه لا يتمكن من قراءتها، وهو قائم يركع الإمام قبله؛ فلا بأس، عذر شرعي؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول النبي ﷺ لمن عجز عن الصلاة قائمًا، قال: صل قائمًا، فإن لم تستطع؛ فقاعدًا، فإن لم تستطع؛ فعلى جنب، فإن لم تستطع؛ فمستلقيًا. فالمقصود أنه يراعي قوته، وقدرته. نعم. المقدم: جزاكم الله خيراً سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11727/حكم-قراءة-المصلي-اول-الفاتحة-وهو-جالس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52707.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13481,"question":"يسأل ويقول: ما حكم قراءة القرآن من السور الطويلة، والتطويل في السجود، والركوع في الجمعة، أو في أي فرض آخر؟","title":"حكم تطويل القراءة والركوع والسجود في الفرائض","answer":"الجواب: السنة أن تكون معتدلة الصلاة، كما كان النبي يفعل -عليه الصلاة والسلام- يكون مطمئنًا في الركوع والسجود، وإذا طول القراءة، طول السجود والركوع، وإذا خفف خفف، تكون الصلاة معتدلة متقاربة، قال البراء بن عازب : \"رمقت صلاة النبي ﷺ -يعني حزرتها وقدرتها- فوجدت قيامه فركوعه فاعتداله بعد الركوع فسجدته فاعتداله بين السجدتين قريبًا من السواء\" وفي رواية: \"ما خلا القيام العقود\" يعني: عند قيامه للقراءة أطول بعض الشيء، وقعوده للتشهد أطول بعض الشيء. فالسنة هكذا أن يكون قيامه أطول بعض الشيء، وهكذا جلوسه للتشهد، لكن يكون ركوعه وسجوده واعتداله بعد الركوع، واعتداله بين السجدتين، كله كامل، وفيه الطمأنينة، وفيه المقاربة للقيام والقعود. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11784/حكم-تطويل-القراءة-والركوع-والسجود-في-الفراىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47810.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13632,"question":"آخر سؤال لأختنا يقول: في صلاة الفجر نسيت أن أقرأ سورة بعد الفاتحة، فسجدت سجود السهو بعد السلام، هل ما فعلته صحيح؟","title":"هل يسجد للسهو من نسي القراءة بعد الفاتحة؟","answer":"الجواب: لا حرج في ذلك، ولكن القراءة بعد الفاتحة غير واجبة، الفاتحة كافية، لكن قراءة سورة بعد الفاتحة، أو آيات أفضل، فإذا تركها الإنسان؛ فليس عليه سجود، وإن سجد؛ فلا حرج، إذا تركها .... سهوًا؛ فليس عليه شيء. وإذا سجد من أجل ذلك؛ فلا بأس، فلا حرج في ذلك؛ لأنها سنة، سجد من أجل تركها، ولكن لا يجب ذلك؛ لأن الواجب إنما هو الفاتحة، وما زاد فهو سنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11961/هل-يسجد-للسهو-من-نسي-القراءة-بعد-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48017.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13715,"question":"تسأل أختنا أيضًا سؤالًا آخر وتقول: هل قراءة بسم الله الرحمن الرحيم في الصلاة عند قراءة الفاتحة واجبة، أم سنة؟","title":"حكم البسملة عند قراءة الفاتحة","answer":"الجواب: سنة، قراءة التسمية عند قراءة الفاتحة أو غيرها من السور سنة في الصلاة وخارجها، وليست واجبة، هذا هو الصواب. نعم.. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12086/حكم-البسملة-عند-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48107.mp3","categories":["القراءة في الصلاة","القرآن وعلومه"]},{"id":13764,"question":"تسأل وتقول: هل يجوز للمرأة أن ترفع صوتها قليلًا أثناء القراءة في الصلاة وهي تصلي، وسواءً كان ذلك في الصلوات الجهرية، أم السرية؟","title":"حكم الجهر بالقراءة في الصلاة للمرأة","answer":"الجواب: يستحب لها رفع الصوت في الجهرية، مثل الفجر، ومثل الأولى والثانية من العشاء والمغرب، يستحب لها الجهر مثلما يستحب للرجال، إلا إذا كان عندها رجال أجناب؛ تسر عنهم أفضل، تسر عنهم أفضل، وإن قرأت سرًا؛ فلا حرج، الحمد لله. نعم.  المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12136/حكم-الجهر-بالقراءة-في-الصلاة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48121.mp3","categories":["القراءة في الصلاة","قضايا المرأة"]},{"id":13862,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخوين عبد الله حسن الشهراني وعبد الرحمن مرضي الدوسري من مدينة الدمام، الأخوان يسألان مجموعة من الأسئلة من بينها سؤال يقول: هل يجهر في الصلاة إذا صلاها الإنسان منفردًا مثل صلاة المغرب والعشاء والفجر أو يجعلها سرًا؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الجهر بالقراءة للمنفرد في الصلوات الجهرية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nالسنة في صلاة المغرب والعشاء والفجر الجهر، سواء كان المصلي إمامًا أو منفردًا، هكذا كان النبي يفعل عليه الصلاة والسلام، فإذا فاتت العشاء عن الصلاة مع الجماعة صلاها بالجهر المغرب والعشاء والفجر كما كان يصليها لو كان إمامًا، لكن إذا كان حوله من قد يتأذى بالجهر من نوام أو قراء خفض قليلًا حتى لا يؤذي أحدًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12226/حكم-الجهر-بالقراءة-للمنفرد-في-الصلوات-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60301.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13865,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخوين عبد الله حسن الشهراني وعبد الرحمن مرضي الدوسري من مدينة الدمام، الأخوان يسألان مجموعة من الأسئلة من بينها سؤال يقول: هل يجهر في الصلاة إذا صلاها الإنسان منفردًا مثل صلاة المغرب والعشاء والفجر أو يجعلها سرًا؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الجهر بالقراءة للمنفرد في الصلوات الجهرية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nالسنة في صلاة المغرب والعشاء والفجر الجهر، سواء كان المصلي إمامًا أو منفردًا، هكذا كان النبي يفعل عليه الصلاة والسلام، فإذا فاتت العشاء عن الصلاة مع الجماعة صلاها بالجهر المغرب والعشاء والفجر كما كان يصليها لو كان إمامًا، لكن إذا كان حوله من قد يتأذى بالجهر من نوام أو قراء خفض قليلًا حتى لا يؤذي أحدًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12226/حكم-الجهر-بالقراءة-للمنفرد-في-الصلوات-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60301.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":13945,"question":"يسأل أخونا ويقول: إن والدتي تصلي ولكنها لا تعرف الصلاة بصورة كاملة فهي تعرف الفاتحة فقط، وعندما أعلمها تنسى بسرعة فهل صلاتها صحيحة؟ جزاكم الله خيرًا.","title":"حكم صلاة من لا يحفظ سوى الفاتحة","answer":"الجواب: نعم، صلاتها صحيحة، وعليك وعلى إخوانك تعليمها والاستمرار في تعليمها في أوقات كثيرة حتى يستقر العلم في قلبها، والفاتحة مجزئة والحمد لله، إذا علمت الفاتحة أجزأت، وإذا تيسر معها بعض السور القصيرة مثل قل أعوذ برب الفلق وقل أعوذ برب الناس وقل هو الله أحد وغيرها من السور القصيرة إذا تيسر لكم تعليمها إياها فهذا خير عظيم، ومع الاستمرار والملاحظة تحفظ إن شاء الله، حتى الذي لا يعرف الفاتحة تصح صلاته إذا عجز عن تعلمها يقرأ ما تيسر ولو بعض الآيات، فإذا عجز سبح الله وحمد الله وكبره وهلله في محل القراءة ثم كبر وركع فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].  ولا يجوز ترك الصلاة أبدًا بل يصلي على حسب حاله ولكن يتعلم، يلزمه أن يتعلم ويتقي الله في ذلك، ويلزم أولاد المرأة أن يعلموها إذا كانوا يعلمون أن يعلموها ويوجهوها، وهكذا يعلمون أباهم إذا كان جاهلًا وهم يعلمون، يعلمون إخوتهم، طالب العلم يعلم الجاهل، هكذا المؤمنون يتعاونون على البر والتقوى كما قال الله : وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، وقال سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3].\nفالواجب عليكم أن تعلموها أنت وإخوانك تعلموها وتصبروا بالحلم والكلام الطيب لا بالنهر ولا بالغلظة ولكن بالكلام الطيب والأسلوب الحسن والرفق في الأوقات المناسبة من ليل أو نهار حتى تتعلم مع الاستمرار الدائم حتى تتعلم، وهكذا أخواتكم وهكذا عماتكم وخالاتكم أحسنوا إلى الجميع، هذه الدنيا دار العمل دار التعليم دار التعاون دار التكليف، نسأل الله للجميع الهداية والتوفيق.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12355/حكم-صلاة-من-لا-يحفظ-سوى-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60405.mp3","categories":["القراءة في الصلاة"]},{"id":14167,"question":"هذا سائل للبرنامج يقول: هل من الأفضل أن نقرأ الآيات والسور التي بها سجدة في نوافل النهار أو الليل؟ جزاكم الله خيرًا.","title":"حكم تخصيص قراءة السور التي فيها سجدة في النوافل","answer":"الجواب: الأفضل أن تقرأ ما تيسر من غير تخصيص الآيات التي فيها السجدة، تقرأ ما تيسر كما كان النبي يفعل عليه الصلاة والسلام، تقرأ في الظهر والعصر والمغرب والعشاء ما تيسر إن كنت إمامًا، وإن كنت مأمومًا تقرأ ما تيسر حسب حال الإمام، تقرأ الفاتحة وما تيسر معها في السرية الأولى والثانية من الظهر، والأولى والثانية من العصر، وفي الجهرية تقرأ الفاتحة فقط وتنصت لإمامك، وتقرأ في الثالثة والرابعة من العشاء، وفي الثالثة والرابعة من الظهر والعصر الفاتحة، وفي الثالثة من المغرب الفاتحة. أما في النوافل تقرأ ما تيسر لا تخصص آيات السجود.. سجود التلاوة، تقرأ ما تيسر وإذا رتبت قراءتك من أول القرآن إلى آخره فهذا هو الأفضل، كلما كملت القرآن رجعت من أوله، وتقرأ في صلواتك في الليل والنهار ما تيسر، وتقرأ ما تيسر في غير الصلاة أيضًا، كلما ختمت القرآن رددت من أوله، هذا هو الأفضل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12608/حكم-تخصيص-قراءة-السور-التي-فيها-سجدة-في-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54703.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14171,"question":"هذا السائل يقول في هذا السؤال سماحة الشيخ: هل على المأموم أن يقرأ الفاتحة في كل ركعة أثناء صلاة التراويح مع الإمام أم يكتفي بالإنصات لقراءة الإمام، مع العلم بأن الإمام يشرع في قراءة القرآن بعد الفاتحة مباشرة؟","title":"هل على المأموم أن يقرأ الفاتحة في كل ركعة؟","answer":"الجواب: هذه مسألة خلاف بين أهل العلم، من أهل العلم من قال: يكفيه قراءة الإمام ولكن الراجح أنه يقرأ.. الصواب أنه يقرأ، يقرأ الفاتحة ثم ينصت، لقول النبي ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم. قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها وهذا عام يعم الفرض والنفل، وهو حديث صحيح مع عموم حديث: لا صلاة لمن لم يقرأ بفاتحة الكتاب فالمأموم يقرأ الفاتحة ثم ينصت، سواء كانت الصلاة جهرية أو سرية، هذا هو الصواب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12612/هل-على-الماموم-ان-يقرا-الفاتحة-في-كل-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54706.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14172,"question":"هل يجوز للمصلي أن يقرأ أكثر من سورة في الركعة الواحدة خاصة في صلاة الفريضة؟","title":"جواز قراءة أكثر من سورة في الركعة الواحدة","answer":"الجواب: لا حرج في ذلك أن يقرأ سورتين أو أكثر، قد كان بعض الأئمة في الأنصار يقرأ الفاتحة وسورة ويقرأ معها قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] فأقره النبي عليه الصلاة والسلام، وسأله عن ذلك قال: لأني أحبها، فأخبره قال: إن الله يحبك كما أحببتها وفي لفظ: حبك إياها أدخلك الجنة فلا حرج.\nوجاء عن ابن مسعود «أن النبي ﷺ كان يقرأ بعدة سور كل سورتين في ركعة غير الفاتحة» وثبت عنه ﷺ في حديث حذيفة «أنه في بعض صلاة الليل قرأ البقرة والنساء وآل عمران في ركعة» عليه الصلاة والسلام.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12613/جواز-قراءة-اكثر-من-سورة-في-الركعة-الواحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54707.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14211,"question":"يقول هذا السائل: هل المأموم يقرأ القرآن عند الصلاة؟","title":"هل يقرأ المأموم القرآن في الصلاة؟","answer":"الجواب: المأموم يقرأ الفاتحة في الجهرية، أما في السرية يقرأ الفاتحة وما تيسر معها، في الظهر والعصر يقرأ الفاتحة وما تيسر معها، ويقرأ في الثالثة من المغرب الفاتحة، وفي الثالثة من الظهر والعصر والرابعة يقرأ الفاتحة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12660/هل-يقرا-الماموم-القران-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54812.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14215,"question":"يقول السائل في آخر أسئلته: عند الصلاة هل المسلم يقرأ بقلبه أو بلسانه، أو بقلبه ولسانه مع تحريك الشفتين وفي الدعاء كذلك؟","title":"كيفية قراءة القرآن في الصلاة","answer":"الجواب: المقدم: الله المستعان جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12665/كيفية-قراءة-القران-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54816.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14244,"question":"يقول السائل في آخر أسئلته: سمعت من بعض الإخوة بأنهم يقولون: بأن الفاتحة واجبة في الجهرية، وسمعت من آخرين يقولون: بأنها ليست واجبة في الجهرية؛ لقوله تعالى: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا لَعَلَّكُمْ تُرْحَمُونَ [الأعراف:204]؟","title":"هل قراءة الفاتحة للمأموم واجبة في الصلاة الجهرية؟","answer":"الجواب: نعم، القراءة واجبة في السرية والجهرية على الصحيح على المأموم، في الجهرية يقرأ ثم ينصت، وفي السرية يقرأ ويقرأ معها ما تيسر في الأولى والثانية من الظهر والعصر والمغرب والعشاء والفجر، يقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب، ويقول ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم. قال: لا تفعلوا إلا بفاتحة الكتاب فإنه لا صلاة لمن لم يقرأ بها فدل ذلك على وجوب القراءة على المأموم في الجهرية والسرية، لكن لو فاتته القراءة جهلاً أو نسياناً سقطت عنه؛ لأنها واجبة لا ...... واجبة في حق المأموم، وهكذا لو جاء والإمام راكع سقطت عنه لأن الرسول ﷺ أقر أبا بكرة لما جاء والإمام راكع ولم يأمره بقضاء الركعة، بل قال: «زادك الله حرصاً ولا تعد» لما ركع دون الصف، قال: زادك الله حرصاً ولا تعد، ولم يقل له يقضي الركعة التي لم يقرأ فيها الفاتحة، أما حديث: من كان له إمام فقراءته له قراءة فهو حديث ضعيف.\nفالصواب أن المأموم يقرأ في الجهرية والسرية الفاتحة فقط ... في الجهرية، أما في السرية فيقرأ معها ما تيسر في الأولى والثانية. نعم.\nالمقدم: شكر الله لكم سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12708/هل-قراءة-الفاتحة-للماموم-واجبة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53019.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14358,"question":"هل تكفي فاتحة الكتاب في التهجد والسنن، أم لا بد من قراءة آيات وسور أخرى معها؟","title":"هل يكفي قراءة الفاتحة في صلاة النافلة؟","answer":"الجواب: تكفي الفاتحة؛ لأنها ركن، ولكن إذا قرأ معها فهو أفضل، السنة أن يقرأ معها زيادة، النبي كان يقرأ مع الفاتحة -عليه الصلاة والسلام-، لكنه قال: لا صلاة لمن لم يقرأ بفاتحة الكتاب فالركن هو الفاتحة، وما زاد فهو مستحب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12838/هل-يكفي-قراءة-الفاتحة-في-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48704.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14415,"question":"يقول هذا السائل: ما حكم قراءة الفاتحة على المأموم؟ وإذا كانت واجبة فكيف الجمع بينها وبين الإنصات للقرآن؟ لأنني سمعت بعض الإخوة يقول: بأنه لا يجوز للإمام السكوت بعد قراءة الفاتحة، بل يواصل القراءة.","title":"حكم قراءة الفاتحة على المأموم","answer":"الجواب: حكم القراءة للمأموم أنها واجبة، يجب على المأموم أن يقرأ الفاتحة هذا الصحيح، وذهب أكثر أهل العلم إلى أنها لا تجب عليه اكتفاء بالإمام، ولكن الصواب أنها تجب عليه في السرية والجهرية؛ لقوله ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها وهو حديث صحيح رواه أحمد وغيره؛ ولعموم قوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب لكنها في حق المأموم واجبة إذا تركها جاهلًا أو ناسيًا، أو لم يأت إلا عند ركوع الإمام وركع معه سقطت عنه، كما جاء في حديث أبي بكرة الثقفي  أنه جاء إلى النبي ﷺ وهو راكع، فركع قبل أن يصل إلى الصف، ثم دخل في الصف، فذكر ذلك للنبي ﷺ بعد السلام فقال ﷺ: زادك الله حرصًا، ولا تعود ولم يأمره بقضاء الركعة. أما الإمام والمنفرد فهي ركن في حقهما لا بد منها، فلو تركها الإمام أو المنفرد القراءة -قراءة الفاتحة- بطلت صلاته، إذا تعمد ذلك، وإن نسيها في ركعة أتى بركعة بدل التي نسيها منها وسجد للسهو. أما المأموم فهي واجبة في حقه لو تركها ناسيًا أو جاهلًا صحت صلاته؛ لأنه تابع للإمام والجمع بينها وبين النصوص التي فيها الإنصات أنها خاصة، والنصوص عامة، فيخص منها قراءة الفاتحة، وأما الإمام فإن سكت بعد الفاتحة فلا بأس، وإن واصل القراءة فلا بأس؛ لأنه لم يثبت في هذا نص واضح، جاء في بعض الأحاديث أنه يسكت بعد قول: وَلا الضَّالِّينَ [الفاتحة:7] وجاء في بعضها أنه لا يسكت بعد نهاية القراءة، فإن سكت بعد الفاتحة فلا بأس، وإن واصل القراءة فلا بأس، الأمر واسع -إن شاء الله-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12897/حكم-قراءة-الفاتحة-على-الماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55312.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14481,"question":"هل يجوز لمن زفر في الصلاة أن يقول: أستغفرك اللهم وأتوب إليك؟وهل يجوز أن يستعيذ من الشيطان الرجيم أثناء الصلاة؟وهل يجوز للمصلي أن يقول: سبحانه، أو سبحان الله إذا مر به بعض الآيات وفيها تعظيم لله؟","title":"هل يسبيح المصلي إذا مر بآية تسبيح؟","answer":"الجواب: السنة للمؤمن في مثل هذه المسائل أن يفعل ما شرعه الله  من العناية بخشوع وتدبر لما يقرأ، وإذا عرض له عارض في صلاته بأن مر بآية تسبيح، أو آية رجاء، أو آية خوف فسبح أو سأل فلا بأس، لكن مشروع هذا في صلاة الليل، هذا هو المشروع، كان النبي ﷺ يفعله في صلاة الليل، ولم يحفظ عنه أنه فعله في صلاة الفريضة، ولو فعله الإنسان لا شيء عليه صلاته صحيحة، ولكن الأفضل ترك ذلك؛ لأن الرسول ﷺ ما كان يفعله إلا في تهجده بالليل، كان يستمر في قراءته -عليه الصلاة والسلام- في الفجر والمغرب والعشاء والناس يسمعونه، ما يقف يسبح أو يدعو، لم ينقل هذا فيما نعلم عن النبي ﷺ إلا في تهجده بالليل. فالأفضل في هذا ألا يقف عند آية التسبيح، ولا عند آية الوعيد، ولا عند آية الوعد، بل يستمر في الفريضة، أما في التهجد في الليل أو في النوافل فالأمر واسع الحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12976/هل-يسبيح-المصلي-اذا-مر-باية-تسبيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62505.mp3","categories":["الأدعية والأذكار","القراءة في الصلاة"]},{"id":14505,"question":"إذا صليت الظهر أو العصر وراء إمام، وأطال القراءة، وقد قرأت سورة قصيرة، فهل أشرع في قراءة سورة ثانية حتى يركع، أم أبقى منتظرًا صامتًا حتى يركع؟","title":"إذا أطال الإمام هل يقرأ المأموم أكثر من سورة؟","answer":"الجواب: ينبغي لك أن تقرأ، زيادة سورة أو آيات حتى يركع إمامك؛ لأن المأموم لا يسكت، إما أن يقرأ، وإما أن ينصت، فإذا كان الإمام في صلاة سرية، فإنك تقرأ زيادة حتى يركع إمامك، نعم. المقدم: جزاكم الله خيرًا.\nسنعود إلى بقية أسئلته في حلقة قادمة -إن شاء الله تعالى- لإتاحة الفرصة أمام رسائل أخرى.\nالشيخ: إن شاء الله.\nالمقدم: إن شاء الله.","link":"https://binbaz.org.sa/fatwas/13023/اذا-اطال-الامام-هل-يقرا-الماموم-اكثر-من-سورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62609.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14512,"question":"إذا صليت الظهر أو العصر وراء إمام، وأطال القراءة، وقد قرأت سورة قصيرة، فهل أشرع في قراءة سورة ثانية حتى يركع، أم أبقى منتظرًا صامتًا حتى يركع؟","title":"إذا أطال الإمام هل يقرأ المأموم أكثر من سورة؟","answer":"الجواب: ينبغي لك أن تقرأ، زيادة سورة أو آيات حتى يركع إمامك؛ لأن المأموم لا يسكت، إما أن يقرأ، وإما أن ينصت، فإذا كان الإمام في صلاة سرية، فإنك تقرأ زيادة حتى يركع إمامك، نعم. المقدم: جزاكم الله خيرًا.\nسنعود إلى بقية أسئلته في حلقة قادمة -إن شاء الله تعالى- لإتاحة الفرصة أمام رسائل أخرى.\nالشيخ: إن شاء الله.\nالمقدم: إن شاء الله.","link":"https://binbaz.org.sa/fatwas/13023/اذا-اطال-الامام-هل-يقرا-الماموم-اكثر-من-سورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62609.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14520,"question":"عند نهاية قراءة الفاتحة في الركعة الأولى، هل أتعوذ وأبسمل في السورة التي تلي الفاتحة؟ وهل أكرر التعوذ والبسملة عند قراءتي للفاتحة والسورة الأخرى في الركعات التالية؟","title":"هل تقرأ الاستعاذة والبسملة في كل ركعات الصلاة؟","answer":"الجواب: المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13020/هل-تقرا-الاستعاذة-والبسملة-في-كل-ركعات-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63403.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14605,"question":"المستمع عطية عبدالعزيز عبدالله، بعث يسأل عن حكم قراءة الفاتحة بالنسبة للمأموم، حيث يقول:إنه سمع حديثًا عن رسول الله ﷺ يقول: لا صلاة إلا بفاتحة الكتاب فعند انتهاء الإمام من قراءة الفاتحة في الصلاة الجهرية هل نقرأ الفاتحة؟ وهل إذا قرأنا الفاتحة وبدأ في السورة هل نكمل قراءة الفاتحة، أم كيف نتصرف؟جزاكم الله خيرًا.","title":"حكم قراءة الفاتحة للمأموم في الصلاة الجهرية","answer":"الجواب: عليك أن تقرأ الفاتحة وتجتهد؛ لأن الصحيح أنها تجب على المأموم، وإذا شرع في القراءة تكمل ولو شرع، ثم تنصت لقراءة إمامك، وفي السرية تقرأ الفاتحة، وما تيسر معها؛ لقول النبي ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب؛ فإنه لا صلاة لمن لم يقرأ بها فتجمع بين الأمرين تنصت لقراءة إمامك، وتقرأ الفاتحة ولو كان يقرأ إذا كان لم يسكت سكوتًا يكفي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13109/حكم-قراءة-الفاتحة-للماموم-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63605.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14672,"question":"حدثونا لو تكرمتم بقول واضح عن حكم قراءة الفاتحة بالنسبة للمأموم؟","title":"حكم قراءة الفاتحة بالنسبة للمأموم","answer":"الجواب: الصواب: أن المأموم تلزمه قراءة الفاتحة، ولكنها في حقه دون وجوبها على الإمام والمنفرد؛ ولهذا ذهب الجمهور إلى أنها لا تجب على المأموم، ولكن تستحب في السرية، وفي سكتات الإمام، ولكن الصحيح أنها تلزمه؛ لقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب فهو عام، وقوله ﷺ: لعلكم تقرؤون خلف الإمام؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب؛ فإنه لا صلاة لمن لم يقرأ بها فهذا صريح في أن على المأموم أن يقرأ، وأنه لا صلاة إلا بذلك. لكن لو تركها ناسيًا، أو جاهلًا بالحكم الشرعي، فإن صلاته صحيحة؛ لأن وجوبها في حقه ليس كوجوبها في حق الإمام والمنفرد، والدليل على هذا أن الذي أدرك الإمام راكعًا تجزئه الصلاة، كما في حديث أبي بكرة الثقفي عند البخاري -رحمه الله-، فإنه جاء والنبي ﷺ راكعًا فركع دون الصف، ثم دخل في الصف ولم يأمره النبي ﷺ بالإعادة، فدل على أنها أجزأته الركعة؛ لأنه لم يدرك الوقوف ولا قراءة الفاتحة فعفي عنه، فالذي نسيها أو جهل الحكم الشرعي وقلد من لا يوجبها من باب أولى أن يسقط عنه ذلك، كما سقطت الفاتحة عمن أدرك الإمام راكعًا؛ لأنه لم يدرك الوقوف. أما من أدرك الوقوف، وتمكن من قراءة الفاتحة وهو يعلم الحكم الشرعي، فإنه يلزمه أن يقرأها عملًا بالأدلة الشرعية، وخروجًا من خلاف العلماء -رحمهم الله-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13173/حكم-قراءة-الفاتحة-بالنسبة-للماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62804.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14712,"question":"هل حمل المصحف في الصلاة جائز لمن لم يحفظ من القرآن إلا القليل؟","title":"حكم القراءة من المصحف في الصلاة","answer":"الجواب: لا مانع أن يقرأ من المصحف في التهجد بالليل، أو في صلاة التراويح.  أما الفريضة يقرأ ما تيسر، ولا حاجة إلى المصحف، يقرأ ما تيسر، والحمد لله مع الفاتحة، ويكفي والحمد لله، الفاتحة هي الأصل، والباقي سنة، يقرأ ما تيسر من السور القصيرة، أو الآيات، ويكفي، الحمد لله. المقدم: الحمد لله، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13196/حكم-القراءة-من-المصحف-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56022.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14722,"question":"لو أن الإمام أخطأ أثناء الصلاة في آية، هل يسجد سجود للسهو أم لا؟","title":"هل يسجد للسهو عند السهو في آية؟","answer":"الجواب: لا ما يلزمه سجود السهو إذا أسقط آية من غير الفاتحة، ما يلزمه سجود، الحمد لله؛ لأن هذا قراءة، زيادة على الفاتحة ليس بلازم، لكن إذا أسقط من الفاتحة، لا بد يأتي بالفاتحة كاملة، ينبهه الذي وراه، إذا أسقط آية من الفاتحة ينبهه الذي وراه على ما أسقط حتى يأتي به، ولو ما أتى به تبطل الركعة يأتي بركعة بدلها، لو أسقط آية من الفاتحة بطلت الركعة، وقامت الأخرى مقامها، إذا سها عن آية ولم يُنبه، أما إذا نُبه وأتى بها في الحال فلا بأس، الحمد لله. أما الذي غير الفاتحة لو أسقط شيئًا ناسيًا فلا يضره، الحمد لله، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13208/هل-يسجد-للسهو-عند-السهو-في-اية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56026.mp3","categories":["القراءة في الصلاة","سجود السهو"]},{"id":14782,"question":"هذا الشاب مصري، ومقيم بالمملكة، يقول في هذا  أنا أحب أن أقرأ سورة الكافرون باستمرار، وبالذات في صلاة السنة أو الضحى، ولكن ليس دائمًا، ولكن في أغلب الأوقات؛ وذلك لأنني عند قراءتها أشعر بالإيمان والتبرؤ من الكفر، فهل هذا جائز أم لا؟","title":"حكم الإكثار من قراءة سورة الكافرون في النوافل","answer":"الجواب: لا حرج، الحمد لله تقرؤها متى شئت الحمد لله، أقول: تقرؤها متى شئت، والحمد لله، وهي إحدى سورتي الإخلاص، كان النبي ﷺ يقرأ بها وبـقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] في سنة الفجر، وفي سنة المغرب، وفي سنة الطواف، كان يقرأ بهما -عليه الصلاة والسلام- قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] في الأولى، وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] في الثانية بعد الفاتحة، فهي سورة عظيمة، وإذا قرأت بها كثيرًا فلا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/13271/حكم-الاكثار-من-قراءة-سورة-الكافرون-في-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56109.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14800,"question":"صليت مرة ببعض الأصدقاء صلاة جهرية، وقرأت في الركعة الأولى سورة الفلق، وقرأت في الثانية: إِذَا زُلْزِلَتِ [الزلزلة:1] وبعد الانتهاء من الصلاة قال لي أحدهم: يجب أن تكون القراءة حسب ترتيب السور في القرآن، ولا يجوز أن تسبق سورة على سورة. آمل الإفادة، جزاكم الله خيرًا.","title":"حكم قراءة السور في الصلاة حسب ترتيب المصحف","answer":"الجواب: هذا هو الأفضل أن يرتب على حسب ما في المصحف، لكن لو عكس لا حرج، ليس بحرام، فقول القائل لك: لا يجوز، هذا غلط، هو جائز، لكن تركه أفضل، فإذا قرأت الزلزلة تقرأ ما بعدها، وإذا قرأت قُلْ أَعُوذُ بِربِّ الفَلَقِ [الفلق: 1] تقرأ قُلْ أَعًوذُ بِربِّ النّاسِ، [الناس: 1] لكن لو أنك قرأت مثل ما فعلت الفلق، ثم قرأت ما قبلها قرأت إِذَا جَاءَ نَصْرُ اللهِ [النصر:1] أو الكافرون، أو قرأت الزلزلة، كل ذلك لا حرج فيه، وقد ثبت عن عمر  أنه قرأ سورة النحل، ثم قرأ بعدها سورة يوسف، وقد ثبت عن النبي ﷺ أنه قرأ البقرة، ثم النساء، ثم آل عمران، نعم.\nالمقدم: جزاكم الله خيرًا، إذًا الترتيب والحالة هذه...\nالشيخ: مستحب فقط. المقدم: مستحب فقط. الشيخ: ليس بحرام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13297/حكم-قراءة-السور-في-الصلاة-حسب-ترتيب-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63812.mp3","categories":["القراءة في الصلاة","القرآن وعلومه"]},{"id":14841,"question":"هل القراءة في الصلاة يجب أن تكون بالترتيل بالمد والترجيع وبتحسين الصوت بها؟","title":"هل يجب ترتيل القرآن في الصلاة؟","answer":"الجواب: هذا هو السنة، هذا هو الأفضل، وإلا لا يجب، إذا قرأ قراءة عربية قد أدى فيها الحروف، كفى، لكن إذا رتلها، وحسّن صوته، واعتنى بالتجويد كان ذلك أكمل.","link":"https://binbaz.org.sa/fatwas/13355/هل-يجب-ترتيل-القران-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64411.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":14980,"question":"سؤالها الآخر تقول: أنا أحفظ -ولله الحمد- خمسة أو ستة أجزاء من القرآن الكريم، ولكنني أنسى بعض الكلمات والجمل في بعض السور، فهل يجوز لي أقرأ في صلاتي ما أعرف وأترك الذي لا أعرفه؟أفتوني، جزاكم الله عني خيرًا. علمًا أنني أتجاوز هذا الذي لا أعرف، وأقرأ الذي بعده.","title":"حكم من يصلي ويتجاوز الأيات التي ينساها","answer":"الجواب: لا حرج، لا بأس -إن شاء الله-، تقرأ ما حفظت ولا بأس، بعد الفاتحة، المهم الفاتحة هي الركن، والباقي نافلة سنة، تقرأ ما تيسر من الآيات التي عندها، ولو طمرت بعض الآيات الأخرى جبهت عنها وتركتها؛ لأنها ما تحفظها لا بأس، لكن المهم الفاتحة لا بد من الفاتحة؛ لأنها ركن في الصلاة، وما زاد عليها مستحب من آية أو سورة، فالأمر فيه واسع، نعم.","link":"https://binbaz.org.sa/fatwas/13494/حكم-من-يصلي-ويتجاوز-الايات-التي-ينساها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_651/nour_65107.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15057,"question":"السؤال الثاني يقول: إذا ترك المأموم الركن الثاني من أركان الصلاة -وأقصد الفاتحة- فهل تبطل صلاته؟ وكيف نقول في قول الرسول ﷺ الذي ما معناه: أن الصلاة التي لم يقرأ فيها بفاتحة الكتاب هي خداج خداج خداج، وفي قوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب؟","title":"حكم ترك المأموم قراءة الفاتحة","answer":"الجواب: أما الإمام والمنفرد فإن صلاتهما تبطل إذا لم يقرءا فاتحة الكتاب للحديثين المذكورين.  وأما المأموم ففيه خلاف؛ فإن تعمد تركها مع العلم بما جاء في السنة، ومع اعتقاده أن معناهما لا معارض له، فإن صلاته تبطل في أصح أقوال أهل العلم.  أما إن ترك قراءتها لأنه اجتهد، ورأى أنها في المنفرد، وفي الإمام، أو جهلًا منه بالحكم الشرعي، فإن صلاته تكون صحيحة؛ لأنه لم يتعمد فعل ما حرم الله، ولا ترك ما أوجب الله، بل تركها إما اجتهادًا، وإما جهلًا بالحكم الشرعي، فهذا صلاته صحيحة. أما من يعلم الحكم الشرعي، ويعتقد أنها تجب عليه، ثم تركها عمدًا، فهذا تبطل صلاته؛ لأنه خالف اعتقاده، وخالف ما يعلم أنه حق، ولا شك أن قراءتها مهمة جدًا، واختلف العلماء في وجوبها، والأرجح: أنها تجب على المأموم؛ لعموم الأحاديث في ذلك، فلا ينبغي له تركها، بل الواجب عليه أن يقرأها، لكن لو تركها نسيانًا أو جهلًا، أو لم يدرك القيام، بل جاء والإمام راكع فإن صلاته صحيحة، والركعة تجزئه، ولا يلزمه قضاء الركعة التي أدرك الإمام في ركوعها، هذا هو الصواب الذي عليه جمهور أهل العلم. المقدم: لكن لا تختلف الصلاة الجهرية عن السرية؟\nالشيخ: لا، مطلقًا؛ سواء جهرية أو سرية، والحجة في هذا ما رواه البخاري في الصحيح من حديث أبي بكرة الثقفي أنه جاء إلى النبي ﷺ وهو راكع، فركع معه، ولم يقرأ الفاتحة، بل فاته القيام، فركع دون الصف، ثم مشى إلى الصف، فدخل في الصف والإمام راكع. المقصود: أنه جاء والإمام راكع فركع دون الصف، ثم مشى إلى الصف، فدخل فيه، فقال له النبي ﷺ: زادك الله حرصًا، ولا تعد ولم يأمره بقضاء الركعة، فدل ذلك على أن من أدرك الإمام راكعًا أجزأته الركعة، وسقطت عنه قراءة الفاتحة؛ لأنه معذور بفوات القيام، وهكذا من جهل الحكم الشرعي، أو نسي الفاتحة، وهو مع الإمام يتحملها عنه الإمام كالجاهل، نعم.","link":"https://binbaz.org.sa/fatwas/13558/حكم-ترك-الماموم-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_663/nour_66302.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15062,"question":"في آخر أسئلة هذا السائل يقول: إذا كنت مأمومًا في صلاة جهرية، فمتى أقرأ الفاتحة وما يتيسر من القرآن؟ هل أقرأ والإمام يقرأ أما ماذا أعمل؟","title":"متى يقرأ المأموم الفاتحة في الصلاة الجهرية؟","answer":"الجواب: إذا كان له سكوت تقرأ في حال السكوت، وإن كان ما له سكوت تقرأ، ولو هو يقرأ، تقرأ الفاتحة، ثم تنصت؛ لقول النبي ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب؛ فإنه لا صلاة لمن لم يقرأ بها. فهذا الحديث الصحيح يدل على أن المأموم يقرأ الفاتحة، وينصت بعدها في الجهرية، وإذا كان للإمام سكتة بعد الفاتحة؛ قرأت الفاتحة في حال السكوت، أما إن كان ماله سكتة؛ تقرأ وإن كان يقرأ، تقرأ الفاتحة، ثم تنصت، وإذا كان في السرية: في الظهر، والعصر، تقرأ الزيادة مع الفاتحة في الأولى والثانية، تقرأ ما تيسر، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13549/متى-يقرا-الماموم-الفاتحة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56311.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15084,"question":"أيضًا عن الجهر بالبسملة، وردتنا هذه الرسالة من عايض محمد اليماني، يقول عايض في رسالته هذه: لقد تقدمت في مسجد في مزرعة، وكنا من العمال، ومعنا أيضًا -يقول: سعوديون، ويمنيون، وباكستاني، وبعد أن قرأت البسملة جهرًا، تركنا السعودي، وخرج من الصف، ولم يصل معنا جماعةً، نرجو- إذا كان في البسملة، أو في الجهر بالبسملة شيء يجانب الصواب -إفتاؤنا في ذلك، وفقكم الله.","title":"هل يجوز إنصراف المأموم إن جهر الإمام بالبسملة؟","answer":"الجواب: البسملة يجوز الجهر بها، والأفضل السر بها، وقد ثبت عن النبي ﷺ أنه كان يسر بها، وهكذا الصديق، وعمر، وعثمان ، فالسنة الإسرار بها، وأن تقرأها سرًا بينك وبين نفسك، قبل الفاتحة، وقبل كل سورة، ولا تجهر بها، لكن لو جهر بها الإمام؛ فلا حرج، ولا ينبغي الانصراف من أجل ذلك، والذي انصرف من الصلاة من أجل ذلك غلط، ليس عنده بصيرة، فالجهر بالبسملة لا يضر بـالصلاة، ولا حرج فيه، ولكنه خلاف الأفضل، فالأفضل السر بها، نعم. المقدم: لكن هل ينبغي للمأموم أن يتصرف مثل هذا التصرف، وهو لم يتثبت في..؟ الشيخ: لا، لا ينبغي هذا، غلط، كونه يخرج من الصلاة من أجل هذا، غلط منه جهل، نعم.","link":"https://binbaz.org.sa/fatwas/13593/هل-يجوز-انصراف-الماموم-ان-جهر-الامام-بالبسملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_655/nour_65508.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15143,"question":"هذا السائل أخوكم في الله: محمد محمود، مقيم بجدة، يقول: سماحة الشيخ، عندما كنت في صلاة الجمعة قال الإمام: يجب على المأموم إذا قرأ الإمام أن ينصت لقراءته، وحتى وإن لم يقرأ الفاتحة، وبالفعل صليت عدة صلوات ليست بالكثيرة؛ وذلك بدون قراءة الفاتحة، وبالذات عندما لا يعطي الإمام فرصة ويقرأ مباشرة بعد الفاتحة فأنصت له، فسألت في الأمر فعرفت بأنه يجب علي أن أقرأ الفاتحة، فهل علي شيء في الصلوات الفائتة التي لم أقرأ فيها الفاتحة؟","title":"هل علي شيء في الصلوات الفائتة التي لم أقرأ فيها الفاتحة؟","answer":"الجواب: اختلف العلماء في هذا، فجمهور أهل العلم يرون أن الفاتحة لا تجب على مأموم، وأن الإمام يقوم بذلك عنه ويكفي.  والقول الثاني: أنه لا بد من قراءة الفاتحة، وهو الصواب.  فالصواب: أنه لا بد أن يقرأ المأموم الفاتحة؛ لقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب وقوله ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها. فالواجب على المأموم أن يقرأها ولو ما سكت الإمام، يقرأها، ثم ينصت، هذا هو الواجب، لكن من تركها جاهلًا؛ لأنه أفتاه بعض أهل العلم بأنه يتركها، أو إن تركها ناسيًا فصلاته صحيحة، وليس عليه قضاء، ليس عليك قضاء؛ لأنك تركتها من أجل ما سمعت من بعض أهل العلم، هكذا لو تركها المأموم ناسيًا ليس عليه قضاء، وهكذا لو جاء المأموم والإمام راكعًا وعند الركوع فإنه يركع معه وتسقط عنه الفاتحة، نعم.\nالمقدم: السكتة اللطيفة من بعض الأئمة يا سماحة الشيخ بعد الفاتحة حتى يعطي فرصة للقراءة؟ الشيخ: الأمر واسع، إن سكت فلا بأس، وإن لم يسكت فلا بأس، يقرؤها، سواء سكت الإمام أو ما سكت الإمام، والإمام مخير، إن سكت فحسن، وإن لم يسكت فلا حرج؛ لأن الأحاديث التي في السكتة ليست بواضحة، وليس هناك حديث صحيح يدل على السكتة، نعم. مقصودي السكتة يعني: بعد الفاتحة، أما السكوت بعد تكبيرة الإحرام فهذا سنة، يسكت حتى يأتي بالاستفتاح، كان النبي ﷺ يأتي بالاستفتاح بعد التكبيرة -التكبيرة الأولى- تكبيرة الإحرام، ثم بعد هذا يتعوذ بالله من الشيطان الرجيم، ويسمي بينه وبين نفسه، ثم يقرأ الفاتحة في الجهرية جهرًا، وسرًا في السرية، والمأموم كذلك يستفتح أيضًا بعد تكبيرة الإحرام قبل أن يشرع إمامه في القراءة، ويقرأ الفاتحة إن كان إمام سكت بعد الفاتحة قرأ فيها، وإن كان ما له سكتة قرأ ولو كان الإمام يقرأ، ثم ينصت بعد ذلك، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13641/هل-علي-شيء-في-الصلوات-الفاىتة-التي-لم-اقرا-فيها-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56412.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15179,"question":"هذه رسالة وردتنا من عبدالمجيد العواجي، من الرياض، يسأل عن قراءة الفاتحة للمأموم، يقول: إذا كان المأموم خلف الإمام، وترك قراءة الفاتحة عمدًا أو سهوًا، سواءٌ كانت الصلاة سرية أو جهرية، هل في ذلك شيء؟نرجو عرض هذا السؤال على فضيلة الشيخ عبدالعزيز وإفادتنا به، وفقه الله.","title":"حكم ترك المأموم قراءة الفاتحة","answer":"الجواب: الواجب على المأموم أن يقرأ الفاتحة، هذا هو المختار من أقوال أهل العلم، وقد ذهب بعض أهل العلم وهم الأكثرون إلى أنها لا تجب قراءتها على المأموم، وأن الإمام يتحملها عنه.  ولكن الأرجح في هذه المسألة أنه لا يتحملها الإمام، بل عليه أن يقرأها المأموم؛ لعموم قول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب وما جاء في معنى ذلك، لكن لو نسيها أو تركها جهلًا أو اعتقادًا أن الإمام يتحملها فإن صلاته صحيحة. أما تعمد تركها فلا ينبغي، بل ينبغي له أن يقرأها خروجًا من خلاف العلماء، وإذا تعمد تركها فالأحوط له أن يقضي الصلاة التي ترك فيها الفاتحة عمدًا من دون اجتهاد ولا تقليد لغيره من أهل العلم، ولا قصدًا لتركها؛ لكونه يرى أنها لا تجب، لكونه طالب علم قد درس الموضوع، وتأمل الأدلة، فإن هذا معذور. أما الذي لا يعرف الحكم، ويعلم أنه مأمور بالقراءة في الصلاة، ثم يتعمد تركها، وقد علم أنه مأمور بقراءتها، وأن قراءتها لازمة، فإن مثله يعيدها احتياطًا وخروجًا من خلاف العلماء، بخلاف الذي تركها ساهيًا أو جاهلًا، أو عن اجتهاد أنها لا تجب، أو تابعًا لمن قال: لا تجب تقليدًا له، وظنًا أنه هو المصيب، فهذا ليس عليه إعادة؛ لكونه عمل باجتهاده، أو تقليده لمن يرى أنها لا تجب، أو لأنه جهل الحكم الشرعي، أو نسيه، فهذا ليس عليه إعادة.  أما كونه يعلم الحكم الشرعي، ويدري أنه مأمور بقراءتها، وأن الواجب عليه قراءتها، ثم يتساهل، ويدعها عمدًا، فهذا ينبغي له القضاء، بل يجب عليه القضاء؛ لكونه خالف ما يعتقد.","link":"https://binbaz.org.sa/fatwas/13671/حكم-ترك-الماموم-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66511.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15295,"question":"يسأل عن أولئك الذين لا يفرقون في النطق بين حرف الضاد والظاء، ويرجون التوجيه، وهل يعتبر فعلهم هذا من اللحن أو لا؟","title":"هل من اللحن من لا يفرق بين الضاد والظاء؟","answer":"الجواب: كثير من الناس لا يستطيع أن يفرق بين الضاد والظاء، فيغتفر له ذلك، ولا يضره ذلك، فقراءته صحيحة، وصلاته صحيحة، والحمد لله؛ لأن الله -جل وعلا- يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وهذه قاعدة كلية، ويقول سبحانه: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286] ويقول -جل وعلا-: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ [البقرة:185]. وقد صرح الحافظ ابن كثير -رحمه الله- في كتابة التفسير بهذه المسألة، وذكر أن الصحيح من أقوال أهل العلم التسامح في ذلك، وأنه لا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13799/هل-من-اللحن-من-لا-يفرق-بين-الضاد-والظاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_498/49802.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15484,"question":"السائل هذا طه سوداني، مقيم في ليبيا، يقول: ما حكم المرأة التي تصلي الصلاة بسورتين فقط، وهما: سورة الفاتحة، وسورة الإخلاص؛ وذلك لعدم تعلمها، وهي تقوم بكل الواجبات الإسلامية؟ وهل صلاتها مقبولة يا سماحة الشيخ؟","title":"حكم الاقتصار على الفاتحة والإخلاص في الصلاة","answer":"الجواب: نعم صلاتها صحيحة، ولو لم تقرأ إلا الفاتحة، لكن قراءتها قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] أو غيرها من السور القصيرة يكون أفضل في الركعة الأولى والثانية من المغرب والعشاء والظهر والعصر والفجر.  أما الركعة الثالثة من المغرب والثالثة والرابعة من الظهر والعصر والعشاء فتكفي قراءة الفاتحة، وإن قرأت قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] مع الفاتحة فلا حرج في الجميع، لكن السنة لها الاقتصار على الفاتحة في الثالثة من المغرب، والثالثة والرابعة من العشاء، والثالثة والرابعة من الظهر، والثالثة والرابعة من العصر، نعم. وإن قرأت زيادة في الثالثة والرابعة من الظهر قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] فلا حرج في ذلك، وإن قرأت في الثالثة والرابعة من الظهر زيادة قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] فلا حرج في ذلك؛ لأنه ورد عن النبي ﷺ ما يدل على أنه ربما قرأ في الثالثة والرابعة من الظهر، يعني: زيادة على الفاتحة. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14012/حكم-الاقتصار-على-الفاتحة-والاخلاص-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56905.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15493,"question":"سماحة الشيخ، هذه السائلة أم عبدالرحمن من القوارة، تقول: صلاة المرأة المنفردة، هل تقرأ في الركعتين الأوليين الفاتحة، وما تيسر من القرآن، وبعد التشهد الأول تقرأ الفاتحة فقط أم ماذا تفعل؟","title":"ما تقرأ المرأة في صلاتها؟","answer":"الجواب: نعم، مثل الرجل، السنة في الأولى والثانية أن تقرأ مع الفاتحة زيادة، أما الفاتحة ركن لا بد من الفاتحة، لكن تقرأ مع الفاتحة زيادة ما تيسر من القرآن.  أما في الثالثة والرابعة للظهر والعصر، والثالثة في المغرب، والثالثة والرابعة في العشاء، تكفي الفاتحة، وإن قرأت مع الفاتحة شيئًا زيادة فلا بأس، لكن ترك القراءة أفضل، يكفي الفاتحة في الثالثة والرابعة إلا في الظهر فمن قرأ الزيادة فلا حرج؛ لأنه ثبت عن النبي ﷺ ما يدل على فعل ذلك، لكن يكون بعض الأحيان، وثبت في الصحيحين من حديث أبي قتادة: «أن النبي ﷺ كان يقتصر على فاتحة الكتاب في الثالثة والرابعة في الظهر والعصر». المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14022/ما-تقرا-المراة-في-صلاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56910.mp3","categories":["القراءة في الصلاة","قضايا المرأة"]},{"id":15517,"question":"هذه رسالة وصلت من مستمع للبرنامج، يقول: سماحة الشيخ، هل الاستعاذة والبسملة تكون عند قراءة الفاتحة، وأيضًا عند قراءة السورة التي تلي الفاتحة، ويكون ذلك في جميع الركعات؟ وإذا لم يقرأ الإنسان السورة التي بعد الفاتحة من أولها هل ينبغي له أيضًا أن يبدأ بالاستعاذة والبسملة؟","title":"متى تقرأ البسملة والاستعاذة في الصلاة؟","answer":"الجواب: تكفي الاستعاذة في أول قراءة الركعة، استعاذته عند الفاتحة تكفي، وإذا قرأ بعد الفاتحة سورة يسمي فقط، بسم الله الرحمن الرحيم وَالْعَصْرِ [العصر: 1] بسم الله الرحمن الرحيم أَلْهَاكُمُ [التكاثر: 1] تكفي البسملة في السورة بعد الفاتحة، وأما الاستعاذة تكون في أولها قبل الفاتحة، نعم.","link":"https://binbaz.org.sa/fatwas/14059/متى-تقرا-البسملة-والاستعاذة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69110.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15526,"question":"يقول هذا السائل: بما أن الصلاة ليس فيها سكوت، فماذا يقول الإمام في السكتة التي تلي قراءة الفاتحة بالنسبة للصلاة الجهرية؟","title":"ما يقول الإمام في السكتة التي بعد الفاتحة؟","answer":"الجواب: ما فيها شيء، إذا سكت سكتة خفيفة يقرأ المأموم فيها الفاتحة، وهو لا يقرأ شيئًا، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/14061/ما-يقول-الامام-في-السكتة-التي-بعد-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69111.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15597,"question":"سؤاله الأخير يقول: هل صحيح أن المأموم في الصلاة الجهرية لا يقرأ الفاتحة خلف إمامه، ولا يؤمن بعد إتمام الإمام الفاتحة حسب المذهب الحنفي، إذا كان الأمر كذلك فماذا عليه أن يفعل؟","title":"حكم قراءة الفاتحة والتأمين للمأموم","answer":"الجواب: المذهب الحنفي هنا مرجوح، المذهب الحنفي مرجوح في هذا، والصواب ما عليه الجمهور، المأموم يؤمن مع إمامه؛ لقول النبي ﷺ: إذا أمن الإمام فأمنوا وفي اللفظ الآخر: إذا قال الإمام: ولا الضالين، فقولوا: آمين، فإنه من وافق تأمينه تأمين الملائكة غفر له ما تقدم من ذنبه وهذا هو الصواب الذي عليه جمهور أهل العلم خلافًا لمذهب الأحناف، مذهب الأحناف هنا مرجوح. وكذلك يقرأ على الصحيح، يقرأ في الجهرية، يقرأ الفاتحة فقط، ثم ينصت؛ لقوله ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم. قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها فاستثنى الفاتحة -عليه الصلاة والسلام-، فدل ذلك على أنه يقرأ الفاتحة فيما أسر في إمامه إذا أسر، وإن كان الإمام ما أسر يعني: قرأ الفاتحة ثم شرع بعدها، ولم يكن له سكتة قرأها، ولو في حال قراءة إمامه جهرًا، يقرؤها سرًا في نفسه ثم ينصت لإمامه؛ عملًا بالأحاديث الكثيرة الصحيحة عن رسول الله -عليه الصلاة والسلام-. أما في السرية كالظهر والعصر والثالثة من المغرب، والثالثة والرابعة من العشاء هذه يقرأ فيها على كل حال، يلزمه أن يقرأ الفاتحة عند الأكثر؛ لقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب وللحديث السابق: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم. قال: لا تفعلوا إلا بفاتحة الكتاب فهذا في الجهرية، أما في السرية فإنه يقرأ الفاتحة، ويقرأ معها ما تيسر في الأولى والثانية من الظهر والعصر، ويقرأ الفاتحة في الثالثة والرابعة من الظهر والعصر والثالثة من المغرب أيضًا، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14138/حكم-قراءة-الفاتحة-والتامين-للماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_694/nour_69403.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15826,"question":"سائل يقول يا سماحة الشيخ: إذا كنت مأمومًا في الصلاة الجهرية، وكان الإمام لا يتوقف بين قراءة الفاتحة والسورة التي بعدها، فهل أقرأ الفاتحة أثناء قراءة الإمام، أم أنصت له؟","title":"هل أقرأ الفاتحة أثناء قراءة الإمام، أم أنصت له؟","answer":"الجواب: عليك أن تقرأ القرآن، عليك أن تقرأ الفاتحة ولو ما سكت؛ لقول النبي ﷺ للصحابة: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب؛ فإنه لا صلاة لمن لم يقرأ بها وفي الحديث الآخر يقول ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب. فالواجب على المأموم أن يقرأها، وإن استمر إمامه في القراءة، يقرأ الفاتحة، ثم ينصت، فإن كان جاهلًا، أو ناسيًا صحت صلاته المأموم خاصة. أما الإمام والمنفرد فلا بد من الفاتحة، ولا تصح صلاته بدون ذلك لا ناسيًا ولا جاهلًا، أما المأموم فهو أسهل؛ لأن الرسول ﷺ لما دخل أبو بكرة والنبي ﷺ راكع، ركع دون الصف، ثم دخل في الصف، فقال له النبي ﷺ: زادك الله حرصًا، ولا تعد ولم يأمره بقضاء الركعة، فدل على أن المأموم إذا جاء والإمام راكع تجزئه الركعة، وقد فاتته القراءة، وهكذا لو جهل أو نسي ولم يقرأ مع الإمام كفته قراءة الإمام لكن لا يتعمد تركها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14415/هل-اقرا-الفاتحة-اثناء-قراءة-الامام ام-انصت-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57518.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15837,"question":"يقول: هل قراءة الفاتحة في كل ركعة واجبة؟ وهل يغني عنها شيء؟","title":"حكم قراءة الفاتحة في كل ركعة","answer":"الجواب: قراءة الفاتحة ركن في كل ركعة للإمام والمنفرد، واجبة في حق المأموم في كل ركعة؛ لقوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب فعلى الإمام أن يقرأها في كل ركعة، وعلى المنفرد أن يقرأها في كل ركعة، وعلى المأموم أن يقرأها في كل ركعة.\nلكن في حق المأموم واجبة لو نسيها سقطت بخلاف الإمام والمنفرد، فإنها لا بد منها، لا تسقط لا جهلًا ولا نسيانًا بل عليه أن يؤديها -الإمام والمنفرد- في كل ركعة.  وأما المأموم فلو فاته القيام مع الإمام، ولم يأتِ إلا وهو راكع أجزأته الركعة، وتحملها الإمام، وهكذا لو نسيها مع الإمام، أو جهلها مع الإمام، فإنه يتحملها عن الإمام، أما أنه يتعمد فلا يتعمد، ليس للمأموم أن يتعمد تركها، بل يجب عليه أن يقرأها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14428/حكم-قراءة-الفاتحة-في-كل-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57529.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":15887,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يسأل فيها، ويقول: هل تخصيص الجهر بالقراءة في صلاة الليل يشمل الفروض والنوافل أم أنه بالفرض خاصة؟جزاكم الله خيرًا.","title":"هل الجهر في صلاة الليل يشرع في الفرائض والنوافل؟","answer":"الجواب: عام للفرائض والنوافل، يشرع الجهر في التهجد بالليل، وفي الأولى والثانية من المغرب والعشاء كل ذلك مشروع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14480/هل-الجهر-في-صلاة-الليل-يشرع-في-الفراىض-والنوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74507.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16015,"question":"تقول أم شموس من مكة المكرمة: إذا نسيت في الصلاة فقدمت قراءة سورة أخرى على الفاتحة ثم بعد ذلك أتيت بفاتحة الكتاب فما حكم صلاتي؟","title":"ما حكم تقديم قراءة السورة على الفاتحة؟","answer":"الجواب: لا حرج فيها، ما دام أتيت بالفاتحة ولو تأخرت، لو نسيت وقدمت قراءة السورة على الفاتحة، ثم قرأت الفاتحة، الحمد لله المقصود حصل، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14648/ما-حكم-تقديم-قراءة-السورة-على-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57905.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16108,"question":"هذا السائل طاهر آدم من غانا -من غرب أفريقيا-الحقيقة: بعث بمجموعة من الأسئلة، وهو من مستمعي هذا البرنامج يقول: سماحة الشيخ! اختلف العلماء في بلادنا عند حكم قراءة الفاتحة خلف الإمام؛ فإن منهم من قال: بأنها تجوز، ويستدلون بقول النبي الكريم ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب وهي: أم القرآن، أم الكتاب، وقال بعضهم: لا يجوز، ويستدلون بقوله تعالى: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا لَعَلَّكُمْ تُرْحَمُونَ [الأعراف:204] ما هو الأصح من الأدلة في ذلك؟","title":"ما حكم قراءة الفاتحة خلف الإمام؟","answer":"الجواب: المسألة فيها خلاف بين العلماء، بعض أهل العلم يقولون: قراءة الإمام قراءة للمأموم، ويكفي، ولا تلزمه القراءة لا الفاتحة، ولا غيرها، ويكفيه قراءة الإمام. والقول الثاني: إنه لابد من الفاتحة، وهذا هو الصواب؛ لقول النبي ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب؛ فإنه لا صلاة لمن لم يقرأ بها فنص النبي ﷺ على أن المأموم يقرأ الفاتحة، ثم ينصت، وفي السرية يقرؤها، وما تيسر معها، وفي الجهرية يقرأها، ثم ينصت.. هذا هو القول الصواب.","link":"https://binbaz.org.sa/fatwas/14760/ما-حكم-قراءة-الفاتحة-خلف-الامام","audio":"","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16135,"question":"إذا كنا في صلاة جهرية، وقرأ الإمام في الركعة الأولى الفاتحة، وما أن انتهى من قراءة الفاتحة لم يسكت بعد الفاتحة، بل واصل، فهل في حق الإمام أن يقرأ الفاتحة؟ أم ينصت إلى الإمام؟ جزاكم الله خيرًا.","title":"حكم قراءة الفاتحة للمأموم في الصلاة الجهرية","answer":"الجواب: يقرأ. المقدم: يقرأ الفاتحة؟ الشيخ: إذا كان ما قرأها يقرؤها، ولو كان الإمام يقرأ، يقرأ والإمام يقرأ الفاتحة، ثم ينصت؛ لأن الفاتحة واجبة عليه على الصحيح، يقول النبي ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها ومن هنا أخذ الوجوب في قراءة الفاتحة، ولكن إذا كان هناك سكوت للإمام طويل، يقرأ في السكوت، أما إذا كان الإمام لا يسكت، أو سكوتًا قليلًا؛ فإنه يقرأ الفاتحة، ويكمل، ولو مع قراءة إمامه، ثم ينصت. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14820/حكم-قراءة-الفاتحة-للماموم-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_804/nour_80412.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16183,"question":"هذا السائل ياسر القحطاني يقول في هذا  بالنسبة -يا سماحة الشيخ- لقراءة الفاتحة في كل ركعة هل هي واجبة؟ وهل يغني عنها شيء؟ وإذا لم يترك الإمام فرصة لقراءتها، هل يتحمل ذلك مأجورين؟","title":"هل يجب قراءة الفاتحة في كل ركعة؟","answer":"الجواب: الواجب أن تقرأ في كل ركعة؛ لقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب لا صلاة لمن لم يقرأ بأم الكتاب لا تقبل صلاة، لا يقرأ فيها بأم الكتاب ولأنه ﷺ كان يقرؤها في كل ركعة، ويقول: صلوا كما رأيتموني أصلي.  والمأموم يقرؤها، ولو لم يسكت إمامه، يقرؤها في كل ركعة لقوله ﷺ: لعلكم تقرؤون خلف إمامكم؟! قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب؛ فإنه لا صلاة لمن لم يقرأ بها يقرأها المأموم، وإن كان إمامه لم يسكت، يقرؤها بينه وبين نفسه، ثم يسكت.. ثم ينصت، نعم. المقدم: أحسن الله إليكم!","link":"https://binbaz.org.sa/fatwas/14850/هل-يجب-قراءة-الفاتحة-في-كل-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58009.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16212,"question":"سؤالها الأخير تقول فيه: إذا شعرت أنني لم أحسن القراءة في الصلاة هل أعيدها؟","title":"حكم إعادة الصلاة لمن لم يحسن فيها القراءة","answer":"الجواب: إذا كانت الفاتحة سليمة؛ فلا يلزمك إعادة ما زاد عليها، أما الفاتحة فلا بد أن تقرئيها قراءة صحيحة، ليس فيها لحن يحيل المعنى، أما اللحن الذي لا يحيل المعنى؛ فلا تلزم إعادتها، ويعفى عنه. لو قرأت الحمدَ لله رب العالمين، أو الحمدِ لله رب العالمين بالجر؛ لا يضر، أو قلت: الرحمنُ الرحيم، أو الرحمنَ الرحيم؛ لا يضر هذا؛ لأن هذا اللحن لا يحيل المعنى، ولا يغير المعنى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14892/حكم-اعادة-الصلاة-لمن-لم-يحسن-فيها-القراءة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75109.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16412,"question":"يسأل سؤالًا آخر ويقول: بعض المصلين يقولون أثناء الصلاة، وعندما ينتهي الإمام من قراءة آية يبين فيها الله  قدراته العظيمة مثل قوله تعالى: أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى [القيامة:40] يقولون: بلى، فما الحكم في هذا؟ جزاكم الله خيرًا.","title":"ما حكم قول: (بلى) في نهاية سورة القيامة؟","answer":"الجواب: هذا ورد فيه حديث خاص عن النبي ﷺ أنه إذا قال القارئ: أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى [القيامة:40] يقول: بلى، سبحانك فبلى فإنه مشروع، ولا بأس، يقوله الإمام، والمأموم، والمنفرد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15146/ما-حكم-قول-بلى-في-نهاية-سورة-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81204.mp3","categories":["القراءة في الصلاة","القرآن وعلومه"]},{"id":16423,"question":"يسأل سؤالًا آخر ويقول: بعض المصلين يقولون أثناء الصلاة، وعندما ينتهي الإمام من قراءة آية يبين فيها الله  قدراته العظيمة مثل قوله تعالى: أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى [القيامة:40] يقولون: بلى، فما الحكم في هذا؟ جزاكم الله خيرًا.","title":"ما حكم قول: (بلى) في نهاية سورة القيامة؟","answer":"الجواب: هذا ورد فيه حديث خاص عن النبي ﷺ أنه إذا قال القارئ: أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى [القيامة:40] يقول: بلى، سبحانك فبلى فإنه مشروع، ولا بأس، يقوله الإمام، والمأموم، والمنفرد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15146/ما-حكم-قول-بلى-في-نهاية-سورة-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81204.mp3","categories":["القراءة في الصلاة","القرآن وعلومه"]},{"id":16442,"question":"يقول: إذا قرأت في الصلاة الجهرية سرًا، هل هذا يخل بالصلاة، وهل علي سجود سهو؟","title":"ما حكم ترك الجهر بالصلاة الجهرية؟","answer":"الجواب: لا يخل بالصلاة، ولكن تركت الأفضل، وتركت السنة، وليس عليك سجود سهو، وإن سجدت؛ فحسن، نعم. إذا كنت تركته سهوًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15138/ما-حكم-ترك-الجهر-بالصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75511.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16454,"question":"المستمع محمد عبدالرحمن عثمان بعث رسالة ضمنها سؤالين، في سؤاله الأول يقول: إذا قرأت سورة بعد الفاتحة في الركعتين الأخيرتين في الرباعية، أو في الركعة الأخيرة في المغرب؛ فهل علي سجود سهو؟ وماذا أقول فيه؟ جزاكم الله خيرًا.","title":"حكم القراءة بعد الفاتحة في الركعات الأخيرة","answer":"الجواب: ليس عليك سجود سهو، ولكن ترك ذلك أفضل، ترك القراءة أفضل، ومن قرأ فلا حرج، قد ثبت من حديث أبي سعيد  ما يدل على أن النبي ﷺ قرأ في الثالثة والرابعة زيادة على الفاتحة، وثبت عن الصديق  أنه قرأ في الثالثة من المغرب بعد الفاتحة: رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8].  فالأمر في هذا واسع، لكن ترك القراءة أفضل، إلا في الظهر؛ فلا بأس من القراءة في الثالثة والرابعة، بعض الشيء زيادة على الفاتحة في بعض الأحيان، لحديث أبي سعيد ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15166/حكم-القراءة-بعد-الفاتحة-في-الركعات-الاخيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75516.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16501,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أختكم في الله (س. م. ص) من الأردن، لها جمع من الأسئلة في أحدها تقول: هل صلاة الضحى جهرية، أم سرية؟ وهل الجهر في القراءة فقط، أم في الركوع والسجود؟","title":"صفة القراءة في صلاة الضحى","answer":"الجواب: صلاة الضحى سرية، وهكذا الظهر والعصر كلها سرية، ولو جهرت المرأة، أو الرجل في صلاة الضحى لم يضر ذلك؛ لأن الجهر والإخفات سنة، ليس بمحرم، ولا واجب، فالجهر سنة، والإخفات سنة، فلو جهر في النهار، أو أسر في الليل؛ فصلاته صحيحة، لكنه خلاف السنة، فالسنة أن يسر بالنهار في صلاة الضحى، وفي الظهر والعصر، ويجهر بالليل في صلاة المغرب والعشاء، في الركعتين الأوليين إلا الفجر فإنها جهرية، والجمعة جهرية، ولو كانت نهارية الجمعة جهرية، والعيد جهرية، وصلاة الفجر جهرية، وصلاة الاستسقاء جهرية، ولو كانت في النهار. أما النوافل فهي سرية في النهار، وهكذا صلاة الظهر سرية في النهار، صلاة الظهر معلوم أنها سرية، وهكذا العصر سرية، والمغرب والعشاء جهرية في الأولى والثانية، والفجر جهرية كما تقدم، وهكذا صلاة الجمعة جهرية، صلاة العيد، صلاة الاستسقاء، صلاة الكسوف كلها جهرية؛ لأن الرسول جهر، عليه الصلاة والسلام.  لكن لو أسر الإنسان في الجهرية؛ صلاته صحيحة، سواء عامدًا، أو ناسيًا، لكنه خلاف السنة، لا يتعمد، ليس له أن يتعمد السر في الجهرية، وليس له أن يتعمد الجهر في السرية؛ لأنه خلاف السنة، لكن لو جهر متعمدًا؛ لم تبطل صلاته، أو أسر في الجهرية؛ لم تبطل صلاته، لكنه خالف السنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15258/صفة-القراءة-في-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81407.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16504,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أختكم في الله (س. م. ص) من الأردن، لها جمع من الأسئلة في أحدها تقول: هل صلاة الضحى جهرية، أم سرية؟ وهل الجهر في القراءة فقط، أم في الركوع والسجود؟","title":"صفة القراءة في صلاة الضحى","answer":"الجواب: صلاة الضحى سرية، وهكذا الظهر والعصر كلها سرية، ولو جهرت المرأة، أو الرجل في صلاة الضحى لم يضر ذلك؛ لأن الجهر والإخفات سنة، ليس بمحرم، ولا واجب، فالجهر سنة، والإخفات سنة، فلو جهر في النهار، أو أسر في الليل؛ فصلاته صحيحة، لكنه خلاف السنة، فالسنة أن يسر بالنهار في صلاة الضحى، وفي الظهر والعصر، ويجهر بالليل في صلاة المغرب والعشاء، في الركعتين الأوليين إلا الفجر فإنها جهرية، والجمعة جهرية، ولو كانت نهارية الجمعة جهرية، والعيد جهرية، وصلاة الفجر جهرية، وصلاة الاستسقاء جهرية، ولو كانت في النهار. أما النوافل فهي سرية في النهار، وهكذا صلاة الظهر سرية في النهار، صلاة الظهر معلوم أنها سرية، وهكذا العصر سرية، والمغرب والعشاء جهرية في الأولى والثانية، والفجر جهرية كما تقدم، وهكذا صلاة الجمعة جهرية، صلاة العيد، صلاة الاستسقاء، صلاة الكسوف كلها جهرية؛ لأن الرسول جهر، عليه الصلاة والسلام.  لكن لو أسر الإنسان في الجهرية؛ صلاته صحيحة، سواء عامدًا، أو ناسيًا، لكنه خلاف السنة، لا يتعمد، ليس له أن يتعمد السر في الجهرية، وليس له أن يتعمد الجهر في السرية؛ لأنه خلاف السنة، لكن لو جهر متعمدًا؛ لم تبطل صلاته، أو أسر في الجهرية؛ لم تبطل صلاته، لكنه خالف السنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15258/صفة-القراءة-في-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81407.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16528,"question":"هل صحيح أنه لا بد أن يسمع المسلم نفسه ما يقول في الصلاة؟","title":"حكم إسماع النفس بالقراءة في الصلاة","answer":"الجواب: نعم، ما يكون متكلما إلا إذا أسمع نفسه إذا كان يسمع، أما إذا كان عنده ثقل في السمع؛ يتكلم بقدر طاقته من غير أن يشوش على من حوله يعني: يتيقن أنه تلفظ، يتلفظ ما هو بالنية، لا بد يتلفظ باللسان، تلفظًا يسمع من المتكلم، يسمعه المتكلم من نفسه لو كان -يعني- سمعه صحيحًا، أما إذا كان سمعه فيه خلل؛ فلا يرفعه، يؤذي الناس، لا يشوش على الناس، لكن يتأكد أنه تلفظ، يتلفظ بالقراءة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15276/حكم-اسماع-النفس-بالقراءة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75710.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16538,"question":"يسأل عن سجود السهو لو سمحتوا يقول: هل على من زاد في الصلاة، فقرأ سورة قصيرة، أو آيات بعد الفاتحة في الركعة الثالثة، أو الرابعة مثلًا؟","title":"حكم الزيادة على الفاتحة في الركعتين الثالثة والرابعة","answer":"الجواب: ليس عليه سجود سهو؛ لأن هذه الزيادة إما أن تكون مشروعة، أو غير مشروعة، فإن كانت مشروعة كما في الركعة الأولى والثانية هذا أمر معلوم، لو نسيها ما عليه شيء، وإن كانت غير مشروعة في الثالثة والرابعة في العصر، وفي المغرب والعشاء؛ فالإتيان بها لا يضر، ولا يبطل الصلاة، ولا يؤثر فيها، الأمر فيها واسع، ولهذا ذهب بعض أهل العلم إلى شرعية الزيادة في الثالثة والرابعة في الظهر في بعض الأحيان، لحديث أبي سعيد -رضي الله تعالى عنه- أنه قال: \"حزرنا قراءة النبي ﷺ في الظهر قدر الم تنزيل السجدة، وفي الأخريين على النصف من ذلك\".  فقوله: \"على النصف من ذلك\" يدل على أنه يقرأ مع الفاتحة زيادة، فإذا فعلها بعض الأحيان؛ فلا حرج. وجاء عن الصديق  في الموطأ بسند جيد: أنه قرأ في الثالثة في المغرب: رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8] وجاء في بعض الأحاديث أن بعض أئمة الأنصار كان يقرأ في كل ركعة زيادة قل هو الله أحد مع الفاتحة، وأقره النبي ﷺ قال: \"إنها صفة الرحمن، وأنا أحب أن أقرأها\" كان يقرأها في كل ركعة، فأقره النبي ﷺ. فالأمر في هذا واسع، فلو زاد الإنسان سواء كان في الثالثة، أو الرابعة في العصر، والعشاء، أو في الثالثة في المغرب؛ فلا حرج في ذلك، وليس عليه سجود سهو، لكن ترك ذلك أفضل، أما في الظهر فالأمر فيها واسع، في الظهر في الثالثة والرابعة إن زادها بعض الأحيان عملًا بحديث أبي سعيد، فذلك حسن، ويكون في الأغلب لا يزيد، عملًا بحديث أبي قتادة  في الصحيحين أنه ﷺ كان يقرأ في الأخريين من الظهر والعصر بفاتحة الكتاب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15269/حكم-الزيادة-على-الفاتحة-في-الركعتين-الثالثة-والرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81503.mp3","categories":["سجود السهو","القراءة في الصلاة"]},{"id":16576,"question":"يقول: ما الحكم في حالة انتابتني كنت أصلي بمجموعة من الزملاء؛ فأخطأت، وتجاوزت آية من القرآن، ولم يفتح علي أحد، فتذكرت بعد انتهاء الصلاة، ما الحكم حينئذٍ؟","title":"حكم من أخطأ في القراءة ولم يفتح عليه أحد","answer":"الجواب: لا حرج في ذلك، والحمد لله، إذا كانت الفاتحة أديتها كما يجب؛ فالقراءة الزائدة على الفاتحة مستحبة، فإذا سقط منها آية، أو نسيتها؛ فلا حرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15303/حكم-من-اخطا-في-القراءة-ولم-يفتح-عليه-احد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75803.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16707,"question":"إذا نسي الإنسان أن يقرأ الفاتحة في الركعة الثانية، أو الثالثة هل يعيد الصلاة، أم أن ذلك النسيان ينطبق على الركعة الأولى فقط؟","title":"حكم نسيان قراءة الفاتحة في الصلاة","answer":"الجواب: إذا كان إمامًا، أو منفردًا تبطل ركعته، ويأتي بركعة بدلها، ويسجد للسهو، أما إذا كان مأمومًا؛ فإنه تسقط عنه، فإن الإمام يتحملها عنه إذا كان ناسيًا؛ لأن الرسول ﷺ لما أتى أبو بكرة، وركع دون الصف والإمام راكع، ثم دخل في الصف، لم يأمره النبي ﷺ بقضاء الركعة، وقال: زادك الله حرصًا، ولا تعد فدل ذلك على أن من فاته القيام؛ سقطت عنه الفاتحة، إذا جاء والإمام راكع؛ أدرك الركعة، فإذا نسيها وهو قائم مع الإمام، أو جاهل؛ فيكون أدرك الركعة، لا يقضيها والحمد لله، إذا كان مأمومًا، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15440/حكم-نسيان-قراءة-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58421.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16714,"question":"تقول السائلة: هل يجوز أن أحمل المصحف، وأقرأ منه في صلاة الفرض، حيث أقرأ السور التي لا أحفظها، وفي النافلة أيضًا، هل يجوز أن أحمل المصحف؟","title":"حكم القراءة من المصحف في صلاة الفرض","answer":"الجواب: لا حرج، لكن كونك تقرئين عن ظهر قلب أخشع وأقرب إلى الخشوع، ولو قرأ المصلي من المصحف فلا حرج، لكن كونه يقرأ عن حفظ يكون أجمع لقلبه، وأخشع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15453/حكم-القراءة-من-المصحف-في-صلاة-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58424.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16940,"question":"أحسن الله إليكم، هذا أبو أحمد من حريملا سوداني يقول: سماحة الشيخ هل يصح قراءة المعوذتين وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] في الوتر؟ وهل القراءة سرية؟ أم جهرية؟","title":"السور التي يستحب قراءتها في الوتر","answer":"الجواب: إذا أوتر بالثلاث مستحب، بسبح وبـقُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون: 1] وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] يعني في ختام التهجد، إذا صلى الثلاث الأخيرة الأولى بسبح، والثانية بـقُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون: 1] والثالثة بـقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] هذا ورد عن النبي ﷺ والسنة الجهر، لكن جهرًا لا يؤذي من حوله، جهرًا لا يؤذي من حوله، إن كان حوله مصلون، أو نيام، أو قراء لا يؤذيهم، الجهر الخفيف، أما إذا كان ما حوله حتى لا بأس أن يجهر. نعم... جهرًا زائدًا، نعم.","link":"https://binbaz.org.sa/fatwas/15714/السور-التي-يستحب-قراءتها-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58613.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16972,"question":"هل التسمية بالصلاة الجهرية سرًا، أم جهرًا؟","title":"هل السنة الجهر أم الإسرار بالبسملة في الصلاة؟","answer":"الجواب: السنة السر، كان النبي ﷺ وأبو بكر وعمر لا يجهرون بالبسملة، يجهرون بالحمد لله، أول ما يقرأ: الحمد لله رب العالمين يسرون ببسم الله الرحمن الرحيم، والتعوذ، هكذا ثبت في الأحاديث الصحيحة عن أنس وغيره أن الرسول ﷺ كان، وهكذا أبو بكر وعمر لا يجهرون بالبسملة، أول ما يسمعون الناس: الحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/15748/هل-السنة-الجهر-ام-الاسرار-بالبسملة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58621.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16980,"question":"تقول: إنني عندما أوتر أصلي ركعةً واحدة، وأقرأ فيها سورة الإخلاص، والفلق، والناس، فهل عملي صحيح؟","title":"حكم قراءة الإخلاص والفلق والناس في الوتر","answer":"الجواب: الأفضل الاقتصار على: قل هو الله أحد هذا هو الأفضل في الركعة الأخيرة، ركعة الوتر، هذا المحفوظ عن النبي ﷺ يقرأ فيها: قل هو الله أحد. أما زيادة المعوذتين فالحديث فيها ضعيف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15799/حكم-قراءة-الاخلاص-والفلق-والناس-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82918.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":16996,"question":"تقول: إنني عندما أوتر أصلي ركعةً واحدة، وأقرأ فيها سورة الإخلاص، والفلق، والناس، فهل عملي صحيح؟","title":"حكم قراءة الإخلاص والفلق والناس في الوتر","answer":"الجواب: الأفضل الاقتصار على: قل هو الله أحد هذا هو الأفضل في الركعة الأخيرة، ركعة الوتر، هذا المحفوظ عن النبي ﷺ يقرأ فيها: قل هو الله أحد. أما زيادة المعوذتين فالحديث فيها ضعيف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15799/حكم-قراءة-الاخلاص-والفلق-والناس-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82918.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17015,"question":"سماحة الشيخ، هل من السنة الجهر بالبسملة في الصلاة الجهرية، أم الإسرار؟ مع الدليل؟","title":"حكم الإسرار بالبسملة في الصلاة الجهرية","answer":"الجواب: السنة الإسرار، كان النبي ﷺ يسر بها، كما ثبت ذلك عنه ﷺ وهكذا عن الصديق، وعن عمر كان يفتتح الصلاة بالتكبير، والقراءة بالحمد، ولا يجهر بالبسملة، ولا بالتعوذ، وهذا هو الأفضل عدم الجهر بالتعوذ، وعدم الجهر بالتسمية، نعم.","link":"https://binbaz.org.sa/fatwas/15803/حكم-الاسرار-بالبسملة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58708.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17063,"question":"في سؤال آخر يقول: كنت أؤم المصلين في صلاة المغرب، وفي الركعة الأولى قرأت الفاتحة، وسورة الماعون، وفي الركعة الثانية قرأت الفاتحة وسورة الضحى، وبعد الانتهاء من الصلاة قال لي أحد المصلين: لا تقدم سورة الماعون على الضحى، علمًا بأنني في وقت صلاة، وليس في وقت قراءة قرآن، وجهوني جزاكم الله خيرًا.","title":"حكم الترتيب بين سور القرآن عند القراءة في الصلاة","answer":"الجواب: الأفضل مثل ما قال لك أخوك أن ترتب القراءة مثل ما في المصحف، تقرأ الضحى أولًا، ثم الماعون في الثانية، لا تعكس، لكن لا حرج، فعلك لا حرج فيه -إن شاء الله- كونك قرأت الماعون، ثم قرأت الضحى لا حرج، لكن تركت الأفضل والأولى؛ لأن الصحابة رتبوا القرآن كما نزل في العرضة الأخيرة على النبي -عليه الصلاة والسلام- فاقرأ القرآن أنت وغيرك كما في المصحف، تبدأ من الفاتحة، ثم البقرة، ثم آل عمران، ثم النساء، ثم المائدة، وهكذا .. إلى آخره، لا تعكس، فإذا قرأت الماعون، فاقرأ بعدها إنا أعطيناك الكوثر أو غيرها مما بعدها، ولا تقرأ التي قبلها: لإيلاف قريش أو ألم تر كيف فعل ربك .. أو الهمزة أو الضحى لا، هذا الأفضل ، هذا هو الأفضل، ولكن لا حرج والحمد لله. نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15855/حكم-الترتيب-بين-سور-القران-عند-القراءة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_721/nour_72109.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17083,"question":"يقول: لماذا كانت صلوات الليل جهرية، وصلوات النهار سرية؟","title":"الحكمة من كون صلوات الليل جهرية والنهار سرية","answer":"الجواب: الأقرب -والله أعلم- أن الحكمة في ذلك أن النهار محل العمل، ومحل الأخذ، والعطاء، والاجتماع، فالسر أجمع للقلب، إذا قرأ سرًا أجمع لقلبه، وأخشع لقلبه حتى يتدبر. والليل محل الخلوة في البيت، ومع الأهل، ومحل خلوة بالله  فإذا جهر كان أنشط له، وأقرب إلى انتفاعه بالقراءة، وأبعد عن النوم، فهو في الليل يقرأ جهرة ليتدبر كتاب الله، ولينشط في قراءته، ويجمع قلبه على ذلك؛ لأن ما حوله هادئ، فليس عنده مشاغل، فيرفع صوته حتى يجمع قلبه على القراءة، ويتدبرها عن صوت مرفوع رفعًا لا يشق عليه، ولا يؤذي من حوله، إذا كان حوله نوام، أو مصلون، أو قراء لا يرفع رفعًا يؤذيهم، ويشق عليهم، لكن رفعًا خفيفًا، أما إذا كان ما حوله أحد فيكون رفعه وسطًا، يطرد الشيطان، ويعينه على النشاط، والتدبر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15941/الحكمة-من-كون-صلوات-الليل-جهرية-والنهار-سرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83110.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17103,"question":"يقول: لماذا كانت صلوات الليل جهرية، وصلوات النهار سرية؟","title":"الحكمة من كون صلوات الليل جهرية والنهار سرية","answer":"الجواب: الأقرب -والله أعلم- أن الحكمة في ذلك أن النهار محل العمل، ومحل الأخذ، والعطاء، والاجتماع، فالسر أجمع للقلب، إذا قرأ سرًا أجمع لقلبه، وأخشع لقلبه حتى يتدبر. والليل محل الخلوة في البيت، ومع الأهل، ومحل خلوة بالله  فإذا جهر كان أنشط له، وأقرب إلى انتفاعه بالقراءة، وأبعد عن النوم، فهو في الليل يقرأ جهرة ليتدبر كتاب الله، ولينشط في قراءته، ويجمع قلبه على ذلك؛ لأن ما حوله هادئ، فليس عنده مشاغل، فيرفع صوته حتى يجمع قلبه على القراءة، ويتدبرها عن صوت مرفوع رفعًا لا يشق عليه، ولا يؤذي من حوله، إذا كان حوله نوام، أو مصلون، أو قراء لا يرفع رفعًا يؤذيهم، ويشق عليهم، لكن رفعًا خفيفًا، أما إذا كان ما حوله أحد فيكون رفعه وسطًا، يطرد الشيطان، ويعينه على النشاط، والتدبر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15941/الحكمة-من-كون-صلوات-الليل-جهرية-والنهار-سرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83110.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17112,"question":"من أسئلته يقول يا سماحة الشيخ: سنة الفجر، أو ركعتي الفجر هل تجزي فيها الفاتحة فقط، أو الفاتحة وسورة أخرى؟","title":"هل تجزئ الفاتحة في سنة الفجر؟","answer":"الجواب: الفاتحة مجزئة لكن السنة أن يقرأ معها غير الفاتحة، يقرأ: قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] في الأولى، وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] في الثانية مع الفاتحة، أو يقرأ في الأولى: قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا [البقرة:136] من سورة البقرة، وفي الثانية: قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا [آل عمران:64] من سورة آل عمران. نعم.","link":"https://binbaz.org.sa/fatwas/15918/هل-تجزى-الفاتحة-في-سنة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58909.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17123,"question":"ما حكم الجهر في الصلوات الجهرية بالنسبة للمرأة؟ وجهونا جزاكم الله خيرًا.","title":"ما حكم الجهر بالقراءة في الصلوات للمرأة؟","answer":"الجواب: يستحب لها الجهر بالقراءة في المغرب، والعشاء، والفجر كما يستحب للرجال، الفتاة تجهر جهرًا يناسبها، أو مع .. إذا كانت مع النساء ليس يسمعها رجال من الأجانب، فإن كان يسمعها الرجال فالأفضل عدم الجهر، لئلا يفتتن بها، أما إذا كان ما عندها رجال، وإنما عندها النساء، أو ما عندها أحد، أو محارم لا بأس بذلك، تجهر.. السنة الأفضل الجهر، في الأولى والثانية من المغرب، والعشاء، وفي صلاة الفجر. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15936/ما-حكم-الجهر-بالقراءة-في-الصلوات-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72205.mp3","categories":["القراءة في الصلاة","قضايا المرأة"]},{"id":17157,"question":"من خميس مشيط السائل: (ع. ح) يقول: كيف تكون القراءة في صلاة آخر الليل في البيت، هل تكون جهرًا، أم سرًا؟","title":"كيفية القراءة في صلاة الليل","answer":"الجواب: يفعل ما هو أصلح لقلبه، والأفضل السر، وإذا كان الأصلح الجهر يجهر، إذا كان أخشع لقلبه يجهر يجهر، وإن كان أخشع لقلبه السر فهو السر، يعمل ما هو الأصلح. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15974/كيفية-القراءة-في-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58934.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17175,"question":"يقول في الحديث: من أدرك الركوع؛ فقد أدرك الركعة وفي حديثٍ آخر يقول: لا صلاة لمن لم يقرأ بفاتحة الكتاب كيف الجمع بين الحديثين؟","title":"حكم قراءة الفاتحة للمأموم ومن أدرك الركوع","answer":"الجواب: الجمع بينهما؛ أن من أدرك الركوع أدرك الركعة، وهو معذور؛ لأنه ما أدرك القيام حتى يقرأ، والنبي ﷺ لما ذكر له أبو بكرة أنه أدرك الركوع لم يأمره بقضاء الركعة، دل على أن الفاتحة تسقط عنه إذا لم يدرك إلا الركوع، وهكذا لو نسيها المأموم، أو جهل؛ تسقط عنه، وتجزئه الركعة، ولكنها ركن في حق الإمام، والمنفرد لابد منها. أما المأموم تسقط عنه إذا جهل، أو نسي، أو جاء والإمام راكع. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15993/حكم-قراءة-الفاتحة-للماموم-ومن-ادرك-الركوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59004.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17312,"question":"ما حكم المداومة على سور مخصوصة في نوافل مخصوصة كسورتي المسد، والكافرون في ركعتي الفجر مثلًا؟ جزاكم الله خيرًا.","title":"حكم المداومة على قراءة سور معينة في نوافل معينة","answer":"الجواب: لا حرج في مداومة القراءة بسور معينة إذا كان يعتقد أنه لا بأس بخلافها، لكن لكونه يحفظها، أو لكونها أسهل عليه، لا بأس بذلك، أما إذا كان يعتقد أنه لا يجوز غيرها فلا يجوز، أما إذا كان لا، يقرؤها؛ لأنها أسهل عليه، يحفظها، أو لأنها قصيرة فلا بأس بذلك، ولا حرج، كان النبي ﷺ يقرأ في سنة المغرب وفي سنة الفجر وفي سنة الطواف يقرأ فيها: قُلْ يَاأَيُّهَا الْكَافِرُونَ و قُلْ هُوَ اللَّهُ أَحَدٌ وهكذا كان يقرأ في سنة المغرب قُلْ هُوَ اللَّهُ أَحَدٌ و قُلْ هُوَ اللَّهُ أَحَدٌ، وكان يقرأ في الوتر سبح، والغاشية و قُلْ هُوَ اللَّهُ أَحَدٌ في الثلاث الأخيرة، يقرأ بسبح في الأولى من الثلاث الأخيرة، ثم الغاشية في الثانية ثم قُلْ هُوَ اللَّهُ أَحَدٌ في الثالثة بعد الفاتحة، كل هذا لا حرج فيه، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16174/حكم-المداومة-على-قراءة-سور-معينة-في-نوافل-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83311.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17326,"question":"ما حكم المداومة على سور مخصوصة في نوافل مخصوصة كسورتي المسد، والكافرون في ركعتي الفجر مثلًا؟ جزاكم الله خيرًا.","title":"حكم المداومة على قراءة سور معينة في نوافل معينة","answer":"الجواب: لا حرج في مداومة القراءة بسور معينة إذا كان يعتقد أنه لا بأس بخلافها، لكن لكونه يحفظها، أو لكونها أسهل عليه، لا بأس بذلك، أما إذا كان يعتقد أنه لا يجوز غيرها فلا يجوز، أما إذا كان لا، يقرؤها؛ لأنها أسهل عليه، يحفظها، أو لأنها قصيرة فلا بأس بذلك، ولا حرج، كان النبي ﷺ يقرأ في سنة المغرب وفي سنة الفجر وفي سنة الطواف يقرأ فيها: قُلْ يَاأَيُّهَا الْكَافِرُونَ و قُلْ هُوَ اللَّهُ أَحَدٌ وهكذا كان يقرأ في سنة المغرب قُلْ هُوَ اللَّهُ أَحَدٌ و قُلْ هُوَ اللَّهُ أَحَدٌ، وكان يقرأ في الوتر سبح، والغاشية و قُلْ هُوَ اللَّهُ أَحَدٌ في الثلاث الأخيرة، يقرأ بسبح في الأولى من الثلاث الأخيرة، ثم الغاشية في الثانية ثم قُلْ هُوَ اللَّهُ أَحَدٌ في الثالثة بعد الفاتحة، كل هذا لا حرج فيه، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16174/حكم-المداومة-على-قراءة-سور-معينة-في-نوافل-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83311.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17386,"question":"من السودان المستمع (م. م) رسالة وضمنها سؤالين، في سؤاله الأول يقول: هل أقرأ البسملة في السورة التي تلي الفاتحة في الصلاة السرية؟ أم لا تجب؟","title":"ما حكم قراءة البسملة في الصلاة؟","answer":"الجواب: السنة أن تقرأ التسمية في الفاتحة، وفي السور جميعًا، في السرية والجهرية، لكن في الجهرية تسر بها أفضل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16287/ما-حكم-قراءة-البسملة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83516.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17396,"question":"من السودان المستمع (م. م) رسالة وضمنها سؤالين، في سؤاله الأول يقول: هل أقرأ البسملة في السورة التي تلي الفاتحة في الصلاة السرية؟ أم لا تجب؟","title":"ما حكم قراءة البسملة في الصلاة؟","answer":"الجواب: السنة أن تقرأ التسمية في الفاتحة، وفي السور جميعًا، في السرية والجهرية، لكن في الجهرية تسر بها أفضل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16287/ما-حكم-قراءة-البسملة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83516.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17467,"question":"تقول أختنا: في صلاة العيد نسيت في الركعة الأولى أن أقرأ الفاتحة عندما سكت الإمام، هل علي إعادة هذه الصلاة، أم تجزئ قراءة الإمام عني؟ جزاكم الله خيرًا.","title":"ما حكم من نسي قراءة الفاتحة مع الإمام؟","answer":"الجواب: ما دمت ناسية فقراءة الإمام تكفي، ليس للمأموم أن يدع الفاتحة لا في صلاة العيد، ولا في الفرائض يقرأ الفاتحة، لكن إذا نسيها، أو كان جاهلًا تحملها الإمام، أو لم يأت إلا في الركوع والإمام في الركوع تحملها عنه الإمام، والحمد لله، ولا إعادة عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16335/ما-حكم-من-نسي-قراءة-الفاتحة-مع-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72504.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17597,"question":"يقول: إن والدته لا تحفظ شيئًا من القرآن، ولا تحفظ التشهد، ولا تحفظ شيئًا من الأدعية، حاول تحفظيها شيئًا من ذلك لكنها لم تستطع، ويسأل عن حكم صلاتها؟ جزاكم الله خيرًا.","title":"كيفية صلاة من لا يحفظ شيئًا من القرآن","answer":"الجواب: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، عليها أن تتعلم الفاتحة وتتعلم ما يجب عليها في صلاتها، وإذا لم تعرف الفاتحة تقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، هكذا أمر النبي ﷺ من لا يستطيع الفاتحة أن يسبح ويهلل، لكن مع العناية بها وتوجيهها إلى الخير لعلها إن شاء الله تحفظ.\nفالمقصود في الوقت الحاضر في كل وقت لا تحفظ فيه الفاتحة تسبح الله وتهلله وتكبره ويكفي.. حتى تتعلم، ويجب عليها أن تتعلم، كل إنسان يجب عليه أن يتعلم، كل امرأة يجب عليها أن تتعلم من أخيها من زوجها من معلمة تعلمها، لابد هذا، يجب فيه الصبر والعناية وعدم التساهل لا في حق الرجل ولا في حق المرأة، وأقل شيء فاتحة الكتاب، لا عذر فيها الحمد لله رب العالمين لابد من تعلمها؛ لأنها ركن الصلاة، لكن لو جاء الوقت ولم تعرف المرأة هذه السورة أو الرجل فإنه يقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، ويكفي ويركع، حتى يمن الله عليه بالتعليم بعد ذلك. وعلى أبي الولد وأبي البنت وعلى أخيها وعلى جدها التعاون في هذا، المرأة لابد من تعليمها كالرجل أيضًا، قد يوجد في بعض الرجال من البادية وأشباه البادية من يحتاج إلى ذلك، فالواجب التعلم، وعلى أبيه إلزامه وعلى أخيه الكبير إلزامه.. وهكذا، وهكذا البنت يجب على أمها أن تفهمها وعلى أخيها وعلى أبيها، لابد من التعاون على البر والتقوى، ولابد من الصدق في ذلك والجد في ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16530/كيفية-صلاة-من-لا-يحفظ-شيىا-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84115.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17605,"question":"من أسئلة هذا السائل يا سماحة الشيخ يقول: في الصلاة السرية يصعب علي تلاوة القرآن بالأحكام -أي: بأحكام التجويد- كما في الصلاة الجهرية، ما الحل؟ وهل أنا ملزم في ذلك؟","title":"هل يلزم قراءة القرآن بأحكام التجويد في الصلاة؟","answer":"الجواب: الأمر في هذا واسع، اتباع الأحكام التجويدية ما هو بلازم إنما هو مستحب، فلا بأس أن تقرأ بغير الأحكام التجويدية، إذا قرأته باللسان العربي الحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16533/هل-يلزم-قراءة-القران-باحكام-التجويد-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59413.mp3","categories":["القراءة في الصلاة","القرآن وعلومه"]},{"id":17614,"question":"يسأل عن صلاة المرأة الصلاة الجهرية هل تجهر المرأة أو لا؟","title":"هل تجهر المرأة في الصلاة الجهرية؟","answer":"الجواب: نعم السنة لها الجهر كالرجل في المغرب والعشاء والفجر السنة لها الجهر، في الأولى والثانية من المغرب والأولى والثانية من العشاء وفي صلاة الفجر كالرجل جهرًا لا يشغل من حولها إذا كان حولها مصلين، إذا كان حولها مصلون أو حولها قراء أو نوام تجهر جهرًا لا تشق عليهم، وهكذا الرجل إذا كان يصلي في الليل أو مريض يصلي في بيته الفجر أو العشاء يجهر جهرًا لا يؤذي من حوله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16543/هل-تجهر-المراة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84206.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17628,"question":"يقول: أسمع كثيرًا من الناس يقولون عندما يقرأ الإمام قوله تعالى: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، يقولون: استعنا بالله، وإذا قال: وَلا الضَّالِّينَ [الفاتحة:7]، يقولون: رب اغفر لي ولوالدي، هل هذا صحيح؟","title":"قول المأموم استعنا بالله عند قراءة الإمام (إياك نعبد وإياك نستعين)","answer":"ليس له أصل لا، ينبغي تركه ليس له أصل، فإذا قال: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، يستمر في قراءته ولا يقول: استعنا بالله، ما له أصل لا يبطل الصلاة، الصلاة لا تبطل بذلك لكن غير مشروع هذا، كذلك عند قوله: ولا الضالين، لا يقل: اللهم اغفر لي ولوالدي هذا ما ورد ... يقول: آمين ....... وَلا الضَّالِّينَ [الفاتحة:7] يقول بعدها: آمين. هذا الذي شرعه الله . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16567/قول-الماموم-استعنا-بالله-عند-قراءة-الامام-اياك-نعبد-واياك-نستعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84408.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17697,"question":"السائل يقول: إذا شك المصلي هل قرأ الفاتحة في الركعة الأولى، وهذا الشك حصل في الركعة الثانية ماذا يعمل؟","title":"حكم المصلي إذا شك في قراءة الفاتحة","answer":"الجواب: إذا كان مأموم لا يضره ذلك، إذا كان مأموم لا يضره ذلك والحمد لله يتحمل عنه الإمام، إذا كان تركها جاهلًا أو ناسيًا أو شك في الأمر لا يضره لكن لا يجوز له التعمد تركها بل يلزمه أن يقرأها مع الإمام، هذا هو الصواب.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16648/حكم-المصلي-اذا-شك-في-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77608.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17805,"question":"السائلة التي رمزت لاسمها بـ (أ. م. ع) تقول: هل تقرأ المرأة سرًا في جميع أوقات الصلاة، علمًا بأن السر في محل السر والجهر في محل الجهر من سنن الصلاة؟","title":"كيفية قراءة المرأة في الصلاة الجهرية","answer":"الجواب: المرأة والرجل كلاهما عليهما أن يتحريا السنة فيجهر في المغرب والعشاء والفجر في الأولى، والثانية من المغرب، والأولى والثانية من العشاء، وفي فريضة الفجر، ويسر في الظهر والعصر، وفي الثالثة من المغرب، والثالثة والرابعة من العشاء الرجل والمرأة جميعًا، والمرأة ترفع صوتها إذا كان ما عندها من تخشى في الستر ما عندها إلا النساء أو ما عندها أحد أو ما عندها إلا ..... أو ما عندها إلا محارمها تجهر، وإن كان غير المحارم فإنها ترفع صوتها شيئًا خفيفًا في محل الجهر؛ لأن هذا سنة للجميع الرجال والنساء؛ الجهر والإخفات.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16803/كيفية-قراءة-المراة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77819.mp3","categories":["القراءة في الصلاة","قضايا المرأة"]},{"id":17844,"question":"هل إذا قرأ المسلم سورة الفاتحة خارج الصلاة هل يجب عليه أن يقول: آمين؟","title":"حكم قول: (آمين) آخر الفاتحة","answer":"الجواب: آمين مستحبة في الصلاة، وخارجها، مستحبة ليست واجبة، آمين معناها: استجب، اللهم استجب، فهي سنة مستحبة في الصلاة، وخارجها نعم، وليست واجبة.","link":"https://binbaz.org.sa/fatwas/16837/حكم-قول-امين-اخر-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78003.mp3","categories":["القراءة في الصلاة","القرآن وعلومه"]},{"id":17868,"question":"يسأل ويقول: هل أقرأ الفاتحة خلف الإمام؟ أم لا؟","title":"هل يجب قراءة الفاتحة خلف الإمام؟","answer":"الجواب: الواجب أن تقرأها خلف الإمام لقول النبي ﷺ في الحديث الصحيح: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم. قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها، فهذا يدلنا على أنه يقرأ خلف الإمام الفاتحة، ثم ينصت، ولا يقرأ زيادة عليها إلا في السرية كالظهر والعصر يقرأ زيادة في الأولى والثانية على الفاتحة؛ لأنه لا يسمع شيئًا.\nأما في العشاء والمغرب والفجر فإنه يكتفي بالفاتحة ولا يزيد عليها، بل يستمع لقراءة إمامه، فإن جاء متأخرًا ولم يدرك إلا الركوع ما أمداه على الفاتحة أجزأه ذلك والحمد لله على الصحيح عند جمهور أهل العلم، وهكذا لو قد ترك الفاتحة جهلًا منه وهو مع الإمام أو نسيانًا أجزأته ركعته كالذي جاء والإمام راكع يجزئه ذلك للعذر الشرعي. فهي في حقك واجبة بخلاف الإمام والمنفرد فإنها ركن في حقهما، أما في حق المأموم فوجوبها أسهل، ولهذا لم يأمر النبي ﷺ من أدرك الإمام راكعًا أن يقضي الركعة، النبي ﷺ قال: زادك الله حرصًا ولا تعد لما ركع دون الصف ثم دخل في الصف خوفًا أن تفوته الركعة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16874/هل-يجب-قراءة-الفاتحة-خلف-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_845/nour_84502.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":17987,"question":"إذا صلى الإنسان ولم يتذكر ما قرأ في الركعة الأولى أو الثانية فما حكم صلاته؟","title":"حكم من نسي ما قرأه في الصلاة","answer":"الجواب: إذا كان ذلك بعد النهاية أو بعد فراغه منها ما يضره، نعم. إنما إذا كان في أثنائها وشك هل قرأ الحمد أو ما قرأ الحمد يعيدها إلا إذا كان عنده وسواس يترك هذا، يبني على ظنه أنه قرأها والحمد لله، وأما إذا كان لا. يعرض له ذلك هل عرض له شيء عارض توقف، هل قرأ الفاتحة أو ما قرأها؟ يقرؤها، أما بعدما فرغ منها إذا طرأ عليه الشك لا يلتفت إليه، هذا من الوساوس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17029/حكم-من-نسي-ما-قراه-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84915.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18007,"question":"من أختنا في الإسلام (خ. و. خ) رسالة وضمنتها بعض الأسئلة تقول في أحدها:قرأت في كتاب الأذكار للنووي أن الإسرار في القراءة والأذكار المشروعة في الصلاة لابد فيه من أن يسمع الإنسان نفسه، فإن لم يسمعها لم تصح قراءته ولا ذكره، فهل تعتبر صلاتي غير صحيحة؛ لأنني عندما أقرأ في الصلاة السرية أحرك شفتي دون صوت وذلك لجهلي؟ جزاكم الله خيرًا.","title":"حكم إسماع الإنسان نفسه بالقراءة في الصلاة","answer":"الجواب: لابد من تحريك اللسان، ولابد من صوت وإلا ما يسمى قارئًا، ما دام في قلبه فقط ما يسمى قارئًا، لابد من شيء عند القراءة والذكر حتى يسمى ذاكرًا ويسمى قارئًا، ولا يكون ذلك إلا باللسان، بل لابد من كونه يسمع نفسه، إلا إذا كان به صمم فهو معذور يعمل ما يقرأ حسب اجتهاده الذي يظن أنه حصل به المطلوب والحمد لله، ولكن كونه ينوي بقلبه، ويذكر بقلبه ولا يتكلم بلسانه ما يسمى قارئًا ولا يسمى داعيًا ولا يسمى ذاكرًا، بل هذا ذاكر بالقلب يسمى ذكر القلب، لكن المأمور في الصلاة أن تقرأ كما أمرك الرسول ﷺ تقرأ، وكذلك المأمور في الدعاء أن تدعو ولا تسمى داعيًا ولا قارئًا إلا إذا تلفظت. نعم. المقدم: جزاكم الله خيرًا. الذي يذكر الله بقلبه هل يعتبر ذاكرًا سماحة الشيخ؟ الشيخ: نعم، ذكر قلب. المقدم: ذكر قلب؟ الشيح: نعم؛ لأن الذكر أنواع ثلاثة: ذكر القلب، وذكر اللسان، وذكر العمل. فإذا ذكر الله بقلبه بخوف وتعظيم تذكر عظمته وخوفه ورجاءه والشوق إليه  ومحبته هذا ذكر بالقلب، وذكر اللسان سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر ونحو ذلك، وذكر العمل كونه يصلي، كونه يصوم، يتصدق، يرجو ثواب الله، هذا ذكر بالعمل مع القلب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17041/حكم-اسماع-الانسان-نفسه-بالقراءة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84922.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18010,"question":"إذا صلى الإنسان ولم يتذكر ما قرأ في الركعة الأولى أو الثانية فما حكم صلاته؟","title":"حكم من نسي ما قرأه في الصلاة","answer":"الجواب: إذا كان ذلك بعد النهاية أو بعد فراغه منها ما يضره، نعم. إنما إذا كان في أثنائها وشك هل قرأ الحمد أو ما قرأ الحمد يعيدها إلا إذا كان عنده وسواس يترك هذا، يبني على ظنه أنه قرأها والحمد لله، وأما إذا كان لا. يعرض له ذلك هل عرض له شيء عارض توقف، هل قرأ الفاتحة أو ما قرأها؟ يقرؤها، أما بعدما فرغ منها إذا طرأ عليه الشك لا يلتفت إليه، هذا من الوساوس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17029/حكم-من-نسي-ما-قراه-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84915.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18018,"question":"إذا أدركت الركعة الأخيرة من صلاة المغرب فهل يجوز أن أقرأ في الركعة الأخيرة سورة مع الفاتحة أو لا؟","title":"حكم قراءة سورة مع الفاتحة لمن أدرك ركعة من المغرب","answer":"الجواب: تقرأ في الركعة الثانية، إذا قمت تقضي تقرأ في الركعة التي تبدأ بها في القضاء الفاتحة وسورة معها أفضل، ثم الركعة الأخيرة السورة فقط، وهي الثالثة في حقك، وإن قرأت معها زيادة فلا حرج، ثبت عن الصديق  أنه كان يقرأ بعد الفاتحة في الثالثة من المغرب رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8]. وقد ثبت عن بعض أمراء الأنصار الذين أمرهم النبي ﷺ أنه كان يقرأ بأصحابه بعد الفاتحة قل هو الله أحد في كل ركعة مع الزيادة عليها في الركعة الأولى والثانية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17060/حكم-قراءة-سورة-مع-الفاتحة-لمن-ادرك-ركعة-من-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85011.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18019,"question":"إذا أدركت الركعة الأخيرة من صلاة المغرب فهل يجوز أن أقرأ في الركعة الأخيرة سورة مع الفاتحة أو لا؟","title":"حكم قراءة سورة مع الفاتحة لمن أدرك ركعة من المغرب","answer":"الجواب: تقرأ في الركعة الثانية، إذا قمت تقضي تقرأ في الركعة التي تبدأ بها في القضاء الفاتحة وسورة معها أفضل، ثم الركعة الأخيرة السورة فقط، وهي الثالثة في حقك، وإن قرأت معها زيادة فلا حرج، ثبت عن الصديق  أنه كان يقرأ بعد الفاتحة في الثالثة من المغرب رَبَّنَا لا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8]. وقد ثبت عن بعض أمراء الأنصار الذين أمرهم النبي ﷺ أنه كان يقرأ بأصحابه بعد الفاتحة قل هو الله أحد في كل ركعة مع الزيادة عليها في الركعة الأولى والثانية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17060/حكم-قراءة-سورة-مع-الفاتحة-لمن-ادرك-ركعة-من-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85011.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18033,"question":"تسأل أختنا وتقول: هل يلزم الالتزام بالاستعاذة والبسملة في كل ركعة من ركعات الصلاة، أم يكفي ذلك في الركعة الأولى؟","title":"حكم الاستعاذة والبسملة في كل ركعة","answer":"الجواب: أما التسمية: فالسنة في كل الركعات، إذا كانت تقرأ سورة مستقلة تسمي قبلها. وأما الاستعاذة: سنة في الركعة الأولى، أما الركعات الأخرى اختلف فيها العلماء، هل تشرع الاستعاذة أم لا، فمن استعاذ فلا بأس، ومن ترك فلا بأس، في الركعات الأخرى، لكن تشرع الاستعاذة في الركعة الأولى بالتأكيد، وهكذا التسمية، وأما في الركعات الأخرى فإن المصلي يسمي رجل أو امرأة يسمي إذا افتتح سورة، أما إذا كان يقرأ بعض آيات؛ فلا حاجة إلى تسمية، تكفي التسمية الأولى عند قراءته للفاتحة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17063/حكم-الاستعاذة-والبسملة-في-كل-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_599/59909.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18200,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة يقول محمد فضل الله عبد القادر سوداني، من الدويم، أخونا له جمع من الأسئلة نستطيع أن نعرض منها هذا السؤال، يقول: عندنا إمام يصلي بنا، ولكنه لا يقرأ في صلاة الجمعة إلا الغاشية والأعلى، فهل هذا العمل صحيح؟ وهل من نصيحة للأئمة حول ذلك، جزاكم الله خيرًا.الشيخ: أعد المقدم: يقول: لدينا إمام يصلي بنا، ولكنه لا يقرأ في صلاة الجمعة إلا الغاشية والأعلى، فهل يصح هذا؟ وهل من نصيحة له ولبقية الأئمة؟ جزاكم الله خيرًا.","title":"حكم المداومة على قراءة سورتي الأعلى والغاشية في الجمعة","answer":"الجواب: هذا سنة، هذا العمل سنة، النبي ﷺ قرأ بـ(سبح اسم ربك الأعلى) في الركعة الأولى من الجمعة وقرأ بالغاشية، لكن المداومة عليها أمر لا ينبغي، بل ينبغي أن يقرأ بغيرهما بعض الأحيان كالجمعة والمنافقين فإن النبي قرأ بهما في الجمعة أيضًا عليه الصلاة والسلام قرأ بالجمعة والمنافقين في الركعتين بعد الفاتحة، وقرأ بسبح والغاشية في الركعتين، وقرأ أيضًا بالجمعة وهل أتاك حديث الغاشية، فالمحفوظ عنه ﷺ ثلاث صور يعني: ثلاثة أنواع: النوع الأول: سبح في الأولى والغاشية في الثانية بعد الفاتحة. النوع الثاني: الجمعة في الأولى والمنافقون في الثانية. النوع الثالث: الجمعة في الأولى والغاشية في الثانية. نعم. المقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17237/حكم-المداومة-على-قراءة-سورتي-الاعلى-والغاشية-في-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_907/nour_90706.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18299,"question":"هل لي أن أجهر في غير الصلاة الجهرية؟","title":"حكم الجهر في الصلاة السرية","answer":"الجواب: السنة السر، لكن لو جهرت ببعض الآيات لا بأس، كان النبي ﷺ يسمعهم الآية أحيانًا في الظهر والعصر، لكن الأفضل في الظهر والعصر السر، وفي الليل الجهر، وفي الفجر الجهر، لكن لو أن الإنسان جهر في بعض الآيات في الظهر والعصر، فلا بأس، يسمعهم بعض الآيات كما فعل النبي ﷺ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17350/حكم-الجهر-في-الصلاة-السرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_912/nour_91214.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18322,"question":"تقول: صليت صلاة الفجر، وقرأت بعد سورة الفاتحة، في الركعة الثانية الجزء الأخير من سورة النبأ، وبعد إكمالي للصلاة، اكتشفت أنني دمجت مع سورة النبأ آيات من سورة النازعات، وأنا كنت على يقينٍ بأنني أقرؤها بسورة صحيحة، وأنا أثناء الصلاة، وسؤالي هو: هل علي إثم في ذلك؟","title":"هل يأثم من اختلطت عليه الآيات فقرأ من عدة سور؟","answer":"الجواب: لا حرج، لا حرج ... كونه يقرأ من النبأ، ثم دخلت عليه آيات من النازعات، أو من غيرها؛ لا حرج في ذلك والحمد لله. نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17375/هل-ياثم-من-اختلطت-عليه-الايات-فقرا-من-عدة-سور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73208.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18337,"question":"يقول السائل: هل عدم تحريك اللسان والشفتين في الصلاة تبطل الصلاة؟","title":"حكم عدم تحريك اللسان والشفتين في الصلاة","answer":"الجواب: لابد من قراءة الفاتحة، والقراءة لابد من تحريك اللسان حتى يسمع قراءته حتى يكون منه قراءه، لابد من القراءة بالحروف التي يسمعها. نعم. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/17391/حكم-عدم-تحريك-اللسان-والشفتين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91320.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18338,"question":"هذه سائلة مقيمة بجدة تقول: هل يجوز حمل المصحف أثناء صلاة قيام الليل والتراويح للقراءة منه؟","title":"حكم القراءة من المصحف في قيام الليل","answer":"الجواب: لا حرج لو قرأ في المصحف في التراويح والتهجد، لا مانع، كان مولى عائشة ذكوان يصلي بها ويقرأ من المصحف رضي الله عنهما. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17394/حكم-القراءة-من-المصحف-في-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91321.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18363,"question":"السائل حمدي مصري، ومقيم بالرياض، يقول سماحة الشيخ: لماذا شرع الجهر بالتلاوة في صلاة المغرب والعشاء والفجر دون بقية الفرائض؟ وما الدليل على ذلك؟","title":"الحكمة من الجهر بالقراءة في بعض الفرائض","answer":"الجواب: الله أعلم، لكن يغلب على الظن -والله أعلم- أن هذه الأوقات يكون فيها الاستماع متيسرًا، والفهم في المغرب، والعشاء، والفجر؛ فينتفع المأمومون بالقراءة، بخلاف الظهر والعصر؛ فإنها أوقات مشاغل بحاجات الدنيا، وقد لا يكون عندهم من الاستماع، والإنصات، والفهم ما عندهم في المغرب، والعشاء، والفجر، فمن حكمة الله أن جعل القراءة سرية حتى يتأمل هذا، ويتأمل هذا، الإمام يقرأ ويتأمل، والمأموم كذلك، بخلاف المغرب والعشاء؛ فإن مجيء الليل وأول النهار وقت الراحة، ووقت الهدوء. فالأقرب -والله أعلم- أنه يتيسر لهم من الاستماع، والإنصات، والاستفادة؛ ما لا يتيسر لهم في الصلاتين النهاريتين: الظهر والعصر، والحكمة في هذا لله سبحانه، والله هو أحكم وأعلم جل وعلا، هو الحكيم العليم  في ذلك. ولكن الأقرب -والله أعلم- أن هذا هو السر في الجهر في المغرب والعشاء في الأولى والثانية، والجهر في المغرب، والجهر في الجمعة؛ لأنه صلاة يجتمع فيها الناس من كل مكان، من الحكمة أن يجهر فيها بالقراءة، حتى يستمعوا ويستفيدوا، وهكذا صلاة العيد، وصلاة الاستسقاء؛ لأنها صلوات يحصل فيها الاستماع والكثرة، فمن رحمة الله أن شرع فيها الجهر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17418/الحكمة-من-الجهر-بالقراءة-في-بعض-الفراىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78322.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18404,"question":"من أبها السائل (ص. س) بعث بسؤالين، يقول في السؤال الأول: يوجد عندنا إمام نصلي وراءه، وعندما يقرأ سورة الفاتحة نجده لا يفرق في النطق بين الصاد والسين في قوله تعالى: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ[الفاتحة:6] فينطق الصاد سين، فهل علينا حرج؟","title":"حكم إمامة من لا يفرق بين الصاد والسين في الفاتحة","answer":"الجواب: لا حرج في ذلك، ليس بحرج (الصراط المستقيم) ولو ما أفصحها كثيرًا، لأن السين تدل على الصاد، فالأفضل أن يعتني بهذا، وإذا صار فيها شيء من الخفاء واشتبهت الصاد بالسين فلا يضر. نعم.","link":"https://binbaz.org.sa/fatwas/17473/حكم-امامة-من-لا-يفرق-بين-الصاد-والسين-في-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78412.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18517,"question":"السؤال الأخير لأخواتنا من ليبيا: هل يجوز للمرأة أن تصلي جهرًا في صلاة الجهر عندما تتأكد أنه لا يوجد شخص أجنبي عليها قد يسمعها؟ وما هو دليل ذلك؟","title":"حكم جهر المرأة بالقراءة في الصلاة الجهرية","answer":"الجواب: الله شرع لعباده الجهر في الفجر، وفي الأولى والثانية من العشاء والمغرب، وهذا عام للرجال والنساء؛ لأن الشرائع عامة إلا ما خصه الدليل بالرجل أو بالمرأة. فالله شرع أن نجهر في الفجر وفي الأولى والثانية من المغرب وفي الأولى والثانية من العشاء، فالمرأة كذلك تجهر جهرًا يفيدها وينفع من حولها، وإذا كان حولها رجال أجناب فالأفضل عدم الجهر لها؛ لأن الرجل قد يفتن بصوتها، فالأفضل لها عدم الجهر، وهكذا في التلبية في الحج والعمرة إذا كان حولها رجال، فالأفضل عدم الجهر، وإن جهرت فلا حرج، لكن الأفضل هو عدم الجهر، نعم.","link":"https://binbaz.org.sa/fatwas/17622/حكم-جهر-المراة-بالقراءة-في-الصلاة-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_869/nour_86906.mp3","categories":["القراءة في الصلاة","قضايا المرأة"]},{"id":18558,"question":"رسالة وصلت إلى البرنامج من المستمع عيد سعيد بغيم الميزاني المطيري أخونا يسأل في أحد أسئلته سؤالًا يقول فيه: إذا قرأ الإمام سورة الفاتحة جهرًا، وانتهى منها، وبدأ في قراءة سورة بعدها، فهل يجوز للمأموم أن يقرأ سورة الفاتحة؟","title":"حكم قراءة المأموم للفاتحة إذا لم يسكت الإمام","answer":"الجواب: نعم، الواجب على المأموم أن يقرأ الفاتحة، قد ذهب بعض أهل العلم إلى أن القراءة لا تجب على المأموم، ولكن الصواب أنها تجب عليه، فالواجب عليه الفاتحة فقط، ولو كان الإمام يقرأ ما سكت يقرؤها، ثم ينصت؛ لقول النبي ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب متفق على صحته؛ ولقوله ﷺ: لعلكم تقرؤون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها فهذا هو الصواب إلا إذا لم يدرك الإمام في القيام أدركه في الركوع، أو عند الركوع ما تمكن من القراءة، فإن الصواب أنه يعفى عنه، في هذه الحالة، وتجزئه الركعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17668/حكم-قراءة-الماموم-للفاتحة-اذا-لم-يسكت-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_916/nour_91609.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18752,"question":"إذا سها الإنسان في صلاته فقرأ سورة الفاتحة دون أن يتدبرها، ولم يتذكر ذلك إلا بعد الانتهاء من قراءتها، وأحيانًا لا يدري: هل قرأ سورة الفاتحة أم لا، وهذا كله أثناء الصلاة رغم اجتهاده، فهل عليه يا سماحة الشيخ أن يعيد قراءة ذلك، أم لا يجوز له ذلك؟ وما العمل في هذه الحالة؟","title":"حكم من قرأ الفاتحة بغير تدبر في الصلاة","answer":"الجواب: إذا كان الشيء عارضًا يعيد إذا شك: هل قرأ الفاتحة أو ما قرأت يقرأها، أما إذا كان معه وساوس يكثر معه ذلك يطرح الوساوس، ويبني على أنه قرأها، ويترك الوسوسة، ويتعوذ بالله من الشيطان، ولا يعيدها؛ لأن الشيطان حريص على إفساد أعمال بني آدم، فإذا كان هذا شيئًا عارضًا فإنه يعيدها، يقرؤها حتى يتحقق أنه قرأها، أما إذا كان وسوسة هذا يترك ذلك، إذا وقع عليه هذه الوساوس يبني على أنه قرأها، ولا يعيدها، والحمد لله. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17868/حكم-من-قرا-الفاتحة-بغير-تدبر-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79003.mp3","categories":["القراءة في الصلاة"," الوسواس بأنواعه"]},{"id":18820,"question":"السائل أبو محمد يقول من أسئلته: هناك أناس لا يرفعون أصواتهم بقول: آمين بعد وَلا الضَّالِّينَ[الفاتحة:7] فما هو الأفضل في ذلك رفع الصوت أم خفضه؟","title":"حكم رفع الصوت بقول: (آمين) في الصلاة","answer":"الجواب: السنة رفع الصوت، كان الصحابة يؤمنون خلف النبي ﷺ ويرفعون أصواتهم، فالسنة إذا قال الإمام: آمين، يقول المأموم مثله: آمين؛ لقوله ﷺ: إذا أمن الإمام فأمنوا، وقال ﷺ: إذا قال: وَلا الضَّالِّينَ فقولوا: آمين. المقدم: اللهم صل وسلم على رسولنا محمد.","link":"https://binbaz.org.sa/fatwas/17946/حكم-رفع-الصوت-بقول-امين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79121.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18845,"question":"يقول: إنني إذا صليت النوافل لا أقرأ إلا الفاتحة؛ لأنني لا أحفظ من القرآن إلا شيئًا يسيرًا، فهل ما فعلته صحيحًا؟","title":"حكم الاكتفاء بالفاتحة في صلاة النافلة","answer":"الجواب: نعم، الفاتحة كافية، الفاتحة كافية في الفرض والنفل، لكن إذا زدت عليها من بعض الآيات أو السور القصيرة مثل: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] وإِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ [الكوثر:1] وأشباه ذلك فهذا أفضل، وإن اقتصرت على الفاتحة أجزأ ذلك، والحمد لله، حتى في الفرض، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17975/حكم-الاكتفاء-بالفاتحة-في-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73609.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18902,"question":"إذا كان قائم الليل لا يحفظ من القرآن إلا سورًا قليلة، فهل يجوز له قراءة السور متتابعة في ركعة واحدة؟","title":"حكم قراءة أكثر من سورة في ركعة واحدة","answer":"الجواب: لا مانع من ذلك، يقرأ ما يسر الله له، وإن قرأ في المصحف فلا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/18043/حكم-قراءة-اكثر-من-سورة-في-ركعة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92308.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18905,"question":"السؤال الأخير لأخواتنا من ليبيا: هل يجوز للمرأة أن تصلي جهرًا في صلاة الجهر عندما تتأكد أنه لا يوجد شخص أجنبي عليها قد يسمعها، وما هو دليل ذلك؟","title":"حكم رفع المرأة صوتها في الصلوات الجهرية","answer":"الجواب: الله شرع لعباده الجهر في الفجر وفي الأولى والثانية من العشاء والمغرب، وهذا عام للرجال والنساء؛ لأن الشرائع عامة، إلا ما خصه الدليل بالرجل أو بالمرأة، فالله شرع أن نجهر في الفجر، وفي الأولى والثانية من المغرب، وفي الأولى والثانية من العشاء. فالمرأة كذلك تجهر جهرًا يفيدها وينفع من حولها، وإذا كان حولها رجال أجناب؛ فالأفضل عدم الجهر لها؛ لأن الرجل قد يفتن بصوتها، فالأفضل لها عدم الجهر، وهكذا في التلبية في الحج والعمرة؛ إذا كان حولها الرجال، فالأفضل عدم الجهر، وإن جهرت فلا حرج، لكن الأفضل هو عدم الجهر، نعم.","link":"https://binbaz.org.sa/fatwas/18052/حكم-رفع-المراة-صوتها-في-الصلوات-الجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_881/nour_88105.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18943,"question":"يقول السائل: إذا قرأ الإمام في الركعة الأولى سورة بعد الفاتحة، ثم قرأ نفس السورة في الركعة الثانية، فقال له أحد المصلين: (سبحان الله) ماذا على الإمام أن يفعل؟ وهل يسجد للسهو؟","title":"حكم تكرار السورة في الركعتين بعد الفاتحة","answer":"الجواب: لا حرج أن يكررها في الركعة، قد ثبت عن النبي ﷺ أنه كرر سورة إِذَا زُلْزِلَتِ [الزلزلة: 1] في الركعتين، فلا حرج أن يقرأ سورة ويكررها في الركعتين، أو آيات، نعم.","link":"https://binbaz.org.sa/fatwas/18143/حكم-تكرار-السورة-في-الركعتين-بعد-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88242.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":18961,"question":"هذا المستمع للبرنامج سعد عبد الوهاب من خميس مشيط يقول: عندما ينام الشخص عن صلاة الفجر، وفي حالة استيقاظه؛ يصلي فهل يجهر في صلاته أم تكون الصلاة سرية، وهل يصلي الراتبة قبل ذلك أم بعدها؟ أفتونا عن هذا السؤال.","title":"الجهر في صلاة الفجر لمن استيقظ متأخرًا","answer":"الجواب: نعم إذا استيقظ ولو بعد الشمس يصلي الراتبة، ويصلي الفريضة، ويجهر كما لو فعلها في الوقت؛ لأن النبي ﷺ في بعض أسفاره نام هو والصحابة عن الفجر، فلم يستيقظوا إلا بحر الشمس، فلما استيقظوا أمر بالأذان فأذن المؤذن، وصلى الراتبة، وأقام الصلاة، وصلى الفريضة، وجهر فيها كما كان يفعل في وقتها، هذا هو السنة إذا نام عنها، واستيقظ بعد الشمس يتوضأ، ويصلي الراتبة، ويصلي الفريضة، ويجهر فيها كما لو فعلها في الوقت تأسيًا بالنبي -عليه الصلاة والسلام-. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18135/الجهر-في-صلاة-الفجر-لمن-استيقظ-متاخرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79208.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19000,"question":"عند صلاة الجماعة الإمام يقرأ سورة الفاتحة، ويدع لنا فرصة لكي نقرأها نحن أيضًا، ولكنه بعد قليل يبدأ في السورة الصغيرة، ولم نكمل بعد، سؤالي هنا: هل نكمل الفاتحة بسرعة؟ أم نسكت ولا نكمل لكي نستمع إليه جزاكم الله خيرًا؟ وهل يكون جائز بألا نقرأها من بعده، ولو جعل لنا فرصة؛ لأنه هو قد قرأها عنا؟","title":"هل لو شرع الإمام في القراءة بعد الفاتحة، نكمل الفاتحة؟","answer":"الجواب: الواجب على المأموم أن يقرأ الفاتحة في السرية والجهرية في أصح أقوال العلماء، وقال بعض أهل العلم: أنه لا يقرأ في الجهرية، ويقرأ في السرية. وقال بعضهم: لا قراءة عليه لا في السرية، ولا في الجهرية، بل يتحملها الإمام. وكلا القولين ضعيف، والصواب: أنه يقرأ في السرية والجهرية. في السرية يقرأ الفاتحة، ويقرأ معها ما تيسر في الأولى والثانية، من الظهر والعصر، وفي الجهرية كالعشاء، والمغرب، والفجر، والجمعة، يقرأ فقط بالفاتحة، ثم ينصت لإمامه، فإن كان للإمام سكوت قرأ في السكتة، سكتة إمامه. وإن بدأ الإمام بالقراءة ولم يكمل كمل، كملها ثم أنصت، ولو كان الإمام لا يسكت فإنه يقرؤها بينه وبين نفسه ثم ينصت لإمامه لقول النبي ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها هذا صريح في أن المأموم يقرأ الفاتحة خلف الإمام في جميع الصلوات، لكن لو سبق بأن جاء والإمام في الركوع أجزأته الركعة، وسقطت عنه الفاتحة؛ لأنه لم يدرك القيام. وهكذا لو نسي، أو كان جاهلًا بالحكم؛ صلاته صحيحة؛ لأن الفاتحة في حق المأموم واجبة، تسقط بالسهو والجهل. بخلاف الإمام والمنفرد فإنها ركن في حقهما لا بد منها، ولا تسقط لا بالسهو ولا بالجهل لا بد منها.\nأما المأموم فإنها تسقط عنه بالسهو وبالجهل. وهكذا لو لم يدرك القيام جاء والإمام راكع سقطت عنه عند جمهور أهل العلم، وأجزأته الركعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18163/هل-لو-شرع-الامام-في-القراءة-بعد-الفاتحة-نكمل-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_795/nour_79504.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19277,"question":"أختنا تقول: ما رأيكم في طريقتي التالية: أنا أختم القرآن عن طريق الصلاة، فمثلًا آخذ القرآن في يدي وأقرأ، وبهذه الطريقة أختم القرآن في شهرين، هل طريقتي صحيحة؟ جزاكم الله خيرًا.","title":"حكم القراءة من المصحف في الصلاة والمداومة على ذلك","answer":"الجواب: الذي أرى ترك ذلك؛ لأن بعض أهل العلم يرى أن القراءة من المصحف تبطل الصلاة، فلا ينبغي لك ذلك، بل ينبغي أن تقرئي ما تيسر عن ظهر قلب في الفرائض، ولا تقرئي من المصحف؛ لأن هذا أخشع للقلب وأجمع للقلب على القراءة، فاقرئي ما تيسر في صلاتك؛ في الظهر، والعصر، والمغرب والعشاء، أوسط المفصل، ويكون الظهر أطول مثل: هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ، اقْرَأْ بِاسْمِ رَبِّكَ، وَالسَّمَاءِ ذَاتِ الْبُرُوجِ ، سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى، وَالْفَجْرِ .. وما أشبه ذلك. ويكون الظهر أطول، والمغرب يكون أقصر في الغالب، وإذا طولت في المغرب بعض الأحيان فهو أفضل أيضًا؛ لأن الرسول عليه الصلاة والسلام طول فيها بعض الأحيان، وقصر عليه الصلاة والسلام، وفي الفجر يكون أطول من ذلك، مثل قراءة: عم يتساءلون وهل أتى على الإنسان، والمزمل، والمدثر، ق، اقتربت الساعة في الفجر، لأن: الرسول كان يطول فيها عليه الصلاة والسلام، وكان يقرأ فيها بالستين إلى المائة من الآيات، وتقرئين عن ظهر قلب، وعليك أن تجتهدي في حفظ المفصل حتى تستعيني بذلك على القراءة، والمفصل أوله (ق) فأوصيك أن تجتهدي في حفظ المفصل، من (ق) إلى آخر القرآن، حتى تقرئي بهذا في صلاتك. وأما المصحف فالذي أوصيك به ترك ذلك إلا في التراويح وقيام رمضان، إذا طولت فلا بأس، أن تقرئي من المصحف، كانت عائشة رضي الله عنها يصلي بها مولاها من المصحف في رمضان، فلا بأس بذلك، أما الفرائض فأوصيك وأوصي غيرك أن تكون القراءة عن ظهر قلب، مما يسر الله من القرآن. وأوصي الجميع بحفظ المفصل من (ق) إلى آخره، أوصي الرجال والنساء والشباب والفتيات، أوصي الجميع بحفظ المفصل على الأقل؛ لأنه يعين على القراءة في الصلاة، ومن تيسر له حفظ أكثر من ذلك، أو حفظ القرآن كله، فهذا خير إلى خير ونعمة عظيمة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18455/حكم-القراءة-من-المصحف-في-الصلاة-والمداومة-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89202.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19284,"question":"أختنا تسأل وتقول: هل يجوز حمل القرآن في الصلاة وقراءته، وعدم الترتيب أيضًا في قراءة السور ؟","title":"حكم القراءة من المصحف في الصلاة وعدم ترتيب الآيات","answer":"الجواب: لا حرج في ذلك، إذا دعت الحاجة إلى ذلك كما في صلاة التراويح والقيام، إذا قرأ من المصحف لا حرج في ذلك، والأفضل أن يرتب الآيات، ولا يخل بذلك، فإن قرأ بعض آيات في ركعة وآيات أخرى؛ لأنه ما يحفظ إلا ذلك، أو لأن قراءته لبعض الآيات غير مستقيمة، فيقرأ الآيات قراءة مستقيمة، والتي يعجز عنها يؤخرها فلا بأس بذلك. المقصود أنه لا حرج إذا كان لمصلحة شرعية، أن يقرأ بعض الآيات ويترك بعض الآيات؛ لأنه يقيم هذه الآيات وقد درسها وحفظها، ولأنه لا يستطيع يقيم الآيات الأخرى؛ لأنه ما درسها كما ينبغي؛ أو لأنه يحفظ هذه ولا يحفظ هذه، كل ذلك لا حرج فيه. المقدم: بارك الله فيكم، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/18491/حكم-القراءة-من-المصحف-في-الصلاة-وعدم-ترتيب-الايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_893/nour_89308.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19341,"question":"السؤال الثاني يقول فيه: هل تصح صلاة من نسي البسملة في قراءة الفاتحة؟","title":"حكم نسيان البسملة في قراءة الفاتحة أثناء الصلاة","answer":"الجواب: نعم، البسملة ليست من الفاتحة آية مستقلة، يشرع المجيء بها عند قراءة الفاتحة وعند قراءة كل سورة من القرآن يقرأ في أولها: بسم الله الرحمن الرحيم إلا سورة البراءة فليس أمامها بسملة، فإذا بدأ يبدأ بالتعوذ يقول: أعوذ بالله من الشيطان الرجيم ويقرأ، وأما بقية السور وهي مائة وثلاثة عشر سورة ما عدا سورة التوبة فإنه يقرأ في أولها: بسم الله الرحمن الرحيم.","link":"https://binbaz.org.sa/fatwas/18561/حكم-نسيان-البسملة-في-قراءة-الفاتحة-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_899/nour_89906.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19514,"question":"يقول أيضًا يا فضيلة الشيخ! هل يجوز أيضًا أن يقرأ الإمام أي سورة مثل الضحى، أو الشمس، أو الليل ويكررها، وكذلك إذا قرأ سورة، وقرأ معها سورة الإخلاص، هل هذا سنة؟","title":"حكم تكرار قراءة السورة في الصلاة، وحكم قراءة سورتين","answer":"الجواب: كل ذلك لا بأس به، والحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18755/حكم-تكرار-قراءة-السورة-في-الصلاة-وحكم-قراءة-سورتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94606.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19529,"question":"يقول هذا السائل سماحة الشيخ: إذا قرأ الإمام في الركعة الأولى سورة الفاتحة، ثم قرأ نفس السورة في الركعة الثانية، وقال أحد المصلين: سبحان الله، فماذا على الإمام أن يفعله؟ وهل يسجد للسهو؟","title":"حكم تكرار السورة في عدة ركعات","answer":"الجواب: لا ما يسجد، لو كررها ما في بأس، الحمد لله، قد ثبت أن النبي ﷺ كرر السورة في ركعتين، لا بأس، إذا قرأها في الأولى والثانية، ولو ساهيًا ما عليه سجود سهو؛ لأن هذا أمر مشروع. المقدم: جزاكم الله خيرًا يا سماحة الشيخ!","link":"https://binbaz.org.sa/fatwas/18776/حكم-تكرار-السورة-في-عدة-ركعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93938.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19551,"question":"أختنا تقول: إنني أحفظ بعض السور الطوال، مثل سورة البقرة وسورة آل عمران، وحرصًا مني على عدم نسيانها فإنني أقرأ بعض الآيات منها في الصلوات المكتوبة والسنن، ولكنني أخطئ كثيرًا وأتجاوز بعض الآيات أحيانًا، وذلك لنسياني لها، فهل يجوز لي قراءة هذه السور؟ أم أتركها وأقرأ السور القصار؟","title":"حكم القراءة في الصلاة من السور الطوال مع الخطأ","answer":"الجواب: لا بأس بذلك أن تقرئي من سورة البقرة بعض الآيات أو سورة آل عمران أو غيرهما لا بأس بذلك بعد الفاتحة ولو أخطأت في بعض الآيات، نسيت بعض الآيات يكفي قراءة ما ذكرت منها وحفظت منها ولا حرج في ذلك. وإن قرأت بالقصار من السور فحسن، ولكن الأمر في هذا واسع؛ لأن الله سبحانه يقول: فَاقْرَءُوا مَا تَيَسَّرَ مِنْهُ [المزمل:20]، والنبي  يقول: ثم اقرأ بما تيسر معك من القرآن. فإذا قرأت من سورة البقرة، أو من سورة النساء، أو من سورة آل عمران، أو غيرها، كل ذلك لا بأس به، تقرئين ما حفظت، ولو كانت غير متوالية آيات غير متوالية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18791/حكم-القراءة-في-الصلاة-من-السور-الطوال-مع-الخطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_940/nour_94005.mp3","categories":["القراءة في الصلاة","قضايا المرأة"]},{"id":19580,"question":"تقول السائلة من القصيم البدائع سماحة الشيخ: بأنها تحفظ السور القصيرة، وتقول: بأني أحفظ شيئًا من القرآن الكريم آيات مثل أول البقرة، وآية الكرسي، وآخر سورة البقرة، وأول سورة الصافات، وآخر سورة الحشر وأول سورة الجن.و هل يجوز لي أن أقرأ مثل هذه الآيات في الصلاة وأنا حفظي يقتصر على السور القصيرة؟","title":"حكم قراءة ما زاد على الفاتحة في الصلاة","answer":"الجواب: نعم، لا بأس، الله يقول: فَاقْرَءُوا مَا تَيَسَّرَ مِنْهُ[المزمل:20] ، تقرأ ما تحفظ من الآيات أو السور في تهجدها، وفي فريضتها ونوافلها، الواجب الفاتحة، وما زاد على هذا فهو مستحب، الركن قراءة الفاتحة، أما ما زاد على ذلك من آيات أو سور كله مستحب، تقرأ ما تيسر من القرآن الذي معها آيات أو سور.","link":"https://binbaz.org.sa/fatwas/18832/حكم-قراءة-ما-زاد-على-الفاتحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94721.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19604,"question":"سؤال آخر لهذا السائل أبو محمد يا سماحة الشيخ! يقول: نسمع البعض من المصلين يقولون بالصلاة الجهرية حين يقول الإمام: ولا الضالين، عند ذلك يقول هذا المصلي داعيًا: اللهم اغفر لي ولوالدي ولأموات المسلمين، ثم يقول مع الإمام: آمين، فهل هذا من السنة خصوصًا بأنه يرفع الصوت ويشوش على المصلين؟","title":"حكم قول: اللهم اغفر لي ولوالدي عند قول الإمام: {ولا الضالين}","answer":"الجواب: هذا غير مشروع، المشروع بعد ولا الضالين أن يقول: آمين، أما قوله: اللهم اغفر لي ولوالدي، ما عليه دليل، ليس بمشروع ولكن بعد قول الإمام ولا الضالين يقول المأموم: آمين، هذا المشروع للمأموم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18871/حكم-قول-اللهم-اغفر-لي-ولوالدي-عند-قول-الامام-ولا-الضالين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94808.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19617,"question":"هذا سائل يقول: سماحة الشيخ أنا أصلي خلف إمام حافظ لكتاب الله  في صلاة التراويح وغيرها من الصلوات الجهرية وأفتح عليه إذا أخطأ، ويقول الإمام: لا تفتح علي في الكلمات القصيرة، فنرجو من سماحتكم التوجيه في ذلك.","title":"حكم الفتح على الإمام في الصلاة","answer":"الجواب: لا، المشروع أن تفتح عليه، ولو قال: لا تفتح علي، إذا غلط يفتح عليه؛ حتى يعلم المصلون الآية التي ترك، والحرف الذي ترك، فالفتح عليه من باب التعاون على البر والتقوى، ولا ينبغي له أن يكره ذلك، بل ينبغي له أن يشكرك.","link":"https://binbaz.org.sa/fatwas/18887/حكم-الفتح-على-الامام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94819.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19642,"question":"يقول: إذا دخل المصلي صلاة الجماعة في الركعة الثالثة أو الرابعة، فهل عليه أن يقرأ فيهما عدا سورة الفاتحة؟","title":"حكم الزيادة على الفاتحة للمسبوق الذي أدرك الثالثة أو الرابعة","answer":"الجواب: الفاتحة تكفي، ولكن إذا تيسر له قراءة الزيادة عليها فلا بأس؛ لأنها أول صلاته، المسبوق هي أول صلاته وما يقضيه هو آخرها، فإذا كان الإمام تأخر بعد الفاتحة وقرأت فهذا أفضل؛ لأنها أول صلاتك، فإن لم يتيسر كفت الفاتحة والحمد لله، ثم تقضي ما فاتك. نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18918/حكم-الزيادة-على-الفاتحة-للمسبوق-الذي-ادرك-الثالثة-او-الرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94929.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]},{"id":19721,"question":"قد يسهو الإنسان في الصلاة، فيسأل: هل قرأت بالفاتحة أم لا، فهل إذا قرأها بعد السورة تعتبر كمن قرأها قبلها، أم كيف يكون الحال؟","title":"السهو في قراءة الفاتحة","answer":"الجواب: إذا كان النسيان عارضًا؛ فإنه يعيدها ولو بعد السورة، أما إن كان مبتلًا بالوساوس، فلا ينبغي أن يلتفت إلى ذلك بل قد قرأها والحمد لله؛ لأن المؤمن يقرؤها من حين ما يقوم من الركعة، ويبدأ بها قبل السورة فلا يلتفت إلى هذه الوساوس، أما إذا كان الوسواس شيء عارض، عارضًا ليس بمعتاد، يعني شك هل قرأها أو ما قرأها؛ فإنه يقرؤها ولو بعد السورة ويكفي.","link":"https://binbaz.org.sa/fatwas/28279/السهو-في-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D8%A7%D9%84%D8%B3%D9%87%D9%88%20%D9%81%D9%8A%20%D9%82%D8%B1%D8%A7%D8%A1%D8%A9%20%D8%A7%D9%84%D9%81%D8%A7%D8%AA%D8%AD%D8%A9.mp3","categories":["القراءة في الصلاة","صلاة الجماعة"]}]
